-- Chroma 0.1.0 -- generated by build/build.py, do not edit
local __modules = {}
local __cache = {}
local function __require(path)
    local hit = __cache[path]
    if hit ~= nil then return hit end
    local factory = __modules[path]
    if not factory then
        error("chroma: unknown module '" .. tostring(path) .. "'", 2)
    end
    local result = factory(__require)
    __cache[path] = result
    return result
end

__modules["core/anim"] = function(require)
-- Two-stage open/close sequencer.
--
-- The window frame keeps AnchorPoint (0, 0) permanently, also its drag
-- origin, so animation and dragging never disagree about where the window
-- is. Everything shrinks Size toward that fixed corner; Position is never
-- touched. The body never moves horizontally: only the frame's Size
-- animates, so the title bar widens/narrows and the frame unfolds/collapses
-- vertically, with no separate contents slide to read as a third motion.
local Guard = require("util/guard")

-- Resolved lazily in M.new: a module-scope game:GetService() runs on
-- require, which breaks the Lua 5.4 test harness the moment any suite
-- requires this file -- the same failure core/cursor.lua hit.
local TweenService

local M = {}

-- Offsets and durations in seconds. Total is 0.33s each way.
--
-- The stages are separated by a 0.05s gap rather than overlapped: each stage
-- finishes before the next begins, so the two read as "bar, then frame"
-- instead of one blended motion. Overlapping felt mushy.
M.TIMING = {
    open = {
        bar    = { delay = 0.00, time = 0.12 },
        height = { delay = 0.17, time = 0.16 },
    },
    close = {
        height = { delay = 0.00, time = 0.14 },
        bar    = { delay = 0.19, time = 0.14 },
    },
}

local EASE_OUT = Enum.EasingStyle.Quint
local EASE_IN = Enum.EasingStyle.Quad

local Anim = {}
Anim.__index = Anim

-- parts: { frame, contents, barHeight, fullSize() }
--
-- The contents frame is positioned once by the window (at title bar height +
-- gap) and never moved again here; only frame.Size animates.
function M.new(root, parts)
    TweenService = TweenService or game:GetService("TweenService")

    local self = setmetatable({
        _root = root,
        _parts = parts,
        _guard = Guard.new(),
        _tweens = {},
        _open = false,
    }, Anim)

    -- One cleanup closure covers every tween this instance ever creates.
    -- A closure per-tween would append to root's junk list on every
    -- open/close, growing it without bound.
    root:keep(function()
        for i = 1, #self._tweens do
            pcall(function() self._tweens[i]:Cancel() end)
        end
        self._tweens = {}
    end)

    return self
end

function Anim:isOpen()
    return self._open
end

-- Longest end-to-end duration of a close, derived from TIMING so a retune of
-- the table can't desynchronise callers that need to know when the window is
-- gone.
function M.closeDuration()
    local t = M.TIMING.close
    local total = 0
    for _, stage in pairs(t) do
        local finish = stage.delay + stage.time
        if finish > total then total = finish end
    end
    return total
end

function Anim:_tween(object, time, delay, props, easing, direction)
    -- TweenInfo.new(Time, EasingStyle, EasingDirection, RepeatCount, Reverses, DelayTime)
    -- The delay is the sixth argument; passing it fourth sets RepeatCount
    -- instead and the stage fires immediately, collapsing all three into one.
    local info = TweenInfo.new(time, easing, direction, 0, false, delay)
    local tween = TweenService:Create(object, info, props)
    table.insert(self._tweens, tween)
    tween:Play()
    return tween
end

-- Cancels outstanding tweens so a superseded animation never leaves the
-- window mid-fold.
function Anim:_cancel()
    self._guard:cancel()
    for i = 1, #self._tweens do
        pcall(function() self._tweens[i]:Cancel() end)
    end
    self._tweens = {}
end

function Anim:_snap(open)
    local p = self._parts
    local full = p.fullSize()
    if open then
        p.frame.Size = UDim2.fromOffset(full.X, full.Y)
        p.contents.Visible = true
    else
        p.frame.Size = UDim2.fromOffset(0, p.barHeight)
        p.contents.Visible = false
    end
end

function Anim:open(animate)
    if self._open then return end
    self._open = true
    self:_cancel()

    local p = self._parts
    local full = p.fullSize()

    if animate == false then
        self:_snap(true)
        return
    end

    local t = M.TIMING.open
    local token = self._guard:begin()

    -- Start fully collapsed: zero width, title-bar height. The title bar
    -- expands rightward from its left edge (AnchorPoint stays (0, 0)), then
    -- the frame unfolds downward from the bar.
    p.frame.Size = UDim2.fromOffset(0, p.barHeight)
    p.contents.Visible = true

    self:_tween(p.frame, t.bar.time, t.bar.delay,
        { Size = UDim2.fromOffset(full.X, p.barHeight) }, EASE_OUT, Enum.EasingDirection.Out)

    -- task.delay can't be cancelled: Unload only stops future work by making
    -- callbacks check isAlive() themselves, since disconnecting anything here
    -- wouldn't stop a pending stage firing after teardown.
    task.delay(t.height.delay, function()
        if not self._root:isAlive() then return end
        self._guard:run(token, function()
            local liveFull = p.fullSize()
            self:_tween(p.frame, t.height.time, 0,
                { Size = UDim2.fromOffset(liveFull.X, liveFull.Y) }, EASE_OUT, Enum.EasingDirection.Out)
        end)
    end)
end

function Anim:close(animate)
    if not self._open then return end
    self._open = false
    self:_cancel()

    local p = self._parts

    if animate == false then
        self:_snap(false)
        return
    end

    local t = M.TIMING.close
    local token = self._guard:begin()

    -- The frame collapses upward into the title bar first, then the bar
    -- retracts leftward.
    local full = p.fullSize()
    self:_tween(p.frame, t.height.time, t.height.delay,
        { Size = UDim2.fromOffset(full.X, p.barHeight) }, EASE_IN, Enum.EasingDirection.In)

    task.delay(t.bar.delay, function()
        if not self._root:isAlive() then return end
        self._guard:run(token, function()
            local tween = self:_tween(p.frame, t.bar.time, 0,
                { Size = UDim2.fromOffset(0, p.barHeight) }, EASE_IN, Enum.EasingDirection.In)
            tween.Completed:Connect(function()
                if self._guard:isCurrent(token) and self._root:isAlive() then
                    p.contents.Visible = false
                end
            end)
        end)
    end)
end

function Anim:toggle(animate)
    if self._open then
        self:close(animate)
    else
        self:open(animate)
    end
end

return M
end

__modules["core/backdrop"] = function(require)
-- Window backdrop: cover-crop maths plus the image and star pool.
-- computeCover is pure and unit tested; keep it free of Instance calls, in
-- the Lua 5.4 / Luau intersection.

local M = {}

-- Returns the image size and vertical offset for a bottom-anchored cover crop.
--
-- The caller anchors the image at (0.5, 1) on the window's bottom edge and
-- applies offset as a downward Y offset. Oversizing by (1 + shift) and pushing
-- down by baseHeight * shift keeps the top edge exactly at the window top, so a
-- shift can never uncover the top of the window.
function M.computeCover(windowW, windowH, aspect, shift)
    shift = shift or 0
    -- A negative shift would shrink the oversize factor below the base size
    -- without moving the offset back up enough, uncovering the bottom edge
    -- (or the right edge on the width-bound branch). Clamp at 0.
    if shift < 0 then shift = 0 end
    if windowW <= 0 or windowH <= 0 then return 0, 0, 0 end

    local baseW, baseH
    if (windowW / windowH) > aspect then
        baseW = windowW
        baseH = windowW / aspect
    else
        baseH = windowH
        baseW = windowH * aspect
    end

    return baseW * (1 + shift), baseH * (1 + shift), baseH * shift
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

local IMAGE_ASPECT = 1024 / 576
-- "forest background": the Image (AssetTypeId 1), not the Decal that wraps
-- it. Uploading an image to Roblox creates two assets, a Decal (type 13) and
-- the Image (type 1) it points at; an ImageLabel needs the Image. The
-- Creator Store page shows the decal id; the "copy texture ID" button gives
-- this one. Recoverable in-game too, via
-- getobjects("rbxassetid://<decal>")[1].Texture.
--
-- The two are moderated separately, and the decal clears first: at the time
-- of writing the decal reported Completed while this image was still
-- Pending, which renders blank and made the first upload look broken.
local DEFAULT_IMAGE = "rbxassetid://109006147881359"

local Backdrop = {}
Backdrop.__index = Backdrop

-- opts: Image, Shift, Count, TopBias, Span, MaxSize
function M.new(root, holder, opts)
    opts = opts or {}

    local self = setmetatable({
        _root = root,
        _holder = holder,
        _shift = opts.Shift or 0,
        _aspect = opts.Aspect or IMAGE_ASPECT,
        _topBias = opts.TopBias or 2.2,
        _span = opts.Span or 0.55,
        _rng = Random.new(),
        _stars = {},
        _w = holder.AbsoluteSize.X,
        _h = holder.AbsoluteSize.Y,
        _paused = false,
    }, Backdrop)

    local image = Instance.new("ImageLabel")
    image.Name = "backdrop"
    image.BackgroundTransparency = 1
    image.Image = opts.Image or DEFAULT_IMAGE
    image.ScaleType = Enum.ScaleType.Stretch
    image.AnchorPoint = Vector2.new(0.5, 1)
    image.Position = UDim2.new(0.5, 0, 1, 0)
    image.ZIndex = 1
    image.Parent = holder
    self._image = image
    root:keep(image)

    self._maxSize = opts.MaxSize or 3

    -- One cleanup closure for the whole pool, registered once. A keep per
    -- star would grow the junk list every time setCount raises the count
    -- from the settings slider, and would be redundant anyway, since every
    -- dot is a descendant of the ScreenGui that Unload destroys.
    root:keep(function()
        for i = 1, #self._stars do
            self._stars[i].obj:Destroy()
        end
        self._stars = {}
    end)

    self:setCount(opts.Count or 34)

    self:resize(self._w, self._h)
    return self
end

function Backdrop:_addStar()
    local size = self._rng:NextInteger(1, self._maxSize)
    local dot = Instance.new("Frame")
    dot.Name = "star"
    dot.Size = UDim2.fromOffset(size, size)
    dot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    dot.BackgroundTransparency = 1
    dot.BorderSizePixel = 0
    dot.ZIndex = 2
    dot.Parent = self._holder

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(1, 0)
    corner.Parent = dot

    local star = { obj = dot, size = size }
    self:_reseed(star, true)
    table.insert(self._stars, star)
end

-- Grows or shrinks the pool. Called at construction and by the settings slider.
function Backdrop:setCount(count)
    if type(count) ~= "number" then return end
    count = math.floor(count)
    if count < 0 then count = 0 end

    while #self._stars > count do
        local star = table.remove(self._stars)
        star.obj:Destroy()
    end
    while #self._stars < count do
        self:_addStar()
    end
end

function Backdrop:_reseed(star, first)
    local rng = self._rng
    star.y = self._h * (rng:NextNumber() ^ self._topBias) * self._span
    star.x = rng:NextNumber() * self._w
    star.vx = rng:NextNumber(-2.2, 2.2)
    star.vy = -rng:NextNumber(1.0, 4.0)
    star.peak = 0.12 + rng:NextNumber() * 0.42
    star.tWait = rng:NextNumber(0.3, 4.5)
    star.tIn = rng:NextNumber(0.35, 1.3)
    star.tHold = rng:NextNumber(0.4, 3.0)
    star.tOut = rng:NextNumber(0.4, 1.6)
    if first then
        -- Stagger initial phases, or every star fades in together on the
        -- first frame and the randomness is invisible for the first cycle.
        star.phase = rng:NextInteger(1, 4)
        star.clock = rng:NextNumber() * 2
    else
        star.phase = 1
        star.clock = 0
    end
end

function Backdrop:setImage(image)
    self._image.Image = image
end

function Backdrop:setShift(shift)
    self._shift = shift
    self:resize(self._w, self._h)
end

function Backdrop:resize(w, h)
    local prevW, prevH = self._w, self._h
    self._w, self._h = w, h
    local iw, ih, offset = M.computeCover(w, h, self._aspect, self._shift)
    self._image.Size = UDim2.fromOffset(math.ceil(iw), math.ceil(ih))
    self._image.Position = UDim2.new(0.5, 0, 1, math.floor(offset))

    -- AbsoluteSize is (0, 0) until the holder has rendered at least once, so
    -- the star pool in M.new is always seeded against zeros. The first real
    -- resize, with the holder's actual size, is what places the stars;
    -- reseed them fresh rather than scale up from 0.
    if prevW == 0 or prevH == 0 then
        for i = 1, #self._stars do
            self:_reseed(self._stars[i], true)
        end
    else
        local sx = w / prevW
        local sy = h / prevH
        for i = 1, #self._stars do
            local s = self._stars[i]
            s.x = s.x * sx
            s.y = s.y * sy
        end
    end
end

function Backdrop:setPaused(paused)
    if self._paused == paused then return end
    self._paused = paused
    if paused then
        for i = 1, #self._stars do
            self._stars[i].obj.BackgroundTransparency = 1
        end
    end
end

-- Four-phase cycle: 1 waiting (invisible), 2 fading in, 3 holding, 4 fading out.
function Backdrop:step(dt)
    if self._paused then return end
    local stars = self._stars
    for i = 1, #stars do
        local s = stars[i]
        s.clock = s.clock + dt

        if s.phase == 1 then
            s.obj.BackgroundTransparency = 1
            if s.clock >= s.tWait then
                s.clock = 0
                s.phase = 2
            end
        elseif s.phase == 2 then
            local k = math.min(s.clock / s.tIn, 1)
            s.obj.BackgroundTransparency = 1 - (1 - s.peak) * k
            if k >= 1 then
                s.clock = 0
                s.phase = 3
            end
        elseif s.phase == 3 then
            s.obj.BackgroundTransparency = s.peak
            if s.clock >= s.tHold then
                s.clock = 0
                s.phase = 4
            end
        else
            local k = math.min(s.clock / s.tOut, 1)
            s.obj.BackgroundTransparency = s.peak + (1 - s.peak) * k
            if k >= 1 then
                self:_reseed(s, false)
            end
        end

        if s.phase > 1 then
            s.x = s.x + s.vx * dt
            s.y = s.y + s.vy * dt
            if s.x < -s.size then
                s.x = self._w
            elseif s.x > self._w then
                s.x = -s.size
            end
            if s.y < -s.size then
                self:_reseed(s, false)
            end
        end

        s.obj.Position = UDim2.fromOffset(s.x, s.y)
    end
end

return M
end

__modules["core/column"] = function(require)
-- A column: the pure width-distribution maths, plus the ScrollingFrame that
-- holds containers.
--
-- widths() is the only place a size is computed by hand. Everything else is
-- AutomaticSize / AutomaticCanvasSize, because UIListLayout cannot express
-- ratios but can do everything else.
--
-- Lua 5.4 / Luau intersection: no compound assignment, no bitwise ops, no goto.

local M = {}

-- Distributes totalWidth across #weights columns separated by `gap` pixels.
-- The final column takes whatever integer pixels are left over, so the columns
-- always sum exactly to the available space rather than leaving a 1px seam.
function M.widths(weights, totalWidth, gap)
    local n = #weights
    if n == 0 then return {} end

    gap = gap or 0
    local space = totalWidth - gap * (n - 1)
    if space < 0 then space = 0 end

    local total = 0
    for i = 1, n do
        local w = weights[i]
        if type(w) == "number" and w > 0 then total = total + w end
    end

    local out = {}
    if total <= 0 then
        -- Every weight was zero or invalid: fall back to an even split rather
        -- than dividing by zero.
        for i = 1, n do out[i] = 1 end
        total = n
        weights = out
        out = {}
    end

    local used = 0
    for i = 1, n - 1 do
        local w = weights[i]
        if type(w) ~= "number" or w <= 0 then w = 0 end
        local px = math.floor(space * w / total)
        out[i] = px
        used = used + px
    end
    out[n] = space - used
    if out[n] < 0 then out[n] = 0 end
    return out
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

local Container = require("core/container")

local Column = {}
Column.__index = Column

function M.new(root, parent, opts)
    opts = opts or {}
    local theme = root.theme

    local frame = Instance.new("ScrollingFrame")
    frame.Name = "column"
    frame.Size = UDim2.new(0, 0, 1, 0)   -- width assigned by the owning tab
    frame.BackgroundTransparency = 1
    frame.BorderSizePixel = 0
    frame.CanvasSize = UDim2.new()
    -- The property is AutomaticCanvasSize, but its type is Enum.AutomaticSize.
    -- There is no Enum.AutomaticCanvasSize.
    frame.AutomaticCanvasSize = Enum.AutomaticSize.Y
    frame.ScrollBarThickness = 2
    frame.ScrollingDirection = Enum.ScrollingDirection.Y
    frame.ElasticBehavior = Enum.ElasticBehavior.Never
    frame.Parent = parent
    root:keep(frame)
    theme:bind(frame, "ScrollBarImageColor3", "Accent")

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 8)
    layout.Parent = frame

    return setmetatable({
        _root = root,
        _order = 0,
        frame = frame,
        weight = opts.Weight or 1,
    }, Column)
end

function Column:Container(title)
    self._order = self._order + 1
    local container = Container.new(self._root, self.frame, title)
    container.holder.LayoutOrder = self._order
    return container
end

function Column:setWidth(px)
    self.frame.Size = UDim2.new(0, px, 1, 0)
end

return M
end

__modules["core/config"] = function(require)
-- The config manager: the pure name and diff helpers, plus the registry,
-- restore lifecycle and file IO.
--
-- The helpers here are unit tested, so they stay in the Lua 5.4 / Luau
-- intersection: no compound assignment, no bitwise ops, no goto.

local M = {}

local MAX_NAME = 64

-- A config name becomes a filename, so it has to survive the filesystem and
-- must not be able to escape the config folder. Returns nil for anything
-- unusable rather than guessing a replacement.
function M.sanitiseName(name)
    if type(name) ~= "string" then return nil end

    local s = name:gsub("^%s+", "")
    s = s:gsub("%s+$", "")
    -- Path separators and the characters Windows rejects in a filename.
    s = s:gsub("[/\\:%*%?\"<>|]", "")
    -- Leading dots hide the file, and ".." is how a traversal starts.
    s = s:gsub("^%.+", "")
    s = s:gsub("^%s+", "")
    s = s:gsub("%s+$", "")

    if s == "" then return nil end
    if #s > MAX_NAME then s = s:sub(1, MAX_NAME) end
    return s
end

-- Compares a loaded config against the registered flags.
--
-- `unknown` is the orphaning case -- a flag in the file with no widget, which
-- usually means a Flag was renamed and every saved value under the old name is
-- now stranded. It is warned about rather than passed over silently.
--
-- `missing` is ordinary: a config saved before an option existed.
--
-- Both are sorted, so the warning reads the same twice running.
function M.diffFlags(saved, registered)
    local unknown, missing = {}, {}

    for flag in pairs(saved) do
        if registered[flag] == nil then
            table.insert(unknown, flag)
        end
    end
    for flag in pairs(registered) do
        if saved[flag] == nil then
            table.insert(missing, flag)
        end
    end

    table.sort(unknown)
    table.sort(missing)
    return unknown, missing
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

local serialise = require("core/serialise")

-- Resolved lazily: a module-scope game:GetService() runs on require, and the
-- Lua 5.4 harness requires this file to reach the helpers above.
local HttpService

local Config = {}
Config.__index = Config

function M.new(root, folder)
    HttpService = HttpService or game:GetService("HttpService")

    return setmetatable({
        _root = root,
        _folder = folder,
        _widgets = {},   -- flag -> widget
        _opts = {},      -- flag -> the opts it was built with, for warnings
        _pending = {},   -- flag -> encoded value, waiting for the menu to finish
        _live = false,
        -- Plain current values, exposed as Chroma.Flags. Maintained through the
        -- widget contract rather than by the widgets themselves.
        Flags = {},
    }, Config)
end

-- Called by container.lua for every widget it builds.
function Config:register(flag, widget)
    if self._widgets[flag] ~= nil then
        error(string.format("chroma: two widgets share the flag '%s'", tostring(flag)), 2)
    end
    self._widgets[flag] = widget

    self.Flags[flag] = widget:Get()
    widget:OnChanged(function(value)
        self.Flags[flag] = value
    end)

    -- Before the menu is finished, saved values wait in _pending and are
    -- applied together. After it, a widget built later catches up immediately.
    local saved = self._pending[flag]
    if saved ~= nil and self._live then
        self:_apply(flag, saved)
        self._pending[flag] = nil
    end
end

function Config:get(flag)
    return self._widgets[flag]
end

-- Widgets whose state is more than Get() returns say so with Save()/Load().
function Config:_apply(flag, encoded)
    local widget = self._widgets[flag]
    if widget == nil then return end
    local value = serialise.decode(encoded)
    if value == nil then return end

    if type(widget.Load) == "function" then
        widget:Load(value)
    else
        widget:Set(value)
    end
    self.Flags[flag] = widget:Get()
end

-- A single flag erroring (Keybind:Load calling SetMode on a corrupt value, for
-- instance) must not stop every flag after it in iteration order from
-- applying -- pairs() order is arbitrary, so that would drop configs at
-- random. Isolate each apply and warn with enough to find the bad flag.
local function applyOne(self, flag, value, configName)
    local ok, err = pcall(self._apply, self, flag, value)
    if not ok then
        warn(string.format("[Chroma] config '%s' flag '%s' failed to load: %s",
            tostring(configName), tostring(flag), tostring(err)))
    end
end

function Config:_snapshot()
    local out = {}
    for flag, widget in pairs(self._widgets) do
        local value
        if type(widget.Save) == "function" then
            value = widget:Save()
        else
            value = widget:Get()
        end
        local encoded = serialise.encode(value)
        if encoded ~= nil then out[flag] = encoded end
    end
    return out
end

--== file IO ==--
-- Executors sandbox these to their own workspace folder, so paths are relative
-- and no absolute path is ever built.

local function ensureFolder(path)
    if isfolder and not isfolder(path) then
        if makefolder then makefolder(path) end
    end
end

function Config:_configPath(name)
    return self._folder .. "/configs/" .. name .. ".json"
end

function Config:isAvailable()
    return not self._root:isDegraded("config")
end

function Config:ensureFolders()
    if not self:isAvailable() then return end
    ensureFolder(self._folder)
    ensureFolder(self._folder .. "/configs")
end

function Config:List()
    if not self:isAvailable() or not listfiles then return {} end
    self:ensureFolders()

    local out = {}
    local ok, files = pcall(listfiles, self._folder .. "/configs")
    if not ok then return out end

    for i = 1, #files do
        local name = files[i]:match("([^/\\]+)%.json$")
        if name then table.insert(out, name) end
    end
    table.sort(out)
    return out
end

function Config:Save(rawName)
    if not self:isAvailable() then return false, "configs unavailable" end

    local name = M.sanitiseName(rawName)
    if name == nil then return false, "invalid config name" end

    self:ensureFolders()

    -- Unknown flags are carried through rather than dropped: a config written
    -- by a build with more widgets should survive a round trip through one with
    -- fewer, or loading a script twice would quietly prune it.
    local data = self:_snapshot()
    for flag, value in pairs(self._pending) do
        if self._widgets[flag] == nil then data[flag] = value end
    end

    local ok, encoded = pcall(function()
        return HttpService:JSONEncode(data)
    end)
    if not ok then return false, "could not encode config" end

    local written = pcall(writefile, self:_configPath(name), encoded)
    if not written then return false, "could not write config" end
    return true, name
end

function Config:Load(rawName)
    if not self:isAvailable() then return false, "configs unavailable" end

    local name = M.sanitiseName(rawName)
    if name == nil then return false, "invalid config name" end

    local path = self:_configPath(name)
    if isfile and not isfile(path) then return false, "no such config" end

    local ok, text = pcall(readfile, path)
    if not ok then return false, "could not read config" end

    local decoded, data = pcall(function()
        return HttpService:JSONDecode(text)
    end)
    if not decoded or type(data) ~= "table" then
        -- Corrupt on disk. Warn and leave the menu alone rather than erroring:
        -- a bad file must not cost the user their whole session.
        warn("[Chroma] config '" .. name .. "' is unreadable and was ignored")
        return false, "corrupt config"
    end

    local unknown, _ = M.diffFlags(data, self._widgets)
    if #unknown > 0 then
        -- Almost always a renamed Flag, which strands every value saved under
        -- the old name. Silence here is what makes that expensive to find.
        warn("[Chroma] config '" .. name .. "' has " .. #unknown ..
            " flag(s) with no widget: " .. table.concat(unknown, ", "))
    end

    for flag, value in pairs(data) do
        if self._widgets[flag] ~= nil then
            applyOne(self, flag, value, name)
        else
            self._pending[flag] = value
        end
    end
    return true, name
end

function Config:Delete(rawName)
    if not self:isAvailable() then return false, "configs unavailable" end

    local name = M.sanitiseName(rawName)
    if name == nil then return false, "invalid config name" end

    local path = self:_configPath(name)
    if isfile and not isfile(path) then return false, "no such config" end
    if not delfile then return false, "delfile unavailable" end

    local ok = pcall(delfile, path)
    if not ok then return false, "could not delete config" end
    return true, name
end

--== autoload ==--
-- Chroma:Window() returns before a single widget exists, so there is no natural
-- moment at which the menu is known to be built. Saved values therefore wait in
-- _pending until one of two signals, then apply with an ordinary Set so
-- callbacks fire once, normally.

-- No new widget for this long also counts as finished. It exists for scripts
-- that end in a render loop, whose thread never dies.
local QUIET = 1

function Config:_autoloadPath()
    return self._folder .. "/autoload.txt"
end

function Config:GetAutoload()
    if not self:isAvailable() or not isfile then return nil end
    local path = self:_autoloadPath()
    if not isfile(path) then return nil end
    local ok, text = pcall(readfile, path)
    if not ok then return nil end
    return M.sanitiseName(text)
end

function Config:SetAutoload(rawName)
    if not self:isAvailable() then return false end
    self:ensureFolders()

    if rawName == nil then
        if delfile and isfile and isfile(self:_autoloadPath()) then
            pcall(delfile, self:_autoloadPath())
        end
        return true
    end

    local name = M.sanitiseName(rawName)
    if name == nil then return false end
    return pcall(writefile, self:_autoloadPath(), name) and true or false
end

-- Reads the marked config into _pending without touching any widget. Called
-- during Window(), when there are none yet.
function Config:primeAutoload()
    local name = self:GetAutoload()
    if name == nil then return end

    local path = self:_configPath(name)
    if isfile and not isfile(path) then return end

    local ok, text = pcall(readfile, path)
    if not ok then return end

    local decoded, data = pcall(function()
        return HttpService:JSONDecode(text)
    end)
    if not decoded or type(data) ~= "table" then
        warn("[Chroma] autoload config '" .. name .. "' is unreadable and was ignored")
        return
    end

    for flag, value in pairs(data) do
        self._pending[flag] = value
    end
    self._autoloadName = name
end

-- Applies everything still pending, then marks the manager live so any widget
-- built afterwards catches up on registration instead.
--
-- A flag still unmatched here is not yet known to be orphaned: finish() can
-- fire on the quiet timeout while the consumer script is merely slow (an
-- HttpGet mid-build, say), before every widget has registered. Such a flag
-- stays in _pending, where a late registration or the next Save still finds
-- it, so no warning is given here -- it would be a guess, and wrong for the
-- common slow-script case. A flag that really is orphaned is surfaced
-- unambiguously later, by an explicit LoadConfig call.
function Config:finish()
    if self._live then return end
    self._live = true

    local applied = 0
    for flag, value in pairs(self._pending) do
        if self._widgets[flag] ~= nil then
            applyOne(self, flag, value, self._autoloadName)
            self._pending[flag] = nil
            applied = applied + 1
        end
    end

    return applied
end

-- Watches for the menu being finished. `thread` is the consumer's script
-- thread, captured in Window(): once it is dead, the script body has run to
-- completion. That handles a script yielding mid-build -- an HttpGet leaves the
-- thread suspended, not dead -- which a deferred call does not.
--
-- LoadConfig() always works by hand, so if both signals somehow fail the cost
-- is that autoload did not fire, not that configs are broken.
function Config:watchForCompletion(thread)
    local RunService = game:GetService("RunService")
    local waited = 0
    local lastCount = 0

    local conn
    conn = RunService.Heartbeat:Connect(function(dt)
        if not self._root:isAlive() or self._live then
            conn:Disconnect()
            return
        end

        local count = 0
        for _ in pairs(self._widgets) do count = count + 1 end
        if count ~= lastCount then
            lastCount = count
            waited = 0
        else
            waited = waited + dt
        end

        local dead = thread == nil or coroutine.status(thread) == "dead"
        if dead or waited >= QUIET then
            conn:Disconnect()
            self:finish()
        end
    end)
    self._root:keep(conn)
end

return M
end

__modules["core/configui"] = function(require)
-- The Configs sub-tab of the settings page.
--
-- Split out of settings.lua, which is already a long surface file, and because
-- this half is the only part that talks to the config manager.

local M = {}

function M.build(root, window, tab)
    local config = root.config
    local column = tab:Column()

    local box = column:Container("Configs")

    if not config:isAvailable() then
        -- The executor has no writefile. Say so once, plainly, rather than
        -- offering buttons that quietly do nothing.
        box:Label({ Text = "Configs need writefile, which this executor" })
        box:Label({ Text = "does not provide." })
        return
    end

    local list, nameField, autoToggle

    local function refresh(select)
        local names = config:List()
        list:SetItems(names)
        if select ~= nil then
            list:Set(select)
        end
        -- The toggle tracks the selected entry, so it has to be re-read
        -- whenever the selection or the list changes.
        local current = list:Get()
        autoToggle:Set(current ~= nil and current == config:GetAutoload(), true)
    end

    -- All three take Flag = false: they are the config browser, not settings.
    -- Saving them would mean loading a config moved this UI around.
    list = box:ListBox({
        Flag = false,
        Items = config:List(),
        Rows = 6,
        Default = config:GetAutoload(),
        Callback = function(name)
            autoToggle:Set(name ~= nil and name == config:GetAutoload(), true)
            nameField:Set(name or "")
        end,
    })

    nameField = box:TextBox({
        Name = "Name",
        Flag = false,
        Placeholder = "config name",
        Default = config:GetAutoload() or "",
    })

    box:Button({
        Text = "Save",
        Callback = function()
            local ok, result = config:Save(nameField:Get())
            if ok then
                refresh(result)
            else
                warn("[Chroma] save failed: " .. tostring(result))
            end
        end,
    })

    box:Button({
        Text = "Load",
        Callback = function()
            local name = list:Get()
            if name == nil then return end
            local ok, result = config:Load(name)
            if not ok then
                warn("[Chroma] load failed: " .. tostring(result))
            end
        end,
    })

    box:Button({
        Text = "Delete",
        Callback = function()
            local name = list:Get()
            if name == nil then return end
            if config:GetAutoload() == name then
                config:SetAutoload(nil)
            end
            local ok, result = config:Delete(name)
            if ok then
                refresh(nil)
            else
                warn("[Chroma] delete failed: " .. tostring(result))
            end
        end,
    })

    box:Button({ Text = "Refresh", Callback = function() refresh(list:Get()) end })

    box:Separator()

    -- A toggle rather than a label showing the current autoload, because no
    -- widget offers a label that can be rewritten cleanly. It reflects the
    -- SELECTED config, so it changes meaning as the selection moves.
    autoToggle = box:Toggle({
        Name = "Autoload selected",
        Flag = false,
        Description = "Loads the selected config the next time this script runs.",
        Callback = function(on)
            local name = list:Get()
            if on and name ~= nil then
                config:SetAutoload(name)
            elseif not on then
                config:SetAutoload(nil)
            end
        end,
    })

    refresh(config:GetAutoload())
end

return M
end

__modules["core/container"] = function(require)
-- A titled section: the title sits outside a bordered box, on the backdrop,
-- as gamesense does. The box height is derived from its rows via
-- AutomaticSize -- nothing here computes a height.

local Row = require("core/row")
local widgets = require("widgets/init")

local M = {}

local Container = {}
Container.__index = Container

function M.new(root, parent, title)
    local theme = root.theme

    local holder = Instance.new("Frame")
    holder.Name = "container"
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.BackgroundTransparency = 1
    holder.BorderSizePixel = 0
    holder.Parent = parent
    root:keep(holder)

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 4)
    layout.Parent = holder

    local heading = Instance.new("TextLabel")
    heading.Name = "title"
    heading.BackgroundTransparency = 1
    heading.Size = UDim2.new(1, 0, 0, 14)
    heading.Font = Enum.Font.Ubuntu
    heading.TextSize = 12
    heading.TextXAlignment = Enum.TextXAlignment.Left
    heading.Text = title or ""
    heading.LayoutOrder = 1
    heading.Parent = holder
    theme:bind(heading, "TextColor3", "TextBright")

    local box = Instance.new("Frame")
    box.Name = "box"
    box.Size = UDim2.new(1, 0, 0, 0)
    box.AutomaticSize = Enum.AutomaticSize.Y
    box.BorderSizePixel = 0
    box.LayoutOrder = 2
    box.Parent = holder
    theme:bind(box, "BackgroundColor3", "Container", "BackgroundTransparency")

    local boxStroke = Instance.new("UIStroke")
    boxStroke.Thickness = 1
    boxStroke.Parent = box
    theme:bind(boxStroke, "Color", "ContainerBorder")

    local pad = Instance.new("UIPadding")
    pad.PaddingTop = UDim.new(0, 5)
    pad.PaddingBottom = UDim.new(0, 5)
    pad.PaddingLeft = UDim.new(0, 7)
    pad.PaddingRight = UDim.new(0, 7)
    pad.Parent = box

    local rows = Instance.new("UIListLayout")
    rows.FillDirection = Enum.FillDirection.Vertical
    rows.SortOrder = Enum.SortOrder.LayoutOrder
    rows.Padding = UDim.new(0, 0)
    rows.Parent = box

    return setmetatable({
        _root = root,
        _box = box,
        _order = 0,
        holder = holder,
    }, Container)
end

-- One method per registered widget, generated rather than written out, so this
-- file has no per-widget knowledge.
for name, widget in pairs(widgets) do
    -- A widget named `new`, `holder` or after any existing method would silently
    -- clobber it, and the symptom ("containers stopped working") would surface
    -- nowhere near the registry entry that caused it. Fail at load instead.
    assert(Container[name] == nil,
        "chroma: widget name '" .. tostring(name) .. "' collides with an existing Container member")

    Container[name] = function(self, opts)
        opts = opts or {}
        self._order = self._order + 1
        -- widget.FullWidth and widget.Stateless are declared properties, not
        -- hardcoded lists, so this stays widget-agnostic.
        local row = Row.new(self._root, self._box, opts, widget.FullWidth)
        row.frame.LayoutOrder = self._order
        local built = widget.new(self._root, row, opts)

        -- A stateful widget without a Flag would be silently dropped from every
        -- config, and the omission would only surface as a user losing that one
        -- setting. Deriving a flag from the widget's title instead is worse: a
        -- rename then orphans the saved value with nothing in the code hinting
        -- the title was load-bearing.
        -- Flag = false is an explicit opt-out, for a stateful widget that is
        -- part of the interface rather than a setting -- the config browser's
        -- own list and name field, for instance. Writing those into a user's
        -- config would mean loading one moved the browser around.
        if widget.Stateless then
            if opts.Flag ~= nil then
                error(string.format(
                    "chroma: %s '%s' holds no state, so Flag does nothing here",
                    name, tostring(opts.Name or opts.Text)), 2)
            end
        elseif opts.Flag == nil then
            error(string.format(
                "chroma: %s '%s' needs a Flag (or Flag = false if it is not a setting)",
                name, tostring(opts.Name)), 2)
        elseif opts.Flag ~= false then
            self._root.config:register(opts.Flag, built)
        end

        return built
    end
end

return M
end

__modules["core/cursor"] = function(require)
-- Custom cross cursor. hitTest is pure and unit tested, so it stays in the
-- Lua 5.4 / Luau intersection; the DrawingImmediate rendering below does not.

local M = {}

function M.hitTest(px, py, x, y, w, h)
    return px >= x and px <= x + w and py >= y and py <= y + h
end

--== Drawing side. Never runs under Lua 5.4. ==--

-- Resolved lazily inside M.new. A module-scope game:GetService() would execute
-- on require, and this file is required by the Lua 5.4 test harness to reach
-- hitTest, where the `game` global does not exist.
local UserInputService

local Cursor = {}
Cursor.__index = Cursor

local DEFAULTS = {
    Style = "Cross",
    Color = Color3.fromRGB(255, 255, 255),
    Size = 7,
    Thickness = 1,
    Gap = 0,
    Outline = true,
    ClickFeedback = true,
}

-- isOver() must be supplied by the caller: it decides when Chroma owns the
-- pointer. Chroma hides the OS cursor only while that returns true.
function M.new(root, opts, isOver)
    opts = opts or {}
    UserInputService = UserInputService or game:GetService("UserInputService")
    local cfg = {}
    for key, value in pairs(DEFAULTS) do
        cfg[key] = opts[key]
        if cfg[key] == nil then cfg[key] = value end
    end

    local self = setmetatable({
        _root = root,
        _cfg = cfg,
        _isOver = isOver,
        _held = false,
        _hidden = false,
    }, Cursor)

    -- Only a missing DrawingImmediate is fatal here. A Style of false or "None"
    -- still connects the paint loop, because the settings page can turn the
    -- cursor back on -- and it cannot do that if the connection was never made.
    if not DrawingImmediate then
        root:degrade("cursor", "DrawingImmediate missing: OS cursor retained")
        return self
    end

    -- Restoring the pointer must be unconditional. The one genuinely bad failure
    -- here is leaving the user unable to see where they are clicking.
    root:keep(function()
        UserInputService.MouseIconEnabled = true
    end)

    if cfg.ClickFeedback then
        root:keep(UserInputService.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                self._held = true
            end
        end))
        root:keep(UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                self._held = false
            end
        end))
    end

    local paint = DrawingImmediate.GetPaint(1000)
    root:keep(paint:Connect(function()
        self:_paint()
    end))

    return self
end

function Cursor:_paint()
    -- Style is read per frame rather than once at construction: the settings
    -- page changes it live, and "off" has to also restore the OS pointer, which
    -- the transition write below already does for free.
    local off = self._cfg.Style == false or self._cfg.Style == "None"
    local over = (not off) and self._isOver()

    -- _hidden records whether Chroma has hidden the OS pointer.
    --
    -- This re-asserts while the pointer is over the menu rather than writing
    -- only on the transition. A transition-only write is enough on a baseplate,
    -- but a real game that manages its own pointer sets MouseIconEnabled back
    -- to true every frame and simply wins -- the OS arrow and Chroma's cross
    -- then draw on top of each other. Reading the property first keeps this to
    -- one write per frame only while something is actually fighting us.
    if over then
        if UserInputService.MouseIconEnabled then
            UserInputService.MouseIconEnabled = false
        end
        self._hidden = true
    elseif self._hidden then
        UserInputService.MouseIconEnabled = true
        self._hidden = false
    end

    if not over then return end

    local cfg = self._cfg
    local pos = UserInputService:GetMouseLocation()
    local arm = cfg.Size
    if self._held then
        arm = math.max(2, arm - 2)
    end
    local gap = cfg.Gap
    local thin = cfg.Thickness

    local function line(from, to, color, thickness)
        DrawingImmediate.Line(from, to, color, 1, thickness)
    end

    local segments
    if gap > 0 then
        segments = {
            { Vector2.new(pos.X, pos.Y - arm), Vector2.new(pos.X, pos.Y - gap) },
            { Vector2.new(pos.X, pos.Y + gap), Vector2.new(pos.X, pos.Y + arm) },
            { Vector2.new(pos.X - arm, pos.Y), Vector2.new(pos.X - gap, pos.Y) },
            { Vector2.new(pos.X + gap, pos.Y), Vector2.new(pos.X + arm, pos.Y) },
        }
    else
        segments = {
            { Vector2.new(pos.X, pos.Y - arm), Vector2.new(pos.X, pos.Y + arm) },
            { Vector2.new(pos.X - arm, pos.Y), Vector2.new(pos.X + arm, pos.Y) },
        }
    end

    -- Outline first, underneath. Without it a coloured cross over a bright
    -- background disappears.
    if cfg.Outline then
        local black = Color3.new(0, 0, 0)
        for i = 1, #segments do
            line(segments[i][1], segments[i][2], black, thin + 2)
        end
    end
    for i = 1, #segments do
        line(segments[i][1], segments[i][2], cfg.Color, thin)
    end
end

function Cursor:setConfig(opts)
    for key, value in pairs(opts) do
        self._cfg[key] = value
    end
end

return M
end

__modules["core/field"] = function(require)
-- The 110x14 bordered field shared by Dropdown, TextBox and Keybind.
--
-- Three consumers with identical chrome, and the accent-on-open border
-- treatment has to match across them or the widgets read as three different
-- components. This is widget chrome, not row layout: the row still owns the
-- slot, and this renders into it.

local M = {}

M.HEIGHT = 14

-- opts: Glyph (a trailing character), Editable (caption is a TextBox),
-- Placeholder (Editable only).
function M.new(root, parent, opts)
    opts = opts or {}
    local theme = root.theme

    local frame = Instance.new("TextButton")
    frame.Name = "field"
    frame.AnchorPoint = Vector2.new(1, 0.5)
    frame.Position = UDim2.new(1, 0, 0.5, 0)
    frame.Size = UDim2.new(1, 0, 0, M.HEIGHT)
    frame.BorderSizePixel = 0
    frame.Text = ""
    frame.AutoButtonColor = false
    frame.Parent = parent
    theme:bind(frame, "BackgroundColor3", "Field")

    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Parent = frame
    theme:bind(stroke, "Color", "FieldBorder")

    -- A TextBox kept non-editable until clicked, rather than a label swapped for
    -- an input: the proven pattern from the slider's value field, where nothing
    -- moves between the two states.
    local caption = Instance.new(opts.Editable and "TextBox" or "TextLabel")
    caption.Name = "caption"
    caption.BackgroundTransparency = 1
    caption.Position = UDim2.fromOffset(4, 0)
    caption.Size = UDim2.new(1, -(opts.Glyph and 16 or 8), 1, 0)
    caption.Font = Enum.Font.Ubuntu
    caption.TextSize = 11
    caption.TextXAlignment = Enum.TextXAlignment.Left
    caption.TextTruncate = Enum.TextTruncate.AtEnd
    caption.Text = ""
    caption.Parent = frame
    theme:bind(caption, "TextColor3", "Text")

    if opts.Editable then
        caption.TextEditable = false
        caption.ClearTextOnFocus = false
        caption.PlaceholderText = opts.Placeholder or ""
        theme:bind(caption, "PlaceholderColor3", "TextDim")
    end

    local api = { frame = frame, stroke = stroke, label = caption }

    if opts.Glyph then
        local glyph = Instance.new("TextLabel")
        glyph.Name = "glyph"
        glyph.AnchorPoint = Vector2.new(1, 0.5)
        glyph.Position = UDim2.new(1, -4, 0.5, 0)
        glyph.Size = UDim2.fromOffset(8, 10)
        glyph.BackgroundTransparency = 1
        glyph.Font = Enum.Font.Ubuntu
        glyph.TextSize = 8
        glyph.Text = opts.Glyph
        glyph.Parent = frame
        theme:bind(glyph, "TextColor3", "TextDim")
        api.glyph = glyph
    end

    -- The border tracks the accent while the field is live: popup open,
    -- capturing a key, or being typed into. Rebind rather than write directly --
    -- theme:apply() runs every frame while the accent animates, so a binding
    -- keeps cycling with it instead of freezing at the hue it had on click.
    function api.setActive(active)
        theme:unbind(stroke)
        theme:bind(stroke, "Color", active and "Accent" or "FieldBorder")
    end

    return api
end

return M
end

__modules["core/icons"] = function(require)
-- Icons: pure resolveIcon that decides between the two branches Chroma renders,
-- an image asset (Roblox-hosted) or a first-letter fallback.
--
-- Pure: keeps to the Lua 5.4 / Luau intersection so the harness can drive it
-- without a Roblox environment.

local M = {}

-- Returns { kind, value? } for the two branches:
--   { kind = "asset", value = "rbxassetid://..." }
--   { kind = "letter" }
--
-- A Lucide name is resolved through icons.rest's mapping (baked into
-- lucide_assets.lua) into an ordinary Roblox image asset. There is no font
-- involved -- an earlier attempt to ship the Lucide TTF via getcustomasset
-- failed because Roblox's Font system refuses to load a TTF referenced from
-- inside a custom-font manifest that was itself provided by getcustomasset.
-- icons.rest sidesteps the whole problem by pre-uploading each glyph as its
-- own image.
--
-- The letter itself is not returned; the caller has the page name and takes
-- its first character. Keeping the fallback textless here keeps the function
-- pure and its cases countable.
function M.resolveIcon(icon, assets)
    if type(icon) ~= "string" or icon == "" then
        return { kind = "letter" }
    end

    if icon:sub(1, 13) == "rbxassetid://" then
        return { kind = "asset", value = icon }
    end

    local id = assets[icon]
    if id ~= nil then
        return { kind = "asset", value = "rbxassetid://" .. id }
    end

    return { kind = "letter" }
end

return M
end

