__modules["core/page"] = function(require)
-- A page: one rail button, an optional sub-tab row, and one or more tabs, each
-- holding columns.
--
-- There is no tab.lua on purpose. A tab is a named list of columns and this
-- file already owns switching between them; a file existing to hold one table
-- is a boundary that costs more than it earns.

local Column = require("core/column")
local Icons = require("core/icons")
local lucideAssets = require("core/lucide_assets")

local M = {}

local Page = {}
Page.__index = Page

local Tab = {}
Tab.__index = Tab

local SUBTAB_HEIGHT = 24
local COLUMN_GAP = 8
local PADDING = 8

--== Tab ==--

function Tab.new(root, page, name)
    local holder = Instance.new("Frame")
    holder.Name = "tab_" .. name
    holder.Size = UDim2.fromScale(1, 1)
    holder.BackgroundTransparency = 1
    holder.BorderSizePixel = 0
    holder.Visible = false
    holder.Parent = page._columnArea
    root:keep(holder)

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Horizontal
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, COLUMN_GAP)
    layout.Parent = holder

    local self = setmetatable({
        _root = root,
        _page = page,
        _columns = {},
        name = name,
        holder = holder,
    }, Tab)

    -- AbsoluteSize is (0, 0) until the holder has rendered once, so columns
    -- created in the same frame as their page would all get zero width -- the
    -- same trap that seeds every star particle at the origin.
    -- Re-laying out whenever the holder's size actually changes covers first
    -- render, window resize and page switching in one line, with nobody
    -- needing to remember to call relayout().
    root:keep(holder:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        self:_layout()
    end))

    return self
end

function Tab:Column(opts)
    local column = Column.new(self._root, self.holder, opts)
    column.frame.LayoutOrder = #self._columns + 1
    table.insert(self._columns, column)
    self:_layout()
    return column
end

-- UIListLayout cannot express ratios, so widths are assigned explicitly. The
-- available width is the column area minus the gaps between columns.
function Tab:_layout()
    local n = #self._columns
    if n == 0 then return end
    local weights = {}
    for i = 1, n do weights[i] = self._columns[i].weight end
    local total = self.holder.AbsoluteSize.X
    local px = Column.widths(weights, total, COLUMN_GAP)
    for i = 1, n do
        self._columns[i]:setWidth(px[i])
    end
end

--== Page ==--

function M.new(root, window, opts)
    local theme = root.theme
    local name = opts.Name or "Page"

    --== rail button ==--
    local button = Instance.new("TextButton")
    button.Name = "railButton"
    button.Size = UDim2.new(1, 0, 0, 28)
    button.BackgroundTransparency = 1
    button.Text = ""
    button.AutoButtonColor = false
    -- A pinned page sits in the rail's bottom strip rather than its list, so
    -- it stays visually separated from the consumer's pages however many
    -- there are. Today that is only the settings page.
    button.Parent = opts.Pinned and window._railBottom or window._rail
    root:keep(button)

    local marker = Instance.new("Frame")
    marker.Name = "marker"
    -- Overhangs the button by 1px top and bottom: flush with the button, the
    -- marker reads visibly shorter than the RailActive highlight beside it.
    -- The 1px each side sits in the 2px gap the rail layout leaves between
    -- buttons, so it can't collide with a neighbour.
    marker.Size = UDim2.new(0, 2, 1, 2)
    marker.Position = UDim2.fromOffset(0, -1)
    marker.BorderSizePixel = 0
    marker.Visible = false
    marker.Parent = button
    theme:bind(marker, "BackgroundColor3", "Accent")

    local resolved = Icons.resolveIcon(opts.Icon, lucideAssets)

    -- The consumer passed something Chroma cannot resolve into an image. Warn
    -- once so a typo shows up during development rather than as a silent
    -- letter -- Chroma's error, not the consumer's fault.
    if resolved.kind == "letter" and type(opts.Icon) == "string" and opts.Icon ~= "" then
        warn(string.format(
            "[Chroma] page '%s' Icon '%s' is not a Lucide name; falling back",
            tostring(name), tostring(opts.Icon)))
    end

    local glyph
    if resolved.kind == "asset" then
        glyph = Instance.new("ImageLabel")
        glyph.Image = resolved.value
        glyph.Size = UDim2.fromOffset(14, 14)
        glyph.BackgroundTransparency = 1
    else
        -- Letter fallback: first character of the page name, in Ubuntu.
        glyph = Instance.new("TextLabel")
        glyph.Size = UDim2.fromOffset(14, 14)
        glyph.BackgroundTransparency = 1
        glyph.Font = Enum.Font.Ubuntu
        glyph.TextSize = 12
        glyph.Text = name:sub(1, 1):upper()
        theme:bind(glyph, "TextColor3", "TextDim")
    end
    glyph.Name = "glyph"
    glyph.AnchorPoint = Vector2.new(0.5, 0.5)
    -- List pages pin the glyph at x=14 so it does not drift into the page-name
    -- text as the rail widens. Pinned pages have no text and want the glyph to
    -- track the strip's centre as the strip widens with the rail.
    if opts.Pinned then
        glyph.Position = UDim2.fromScale(0.5, 0.5)
    else
        glyph.Position = UDim2.new(0, 14, 0.5, 0)
    end
    glyph.Parent = button

    -- When the rail is expanded, the page name appears to the right of the
    -- glyph. It exists at construction, invisible via TextTransparency, and
    -- the rail's expand animation tweens both the transparency and the rail
    -- width in lockstep.
    --
    -- Only real (non-pinned) rail pages get a text: the pinned strip is
    -- narrow, and expanding it would fight the top rail's own animation.
    --
    -- `self` does not exist yet at this point in M.new; the local `pageText`
    -- is stored on `self` further down when the setmetatable table is built.
    local pageText
    if not opts.Pinned then
        pageText = Instance.new("TextLabel")
        pageText.Name = "text"
        pageText.AnchorPoint = Vector2.new(0, 0.5)
        pageText.Position = UDim2.new(0, 28, 0.5, 0)
        pageText.Size = UDim2.new(1, -34, 1, 0)
        pageText.BackgroundTransparency = 1
        pageText.Font = Enum.Font.Ubuntu
        pageText.TextSize = 12
        pageText.TextXAlignment = Enum.TextXAlignment.Left
        pageText.TextTruncate = Enum.TextTruncate.AtEnd
        pageText.Text = name
        pageText.TextTransparency = 1
        pageText.Parent = button
        theme:bind(pageText, "TextColor3", "TextDim")
    end

    --== page body ==--
    local body = Instance.new("Frame")
    body.Name = "page_" .. name
    body.Size = UDim2.fromScale(1, 1)
    body.BackgroundTransparency = 1
    body.BorderSizePixel = 0
    body.Visible = false
    body.Parent = window._pageArea
    root:keep(body)

    local subtabBar = Instance.new("Frame")
    subtabBar.Name = "subtabs"
    subtabBar.Size = UDim2.new(1, 0, 0, SUBTAB_HEIGHT)
    subtabBar.BackgroundTransparency = 1
    subtabBar.BorderSizePixel = 0
    subtabBar.Visible = false
    subtabBar.Parent = body

    local subtabRule = Instance.new("Frame")
    subtabRule.Name = "rule"
    subtabRule.AnchorPoint = Vector2.new(0, 1)
    subtabRule.Position = UDim2.new(0, 0, 1, 0)
    subtabRule.Size = UDim2.new(1, 0, 0, 1)
    subtabRule.BorderSizePixel = 0
    subtabRule.Parent = subtabBar
    theme:bind(subtabRule, "BackgroundColor3", "ContainerBorder")

    -- The buttons get their own frame because a UIListLayout arranges every
    -- child of its parent, including the 1px rule, which is full width and
    -- would consume the whole row and push the buttons off the end.
    local subtabList = Instance.new("Frame")
    subtabList.Name = "list"
    subtabList.Size = UDim2.fromScale(1, 1)
    subtabList.BackgroundTransparency = 1
    subtabList.BorderSizePixel = 0
    subtabList.Parent = subtabBar

    local subtabPad = Instance.new("UIPadding")
    subtabPad.PaddingLeft = UDim.new(0, PADDING)
    subtabPad.Parent = subtabList

    local subtabLayout = Instance.new("UIListLayout")
    subtabLayout.FillDirection = Enum.FillDirection.Horizontal
    subtabLayout.SortOrder = Enum.SortOrder.LayoutOrder
    subtabLayout.Padding = UDim.new(0, 14)
    subtabLayout.Parent = subtabList

    local columnArea = Instance.new("Frame")
    columnArea.Name = "columns"
    columnArea.Position = UDim2.fromOffset(PADDING, PADDING)
    columnArea.Size = UDim2.new(1, -PADDING * 2, 1, -PADDING * 2)
    columnArea.BackgroundTransparency = 1
    columnArea.BorderSizePixel = 0
    columnArea.Parent = body

    local self = setmetatable({
        _root = root,
        _window = window,
        _theme = theme,
        _tabs = {},
        _tabButtons = {},
        _activeTab = nil,
        _implicit = nil,
        _subtabBar = subtabBar,
        _subtabList = subtabList,
        _columnArea = columnArea,
        _button = button,
        _marker = marker,
        _glyph = glyph,
        _text = pageText,
        name = name,
        body = body,
        pinned = opts.Pinned == true,
    }, Page)

    root:keep(button.Activated:Connect(function()
        window:setActivePage(self)
    end))

    return self
end

function Page:setActive(active)
    self.body.Visible = active
    self._marker.Visible = active
    self._button.BackgroundTransparency = active and 0 or 1
    if active then
        self._theme:unbind(self._button)
        self._theme:bind(self._button, "BackgroundColor3", "RailActive")
    else
        self._theme:unbind(self._button)
    end
    -- Both letter fallbacks (TextLabel) and Lucide icons (ImageLabel) tint on
    -- active state, through their respective colour properties.
    self._theme:unbind(self._glyph)
    if self._glyph:IsA("TextLabel") then
        self._theme:bind(self._glyph, "TextColor3", active and "TextBright" or "TextDim")
    else
        self._theme:bind(self._glyph, "ImageColor3", active and "TextBright" or "TextDim")
    end
    if self._text then
        self._theme:unbind(self._text)
        self._theme:bind(self._text, "TextColor3", active and "TextBright" or "TextDim")
    end
end

function Page:Tab(name)
    -- A page is either tabbed or it is not. Columns added straight to the
    -- page live in an implicit tab with no button, so a real tab created
    -- afterwards would strand them the moment the user switches, with no way
    -- back -- refuse instead.
    if self._implicit then
        error(string.format(
            "chroma: page '%s' already has columns added directly; call :Tab() " ..
            "before adding any columns, or use :Column() throughout",
            tostring(self.name)), 2)
    end

    local tab = Tab.new(self._root, self, name)
    self._tabs[#self._tabs + 1] = tab

    local button = Instance.new("TextButton")
    button.Name = "subtab_" .. name
    button.Size = UDim2.new(0, 0, 1, 0)
    button.AutomaticSize = Enum.AutomaticSize.X
    button.BackgroundTransparency = 1
    button.Font = Enum.Font.Ubuntu
    button.TextSize = 12
    button.Text = name
    button.AutoButtonColor = false
    button.LayoutOrder = #self._tabs
    button.Parent = self._subtabList
    self._root:keep(button)

    local underline = Instance.new("Frame")
    underline.Name = "underline"
    underline.AnchorPoint = Vector2.new(0, 1)
    underline.Position = UDim2.new(0, 0, 1, 0)
    underline.Size = UDim2.new(1, 0, 0, 2)
    underline.BorderSizePixel = 0
    underline.Visible = false
    underline.ZIndex = 2
    underline.Parent = button
    self._theme:bind(underline, "BackgroundColor3", "Accent")

    self._tabButtons[tab] = { button = button, underline = underline }

    self._root:keep(button.Activated:Connect(function()
        self:setActiveTab(tab)
    end))

    -- The bar only appears once a page has real tabs; an implicit tab has none.
    self._subtabBar.Visible = true
    self._columnArea.Position = UDim2.fromOffset(PADDING, SUBTAB_HEIGHT + PADDING)
    self._columnArea.Size = UDim2.new(1, -PADDING * 2, 1, -(SUBTAB_HEIGHT + PADDING * 2))

    -- Restyle every tab, not just the first: setActiveTab binds each button's
    -- colour, so a tab added later would otherwise keep Roblox's default
    -- TextButton colour until something triggered a restyle.
    self:setActiveTab(self._activeTab or tab)
    return tab
end

function Page:setActiveTab(tab)
    self._activeTab = tab
    for i = 1, #self._tabs do
        local t = self._tabs[i]
        local parts = self._tabButtons[t]
        local active = t == tab
        t.holder.Visible = active
        if parts then
            parts.underline.Visible = active
            self._theme:unbind(parts.button)
            self._theme:bind(parts.button, "TextColor3",
                active and "TextBright" or "TextDim")
        end
        if active then t:_layout() end
    end
    -- A popup opened from a row in the outgoing tab has no link to it and
    -- would be left floating over the incoming one.
    self._window:_layoutChanged()
end

-- Pages without tabs proxy straight to an implicit one, so a simple page needs
-- no throwaway :Tab("Main") call.
function Page:Column(opts)
    if not self._activeTab then
        self._implicit = Tab.new(self._root, self, "__implicit")
        self._tabs[#self._tabs + 1] = self._implicit
        self._activeTab = self._implicit
        self._implicit.holder.Visible = true
    elseif not self._implicit then
        -- Real tabs exist, so a bare :Column() would land in whichever tab is
        -- currently active: fine with one tab, ambiguous with several, and
        -- invisible either way. Make the caller say which.
        error(string.format(
            "chroma: page '%s' has sub-tabs; add columns to a tab, not the page",
            tostring(self.name)), 2)
    end
    return self._activeTab:Column(opts)
end

function Page:relayout()
    for i = 1, #self._tabs do
        self._tabs[i]:_layout()
    end
end

return M
end

__modules["core/palette"] = function(require)
-- The saved-colour palette, shared by every colorpicker in the window.
--
-- Global rather than per-config, in its own file: a palette is a preference
-- about how you work, not a setting of one config, and loading a config should
-- not silently swap your swatches.

local serialise = require("core/serialise")

local M = {}

local MAX = 10

local Palette = {}
Palette.__index = Palette

function M.new(root, folder)
    local self = setmetatable({
        _root = root,
        _path = folder .. "/palette.json",
        _colours = {},
        _listeners = {},
    }, Palette)
    self:_read()
    return self
end

function Palette:Get()
    return self._colours
end

function Palette:onChanged(fn)
    table.insert(self._listeners, fn)
end

function Palette:_notify()
    for i = 1, #self._listeners do
        self._listeners[i]()
    end
end

function Palette:Add(colour)
    if typeof(colour) ~= "Color3" then return end
    for i = 1, #self._colours do
        if self._colours[i] == colour then return end
    end
    table.insert(self._colours, colour)
    -- Oldest out first: the row is a fixed width, and silently refusing to add
    -- would read as the button being broken.
    while #self._colours > MAX do
        table.remove(self._colours, 1)
    end
    self:_write()
    self:_notify()
end

function Palette:Remove(index)
    if self._colours[index] == nil then return end
    table.remove(self._colours, index)
    self:_write()
    self:_notify()
end

function Palette:_read()
    if self._root:isDegraded("config") or not isfile then return end
    if not isfile(self._path) then return end

    local ok, text = pcall(readfile, self._path)
    if not ok then return end

    local HttpService = game:GetService("HttpService")
    local decoded, data = pcall(function() return HttpService:JSONDecode(text) end)
    if not decoded or type(data) ~= "table" then return end

    for i = 1, #data do
        local colour = serialise.decode(data[i])
        if typeof(colour) == "Color3" then
            table.insert(self._colours, colour)
        end
    end
end

function Palette:_write()
    if self._root:isDegraded("config") or not writefile then return end

    local out = {}
    for i = 1, #self._colours do
        out[i] = serialise.encode(self._colours[i])
    end

    local HttpService = game:GetService("HttpService")
    local ok, text = pcall(function() return HttpService:JSONEncode(out) end)
    if not ok then return end
    pcall(writefile, self._path, text)
end

return M
end

__modules["core/popup"] = function(require)
-- The popup overlay: placement maths, plus the single-slot manager.
--
-- place() is unit tested, so it stays in the Lua 5.4 / Luau intersection --
-- no compound assignment, no bitwise ops, no goto.

local M = {}

M.GAP = 2       -- pixels between the control slot and the popup
M.MARGIN = 6    -- minimum distance from any screen edge

-- Places a popup against the rect of the control that opened it.
--
-- Right-aligned to the slot and extending left: the colorpicker is 176px
-- against a 110px slot, so left-aligning hangs it over the next column.
--
-- All in the anchor's coordinate space, like Tooltip.place. GetMouseLocation
-- never enters into it, so the GUI-inset mismatch can't happen here.
function M.place(anchor, size, viewport, gap, margin)
    gap = gap or M.GAP
    margin = margin or M.MARGIN

    local x = anchor.x + anchor.w - size.w
    if x + size.w > viewport.w - margin then
        x = viewport.w - margin - size.w
    end
    if x < margin then x = margin end

    local y = anchor.y + anchor.h + gap
    if y + size.h > viewport.h - margin then
        -- Flip above rather than clamp: clamping slides the popup over the
        -- control that opened it.
        y = anchor.y - size.h - gap
    end
    if y < margin then y = margin end

    return x, y
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

-- Resolved lazily: a module-scope game:GetService() executes on require, and
-- the Lua 5.4 harness requires this file to reach place().
local UserInputService
local RunService

local Popup = {}
Popup.__index = Popup

-- Whether an AbsolutePosition-space point falls inside a GuiObject's rect.
local function inside(object, x, y)
    if object == nil then return false end
    local p, s = object.AbsolutePosition, object.AbsoluteSize
    return x >= p.X and x <= p.X + s.X and y >= p.Y and y <= p.Y + s.Y
end

-- One popup at a time. Containers clip and columns scroll, so a popup lives in
-- the overlay layer at absolute coordinates, with no parent-child link to the
-- row that opened it -- nothing hides it automatically. One slot keeps "this is
-- stale, close it" to a single code path; with several, every dismissal has to
-- walk a list, and the failure mode is a dropdown floating over another page.
function M.new(root)
    UserInputService = UserInputService or game:GetService("UserInputService")
    RunService = RunService or game:GetService("RunService")

    local self = setmetatable({
        _root = root,
        _owner = nil,
        _frame = nil,
        _anchor = nil,
        _onClose = nil,
        _watch = nil,
    }, Popup)

    -- A hit test, not a full-screen blocker button. The blocker swallowed the
    -- dismissing click: dragging the title bar with a dropdown open closed it
    -- on mouse-release and never started the drag, because the bar never saw
    -- the press.
    root:keep(UserInputService.InputBegan:Connect(function(input)
        if self._owner == nil then return end

        if input.KeyCode == Enum.KeyCode.Escape then
            self:close()
            return
        end

        -- Touch is here so a tap outside can't strand a popup on a touch-only
        -- target. Untested there, but a silent dead end is worse.
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.MouseButton2
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end

        local mx, my = root:mouseInGuiSpace()
        -- The anchor counts as inside: a click on the field that opened this
        -- has to fall through to the widget's own toggle, or it reopens what we
        -- just closed.
        if inside(self._frame, mx, my) or inside(self._anchor, mx, my) then return end
        self:close()
    end))

    -- One cleanup closure, registered once: doing it per open would grow the
    -- junk list on every click.
    root:keep(function()
        if self._watch then
            self._watch:Disconnect()
            self._watch = nil
        end
    end)

    return self
end

-- `anchor` is the GuiObject that opened the popup. Its rect is read here
-- rather than passed in, so the two can't get out of step -- and the drift
-- watch below needs the object anyway.
function Popup:open(owner, frame, anchor, onClose)
    -- close() fires the outgoing onClose, which may itself open a popup. Loop
    -- until the slot is empty, or the open below overwrites _watch and orphans
    -- a RenderStepped connection.
    local guard = 0
    while self._owner ~= nil or self._watch ~= nil do
        self:close()
        guard = guard + 1
        assert(guard < 8, "chroma: a popup onClose callback kept reopening a popup")
    end

    -- From the declared pixel Size, not AbsoluteSize: that reads (0, 0) until
    -- the frame has rendered once, and a popup is placed the instant it opens.
    local w, h = frame.Size.X.Offset, frame.Size.Y.Offset
    assert(w > 0 and h > 0, "chroma: popup frames must declare a pixel Size")

    self._owner = owner
    self._frame = frame
    self._anchor = anchor
    self._onClose = onClose

    local pos, size = anchor.AbsolutePosition, anchor.AbsoluteSize
    local viewport = workspace.CurrentCamera.ViewportSize
    local x, y = M.place(
        { x = pos.X, y = pos.Y, w = size.X, h = size.Y },
        { w = w, h = h },
        { w = viewport.X, h = viewport.Y })
    frame.Position = UDim2.fromOffset(self._root:toLayerSpace(x, y, frame.Parent))
    frame.Visible = true

    -- While open, close if the anchor moves at all -- the same watch-while-
    -- visible trick the tooltip uses. Covers column scrolling, dragging and
    -- resizing in one place. Page and tab switches don't move the anchor, so
    -- those go through bindDismissal instead.
    local originX, originY = pos.X, pos.Y
    self._watch = RunService.RenderStepped:Connect(function()
        if not anchor.Parent then
            self:close()
            return
        end
        local p = anchor.AbsolutePosition
        if p.X ~= originX or p.Y ~= originY then
            self:close()
        end
    end)
end

function Popup:close()
    -- Fired last, once every field is cleared, so an onClose that opens
    -- something else isn't racing a half-torn-down manager.
    local onClose = self._onClose

    if self._watch then
        self._watch:Disconnect()
        self._watch = nil
    end
    if self._frame then
        self._frame.Visible = false
    end
    self._owner = nil
    self._frame = nil
    self._anchor = nil
    self._onClose = nil

    if onClose then onClose() end
end

-- No argument: is anything open. With an owner: is that owner's popup open,
-- which is what lets a widget toggle itself.
function Popup:isOpen(owner)
    if owner == nil then return self._owner ~= nil end
    return self._owner == owner
end

-- A popup never follows its owner; it closes. Anything that reflows or replaces
-- the view routes here.
function Popup:bindDismissal(window)
    window:onLayoutChanged(function()
        self:close()
    end)
end

return M
end

__modules["core/rail"] = function(require)
-- Rail: pure easeExpand for the hover tween, plus (from the next task) the
-- hover watcher and instance-side tween.
--
-- Pure: Lua 5.4 / Luau intersection.

local M = {}

-- Ease-out quart. Chosen to match the window's own open animation, which uses
-- Enum.EasingStyle.Quint / EasingDirection.Out via TweenService; a quart here
-- is close enough that the two motions read as belonging to the same UI.
--
-- The TweenService codepath is what actually runs in-game; this exists so a
-- caller that wants to sample the curve outside a Tween has one endpoint.
function M.easeExpand(from, to, t)
    if t <= 0 then return from end
    if t >= 1 then return to end
    local eased = 1 - (1 - t) * (1 - t) * (1 - t) * (1 - t)
    return from + (to - from) * eased
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

-- Resolved lazily: a module-scope game:GetService() runs on require, and the
-- Lua 5.4 harness requires this file to reach easeExpand.
local RunService
local TextService
local TweenService
local UserInputService

local Rail = {}
Rail.__index = Rail

local COMPACT = 28
local TEXT_LEFT = 28    -- where the page-name label starts, matches page.lua
local RIGHT_PAD = 10    -- gap between the longest text and the rail's right edge
local MIN_EXPANDED = 60 -- floor so an empty rail is still a visibly-open pill
local DELAY_IN = 0.12
local DELAY_OUT = 0.4
local TWEEN_TIME = 0.16

-- opts: HoverExpand (defaults true), ExpandedWidth (nil = auto-measure)
function M.new(root, window, opts)
    opts = opts or {}
    RunService = RunService or game:GetService("RunService")
    TextService = TextService or game:GetService("TextService")
    TweenService = TweenService or game:GetService("TweenService")
    UserInputService = UserInputService or game:GetService("UserInputService")

    local self = setmetatable({
        _root = root,
        _window = window,
        _rail = window._rail,
        _railBottom = window._railBottom,
        _pageArea = window._pageArea,
        _expanded = false,
        -- nil means measure per expand; a number pins it. A consumer with
        -- deeply-nested Cyrillic or Chinese might want a fixed value.
        _expandedWidth = opts.ExpandedWidth,
        _enabled = opts.HoverExpand ~= false,
        _inTimer = nil,   -- task.delay handle waiting to expand
        _outTimer = nil,  -- task.delay handle waiting to collapse
        _tweens = {},
    }, Rail)

    -- One cleanup closure covers every tween this instance ever creates,
    -- matching the pattern anim.lua uses. A closure per tween would grow the
    -- junk list on every hover-in.
    root:keep(function()
        for i = 1, #self._tweens do
            pcall(function() self._tweens[i]:Cancel() end)
        end
        self._tweens = {}
    end)

    if not self._enabled then
        return self
    end

    -- One RenderStepped connection polling whether the pointer is over the
    -- rail's rect. MouseEnter/MouseLeave on the rail Frame would look
    -- simpler, but they fire against child buttons in ways that make hover
    -- state jitter -- a poll against AbsolutePosition is stable.
    --
    -- The pinned strip is a sibling of the rail, not a child, so the pointer
    -- being on the settings gear falls outside the rail's rect. Without
    -- unioning the strip's rect, hovering the gear starts a collapse and the
    -- rail sweeps out from under the cursor.
    local function isInside(guiObject, mx, my)
        local p, s = guiObject.AbsolutePosition, guiObject.AbsoluteSize
        return mx >= p.X and mx < p.X + s.X and my >= p.Y and my < p.Y + s.Y
    end

    root:keep(RunService.RenderStepped:Connect(function()
        if not root:isAlive() then return end
        local mx, my = root:mouseInGuiSpace()
        local over = isInside(self._rail, mx, my)
            or (self._railBottom and isInside(self._railBottom, mx, my))

        if over then
            self:_wantExpand()
        else
            self:_wantCollapse()
        end
    end))

    return self
end

function Rail:_wantExpand()
    -- Reaching the rail cancels an outstanding collapse.
    if self._outTimer then
        task.cancel(self._outTimer)
        self._outTimer = nil
    end
    if self._expanded or self._inTimer then return end

    self._inTimer = task.delay(DELAY_IN, function()
        self._inTimer = nil
        if not self._root:isAlive() then return end
        self:_expand(true)
    end)
end

function Rail:_wantCollapse()
    -- Leaving cancels an outstanding expand.
    if self._inTimer then
        task.cancel(self._inTimer)
        self._inTimer = nil
    end
    if not self._expanded or self._outTimer then return end

    -- A popup opened from a widget uses that widget's rect as its anchor. If
    -- the rail collapses now, the columns shift, the anchor moves, and the
    -- popup's drift-watch closes it -- eating a dropdown the user asked for.
    -- Wait for the popup to close.
    if self._root.popup and self._root.popup:isOpen() then
        return
    end

    self._outTimer = task.delay(DELAY_OUT, function()
        self._outTimer = nil
        if not self._root:isAlive() then return end
        -- Re-check the popup at fire time: it may have opened during the wait.
        if self._root.popup and self._root.popup:isOpen() then return end
        self:_expand(false)
    end)
end

-- Widest page-name text plus the icon column and a right margin. Cheap: a
-- handful of GetTextSize calls, only when we actually expand. Recomputed each
-- time so pages added after Chroma:Window returns are picked up automatically.
function Rail:_measureExpanded()
    if self._expandedWidth then return self._expandedWidth end

    local widest = 0
    for i = 1, #self._window._pages do
        local page = self._window._pages[i]
        if page._text then
            local ok, bounds = pcall(function()
                return TextService:GetTextSize(page._text.Text, 12,
                    Enum.Font.Ubuntu, Vector2.new(1000, 40))
            end)
            if ok and bounds.X > widest then widest = bounds.X end
        end
    end

    local w = TEXT_LEFT + math.ceil(widest) + RIGHT_PAD
    if w < MIN_EXPANDED then w = MIN_EXPANDED end
    return w
end

function Rail:_expand(open)
    if self._expanded == open then return end
    self._expanded = open

    local width = open and self:_measureExpanded() or COMPACT

    -- Cancel every tween started by the previous _expand call, or a rapid
    -- hover-in/out stacks overlapping tweens on the same Position and Size
    -- properties and leaves visible jitter.
    for i = 1, #self._tweens do
        pcall(function() self._tweens[i]:Cancel() end)
    end
    self._tweens = {}

    local info = TweenInfo.new(TWEEN_TIME, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

    -- Rail: only its width changes.
    local railTween = TweenService:Create(self._rail, info,
        { Size = UDim2.new(0, width, 1, 0) })
    table.insert(self._tweens, railTween)
    railTween:Play()

    -- Pinned strip sits alongside the rail (not inside it) and has a fixed
    -- pixel Size, so it must be tweened in lockstep -- otherwise the settings
    -- gear stays anchored at 28px while the rail widens around it.
    if self._railBottom then
        local bottomTween = TweenService:Create(self._railBottom, info,
            { Size = UDim2.new(0, width, 0, self._railBottom.Size.Y.Offset) })
        table.insert(self._tweens, bottomTween)
        bottomTween:Play()
    end

    -- Page area follows in lockstep so the columns reflow through the
    -- existing AbsoluteSize-changed signal on each tab's holder.
    local areaTween = TweenService:Create(self._pageArea, info, {
        Position = UDim2.fromOffset(width, 0),
        Size = UDim2.new(1, -width, 1, 0),
    })
    table.insert(self._tweens, areaTween)
    areaTween:Play()

    -- Every page's text label tweens transparency in the same window, so text
    -- appears alongside the rail rather than snapping in at either end.
    -- Pinned pages have no _text (see page.lua's construction guard).
    local targetTransparency = open and 0 or 1
    for i = 1, #self._window._pages do
        local page = self._window._pages[i]
        if page._text then
            local textTween = TweenService:Create(page._text, info,
                { TextTransparency = targetTransparency })
            table.insert(self._tweens, textTween)
            textTween:Play()
        end
    end
end

function Rail:setEnabled(enabled)
    if self._enabled == enabled then return end
    self._enabled = enabled
    if not enabled and self._expanded then
        -- Turning it off mid-hover should collapse the rail so the page area
        -- returns to full width rather than being frozen expanded.
        self:_expand(false)
    end
end

return M
end

__modules["core/root"] = function(require)
-- Owns the ScreenGui, the layer stack, and the single junk list that Unload
-- walks. No other module cleans up after itself.
local Theme = require("core/theme")

local GuiService
local UserInputService

local Root = {}
Root.__index = Root

local function pickParent()
    if gethui then
        local ok, hui = pcall(gethui)
        if ok and hui then return hui, "gethui" end
    end
    local okCoreGui, coreGui = pcall(function() return game:GetService("CoreGui") end)
    if okCoreGui and cloneref then
        local ok, cloned = pcall(cloneref, coreGui)
        if ok and cloned then return cloned, "cloneref(CoreGui)" end
    end
    local ok, playerGui = pcall(function()
        return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
    end)
    if ok and playerGui then return playerGui, "PlayerGui" end
    if okCoreGui and coreGui then return coreGui, "CoreGui" end
    error("chroma: no viable GUI parent (tried gethui, cloneref, PlayerGui, CoreGui)", 0)
end

local function randomName()
    local chars = "abcdefghijklmnopqrstuvwxyz"
    local out = {}
    for _ = 1, 12 do
        local i = math.random(1, #chars)
        table.insert(out, chars:sub(i, i))
    end
    return table.concat(out)
end

function Root.new(opts)
    opts = opts or {}
    GuiService = GuiService or game:GetService("GuiService")
    UserInputService = UserInputService or game:GetService("UserInputService")

    local parent, parentKind = pickParent()

    local self = setmetatable({
        _junk = {},
        _degraded = {},
        _alive = true,
        -- Set by a Keybind while it is capturing. The window's toggle handler
        -- checks it: without this, binding the menu's own toggle key would bind
        -- the key and close the menu in one press.
        capturing = false,
        parentKind = parentKind,
        theme = Theme.new(opts),
    }, Root)

    local gui = Instance.new("ScreenGui")
    gui.Name = randomName()
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.DisplayOrder = 2147483000
    gui.Parent = parent
    self.gui = gui
    self:keep(function() gui:Destroy() end)

    -- Layer stack. Popups and tooltips are siblings above the window, never
    -- children of a container: the window body clips for the slide animation,
    -- so anything meant to overflow has to live outside it. Overlays (toasts,
    -- watermark, hotkey list) sit above the window but below popups, so an
    -- open dropdown obscures a stale toast rather than the other way round.
    self.windowLayer = self:_layer("windows", 1)
    self.overlayLayer = self:_layer("overlays", 50)
    self.popupLayer = self:_layer("popups", 100)
    self.tooltipLayer = self:_layer("tooltips", 200)

    if not writefile then self:degrade("config", "writefile missing: configs disabled") end
    if not DrawingImmediate then self:degrade("cursor", "DrawingImmediate missing: OS cursor retained") end

    self:_startHeartbeat()
    return self
end

function Root:_layer(name, zindex)
    local frame = Instance.new("Frame")
    frame.Name = name
    frame.Size = UDim2.fromScale(1, 1)
    frame.BackgroundTransparency = 1
    frame.BorderSizePixel = 0
    frame.ZIndex = zindex
    frame.Parent = self.gui
    return frame
end

-- Register anything that must be undone on Unload: instances, connections,
-- tweens, restored globals. Accepts a function, an Instance, a Connection, or
-- an object with a Disconnect method.
function Root:keep(item)
    if type(item) == "function" then
        table.insert(self._junk, item)
    elseif typeof(item) == "Instance" then
        table.insert(self._junk, function() item:Destroy() end)
    elseif typeof(item) == "RBXScriptConnection" then
        table.insert(self._junk, function() item:Disconnect() end)
    else
        -- Executor signal implementations (e.g. Potassium's
        -- DrawingImmediate.GetPaint():Connect()) return connection-like
        -- userdata that is neither an Instance nor an RBXScriptConnection
        -- (typeof reports something executor-specific, e.g. "PsmConnection").
        -- There is no closed set of these types to check against, so fall
        -- back to structural typing: anything exposing a callable Disconnect
        -- is treated as a connection. Indexing arbitrary userdata can itself
        -- throw, so probe it through pcall rather than assuming it is safe.
        local ok, disconnect = pcall(function() return item.Disconnect end)
        if ok and type(disconnect) == "function" then
            table.insert(self._junk, function()
                pcall(function() item:Disconnect() end)
            end)
            return item
        end
        error("chroma: Root:keep expects a function, Instance, Connection, or an object with a Disconnect method", 2)
    end
    return item
end

--== coordinate spaces ==--
-- GetMouseLocation is true screen space. AbsolutePosition is measured below the
-- GUI inset, and Position is relative to a parent that may itself be offset.
-- Converting by hand per call site is error-prone -- past attempts misplaced
-- drags, the cursor's hover rect, window centring and the tooltip position.
-- Convert here instead.

-- The pointer, in the same space as any AbsolutePosition.
function Root:mouseInGuiSpace()
    local mouse = UserInputService:GetMouseLocation()
    local inset = GuiService:GetGuiInset()
    return mouse.X - inset.X, mouse.Y - inset.Y
end

-- An AbsolutePosition-space point, as a Position offset for a child of `layer`.
function Root:toLayerSpace(x, y, layer)
    local origin = (layer or self.gui).AbsolutePosition
    return x - origin.X, y - origin.Y
end

function Root:degrade(feature, reason)
    if self._degraded[feature] then return end
    self._degraded[feature] = reason
    warn("[Chroma] degraded: " .. reason)
end

function Root:isDegraded(feature)
    return self._degraded[feature] ~= nil
end

-- The user-affecting warn channel. Both warns to the console (so a developer
-- watching Volt's console sees it too) and, from phase 2 onward, surfaces a
-- toast so a running user sees the same information. Programmer-error warns
-- keep calling warn() directly and do not toast.
function Root:notify(kind, text)
    warn(string.format("[Chroma] %s: %s", tostring(kind), tostring(text)))
    if self._notifyHandler then
        pcall(self._notifyHandler, kind, text)
    end
end

-- Registered by the toast manager once it exists. Called through pcall so a
-- broken handler cannot silence future warns.
function Root:setNotifyHandler(fn)
    self._notifyHandler = fn
end

-- task.delay cannot be cancelled, so deferred callbacks scheduled before an
-- Unload can still fire afterwards; they must check this explicitly instead
-- of relying on the junk list to have stopped them.
function Root:isAlive()
    return self._alive
end

function Root:_startHeartbeat()
    local clock = 0
    local conn = game:GetService("RunService").RenderStepped:Connect(function(dt)
        clock = clock + dt
        self.theme:tick(clock)
        if self.theme:isAnimated() then
            self.theme:apply()
        end
        if self._onFrame then
            -- Internal hook (registered by Chroma's own window module), not a
            -- consumer callback: let errors propagate instead of swallowing them.
            self._onFrame(dt, clock)
        end
    end)
    self:keep(conn)
end

function Root:onFrame(fn)
    assert(self._onFrame == nil, "chroma: Root:onFrame already registered")
    self._onFrame = fn
end

function Root:Unload()
    self._alive = false
    for i = #self._junk, 1, -1 do
        pcall(self._junk[i])
    end
    self._junk = {}
    self.theme:clearBindings()
end

return Root
end

__modules["core/row"] = function(require)
-- A single 19px row: label on the left, optional (?) icon, and a fixed-width
-- right-aligned control slot that a widget renders into.
--
-- This is the boundary that keeps widget modules free of layout code: a widget
-- is handed `row.control` and knows nothing about rows, containers or columns.

local M = {}

M.HEIGHT = 19
M.CONTROL_WIDTH = 110   -- fits a 74px slider track plus its value text
M.ICON_SIZE = 12

-- opts: Name, Description, Height (optional override)
-- fullWidth: true for widgets with no control slot (Label, Separator), which
-- span the whole row. The row handles this itself; a widget resizing its own
-- row would put layout logic back inside widget modules.
function M.new(root, parent, opts, fullWidth)
    local theme = root.theme
    local height = opts.Height or M.HEIGHT

    local row = Instance.new("Frame")
    row.Name = "row"
    row.Size = UDim2.new(1, 0, 0, height)
    row.BackgroundTransparency = 1
    row.BorderSizePixel = 0
    row.Parent = parent
    root:keep(row)

    local hasIcon = opts.Description ~= nil and opts.Description ~= ""

    -- Left region holds [label][icon] in a horizontal list, so the engine
    -- does the measuring for icon placement -- no TextBounds read, no
    -- one-frame timing trap. Chosen over fixed-offset placement: trailing
    -- the label reads better than every icon lining up in a column.
    local left = Instance.new("Frame")
    left.Name = "left"
    left.BackgroundTransparency = 1
    left.BorderSizePixel = 0
    left.Position = UDim2.fromOffset(0, 0)
    if fullWidth then
        left.Size = UDim2.new(1, 0, 1, 0)
    else
        left.Size = UDim2.new(1, -M.CONTROL_WIDTH, 1, 0)
    end
    -- Above the hit button (2) so hover/tooltips on the icon still resolve
    -- against it. Regressing this to <=2 kills tooltips silently, with the
    -- symptom far removed from this line.
    left.ZIndex = 4
    left.Parent = row
    root:keep(left)

    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Horizontal
    list.VerticalAlignment = Enum.VerticalAlignment.Center
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 5)
    list.Parent = left

    local label = Instance.new("TextLabel")
    label.Name = "label"
    label.BackgroundTransparency = 1
    label.AutomaticSize = Enum.AutomaticSize.X
    label.Size = UDim2.new(0, 0, 1, 0)
    label.LayoutOrder = 1
    label.Font = Enum.Font.Ubuntu
    label.TextSize = 12
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.TextTruncate = Enum.TextTruncate.AtEnd
    label.Text = opts.Name or ""
    label.Parent = left
    theme:bind(label, "TextColor3", "Text")

    -- Cap the label's width so a long name truncates instead of shoving the
    -- icon into the control slot. left.AbsoluteSize is (0, 0) until the first
    -- render, so reading it once at construction would set a bogus cap; set
    -- it immediately and recompute on AbsoluteSize changing.
    local cap = Instance.new("UISizeConstraint")
    cap.Parent = label
    local function updateCap()
        local maxWidth = left.AbsoluteSize.X
        if hasIcon then
            maxWidth = maxWidth - (M.ICON_SIZE + 5)
        end
        if maxWidth < 0 then
            maxWidth = 0
        end
        cap.MaxSize = Vector2.new(maxWidth, math.huge)
    end
    updateCap()
    root:keep(left:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateCap))

    local icon
    if hasIcon then
        icon = Instance.new("TextButton")
        icon.Name = "help"
        icon.LayoutOrder = 2
        icon.Size = UDim2.fromOffset(M.ICON_SIZE, M.ICON_SIZE)
        icon.BackgroundTransparency = 1
        icon.AutoButtonColor = false
        -- Code rather than Ubuntu: a monospace face designed for small sizes,
        -- hinting far better at 11px, where Ubuntu's '?' goes soft. Only the
        -- glyph differs; row text stays Ubuntu.
        icon.Font = Enum.Font.Code
        icon.TextSize = 11
        icon.Text = "?"
        icon.ZIndex = 4
        icon.Parent = left
        theme:bind(icon, "TextColor3", "TextDim")

        local iconStroke = Instance.new("UIStroke")
        iconStroke.Thickness = 1
        iconStroke.Parent = icon
        theme:bind(iconStroke, "Color", "FieldBorder")

        -- Tint to the accent on hover, so the icon reads as interactive before
        -- the tooltip appears. Rebind rather than write directly: theme:apply()
        -- runs every frame off the window's heartbeat while the accent
        -- animates, so a binding keeps cycling with it instead of freezing at
        -- whatever hue was current on MouseEnter. bind() paints immediately,
        -- so there is no flash between unbinding and rebinding.
        root:keep(icon.MouseEnter:Connect(function()
            theme:unbind(icon)
            theme:unbind(iconStroke)
            theme:bind(icon, "TextColor3", "Accent")
            theme:bind(iconStroke, "Color", "Accent")
        end))
        root:keep(icon.MouseLeave:Connect(function()
            theme:unbind(icon)
            theme:unbind(iconStroke)
            theme:bind(icon, "TextColor3", "TextDim")
            theme:bind(iconStroke, "Color", "FieldBorder")
        end))

        root.tooltip:attach(icon, opts.Description)
    end

    local control
    if not fullWidth then
        control = Instance.new("Frame")
        control.Name = "control"
        control.AnchorPoint = Vector2.new(1, 0)
        control.Position = UDim2.new(1, 0, 0, 0)
        control.Size = UDim2.new(0, M.CONTROL_WIDTH, 1, 0)
        control.BackgroundTransparency = 1
        control.BorderSizePixel = 0
        -- Above the hit button (2) so widgets inside it (a slider track, for
        -- instance) get their own input instead of the row swallowing it.
        control.ZIndex = 3
        control.Parent = row
    end

    -- A transparent, full-row click target. Widgets that want "click anywhere
    -- on the row" ask for it via onActivated() below rather than parenting
    -- their own button into row.frame, which would defeat the boundary the
    -- control slot exists to enforce. ZIndex 2 sits above the label's default
    -- of 1 but below the icon (4) and control (3): getting this ordering
    -- wrong is how the row used to swallow hover input meant for the (?)
    -- icon and silently kill tooltips.
    local hit = Instance.new("TextButton")
    hit.Name = "hit"
    hit.Size = UDim2.fromScale(1, 1)
    hit.BackgroundTransparency = 1
    hit.Text = ""
    hit.AutoButtonColor = false
    hit.ZIndex = 2
    hit.Parent = row

    local api = { frame = row, label = label, icon = icon, control = control }

    -- Widgets that need a different row height ask for it rather than writing
    -- to row.frame themselves. Reaching into Instances the row owns is what
    -- the control-slot boundary exists to prevent.
    function api.setHeight(px)
        row.Size = UDim2.new(1, 0, 0, px)
    end

    -- Widgets ask for click-anywhere-on-row here rather than parenting their
    -- own button, per the ZIndex ordering explained above.
    function api.onActivated(fn)
        root:keep(hit.Activated:Connect(fn))
    end

    return api
end

return M
end

__modules["core/serialise"] = function(require)
-- Type tagging, so the values Chroma stores survive JSON.
--
-- JSON has no Color3 and no EnumItem, and an executor's JSONEncode will either
-- drop them or throw. Each becomes a plain table carrying a __t tag, and decode
-- turns it back.
--
-- Pure: dispatches on typeof() and builds Roblox datatypes, but calls no
-- Instance method, so it is unit tested. Lua 5.4 / Luau intersection -- no
-- compound assignment, no bitwise ops, no goto.

local M = {}

local TAG = "__t"

local function byte(channel)
    local n = math.floor(channel * 255 + 0.5)
    if n < 0 then return 0 end
    if n > 255 then return 255 end
    return n
end

-- Returns a JSON-safe value, or nil for anything unstorable. Unstorable is not
-- an error: a consumer may hand a widget something odd, and losing one flag is
-- better than losing the whole config.
function M.encode(value)
    local kind = typeof(value)

    if kind == "boolean" or kind == "number" or kind == "string" then
        return value
    end

    if kind == "Color3" then
        return { [TAG] = "Color3", r = byte(value.R), g = byte(value.G), b = byte(value.B) }
    end

    if kind == "EnumItem" then
        -- By name rather than by value: enum numbering is not stable across
        -- Roblox versions, and a name is legible in the saved file.
        --
        -- tostring(EnumType) returns e.g. "KeyCode". Reading EnumType.Name
        -- looks tidier but is a Roblox trap: the Enum object has no Name
        -- property, and the local test harness happens to stub one, so the
        -- suite passes green while the real code throws on the first save.
        return { [TAG] = "Enum", enum = tostring(value.EnumType), name = value.Name }
    end

    if kind == "table" then
        local out = {}
        for k, v in pairs(value) do
            local encoded = M.encode(v)
            if encoded ~= nil then out[k] = encoded end
        end
        return out
    end

    return nil
end

function M.decode(value)
    if type(value) ~= "table" then
        -- Booleans, numbers and strings need nothing; so does nil.
        return value
    end

    local tag = value[TAG]

    if tag == "Color3" then
        return Color3.fromRGB(value.r, value.g, value.b)
    end

    if tag == "Enum" then
        local group = Enum[value.enum]
        if group == nil then return nil end
        -- Indexing a missing item throws in Roblox, so probe it.
        local ok, item = pcall(function() return group[value.name] end)
        if not ok then return nil end
        return item
    end

    if tag ~= nil then
        -- A tag this version does not know: written by a newer Chroma. Drop the
        -- one value rather than taking the menu down.
        return nil
    end

    local out = {}
    for k, v in pairs(value) do
        out[k] = M.decode(v)
    end
    return out
end

return M
end

__modules["core/settings"] = function(require)
-- The built-in settings page: a pinned rail entry that configures Chroma itself.
--
-- Everything here writes through knobs that already existed -- setAccent,
-- setPalette, the cursor config, the Animations flag -- so this file adds no
-- infrastructure, only a surface. Settings are not persisted yet.

local M = {}
local ConfigUI = require("core/configui")

-- Lucide's "settings" is a gear; page.lua renders it in the Lucide font when
-- loaded, and falls back to a first-letter "S" when the font is missing.
local GEAR = "settings"

function M.build(root, window)
    local theme = root.theme

    local page = window:Page({ Name = "Settings", Icon = GEAR, Pinned = true })

    -- Sub-tabs rather than one long page: the two halves have nothing to do
    -- with each other, and appearance is the one people open repeatedly.
    local appearance = page:Tab("Appearance")
    local left, right = appearance:Column(), appearance:Column()

    --== accent ==--
    local accent = left:Container("Accent")

    -- The colorpicker is created before the mode dropdown so the dropdown's
    -- callback can reach it. A static accent is only meaningful alongside a
    -- colour, so the two are deliberately adjacent.
    -- Three modes over two axes: whether the hue animates, and whether the
    -- window outline runs a two-tone gradient. Gradient is the interesting one
    -- and was found by accident -- an unanimated accent still hue-shifted the
    -- outline's far end, which reads as a static sheen rather than a bug.
    local colour
    local mode = accent:Dropdown({
        Name = "Mode",
        Flag = "chroma_accent_mode",
        Options = { "RGB", "Gradient", "Static" },
        -- Read from the theme rather than assuming: a window constructed with
        -- Gradient = false and a static accent would otherwise boot showing
        -- "Gradient" while rendering flat hairlines.
        Default = theme:isAnimated() and "RGB"
            or (theme:isGradient() and "Gradient" or "Static"),
        Description = "RGB cycles the hue. Gradient holds one colour but keeps " ..
            "the two-tone sheen on the outline. Static is a single flat colour.",
        Callback = function(value)
            if value == "RGB" then
                window:setAccent("RGB")
            else
                window:setAccent(colour:Get())
            end
            window:setGradient(value ~= "Static")
        end,
    })

    colour = accent:Colorpicker({
        Name = "Colour",
        Flag = "chroma_accent_colour",
        Default = theme:get("Accent"),
        Description = "Used by Gradient and Static; RGB picks its own hue.",
        Callback = function(value)
            if mode:Get() ~= "RGB" then
                window:setAccent(value)
            end
        end,
    })

    accent:Slider({
        Name = "Speed", Flag = "chroma_accent_speed", Min = 0, Max = 1, Default = 0.15, Decimals = 2,
        Description = "Hue rotations per second while Mode is RGB.",
        Callback = function(value)
            window:setAccentSpeed(value)
        end,
    })

    --== window ==--
    local shell = left:Container("Window")

    shell:Toggle({
        Name = "Animations", Flag = "chroma_animations", Default = true,
        Description = "The two-stage open and close slide. Turn off for an instant show and hide.",
        Callback = function(value)
            window:setAnimations(value)
        end,
    })

    shell:Slider({
        Name = "Particles", Flag = "chroma_particles", Min = 0, Max = 80, Default = 34,
        Description = "Drifting stars over the backdrop.",
        Callback = function(value)
            window:setParticleCount(value)
        end,
    })

    shell:Keybind({
        Name = "Toggle key", Flag = "chroma_toggle_key", Default = window._toggleKey, Mode = "Always",
        Description = "Right-click for the mode menu. Escape while capturing clears the bind.",
        Callback = function(bind)
            window:setToggleKey(bind)
        end,
    })

    --== cursor ==--
    local pointer = right:Container("Cursor")

    pointer:Dropdown({
        Name = "Style", Flag = "chroma_cursor_style", Options = { "Cross", "None" }, Default = "Cross",
        Description = "None restores the operating system pointer over the menu.",
        Callback = function(value)
            window:setCursor({ Style = value })
        end,
    })

    pointer:Colorpicker({
        Name = "Colour", Flag = "chroma_cursor_colour", Default = Color3.fromRGB(255, 255, 255),
        Callback = function(value)
            window:setCursor({ Color = value })
        end,
    })

    pointer:Slider({
        Name = "Size", Flag = "chroma_cursor_size", Min = 3, Max = 14, Default = 7,
        Callback = function(value)
            window:setCursor({ Size = value })
        end,
    })

    pointer:Slider({
        Name = "Gap", Flag = "chroma_cursor_gap", Min = 0, Max = 6, Default = 0,
        Description = "Opens a hole at the centre of the cross.",
        Callback = function(value)
            window:setCursor({ Gap = value })
        end,
    })

    pointer:Toggle({
        Name = "Outline", Flag = "chroma_cursor_outline", Default = true,
        Description = "A black border under the cross, so it stays visible over bright ground.",
        Callback = function(value)
            window:setCursor({ Outline = value })
        end,
    })

    ConfigUI.build(root, window, page:Tab("Configs"))

    return page
end

return M
end

__modules["core/theme"] = function(require)
-- Palette, accent engine and binding registry.
-- Pure logic: no Instance API is called, only property assignment on whatever
-- objects are bound, so this is unit tested locally.
-- Lua 5.4 / Luau intersection: no compound assignment, no bitwise ops.

local Theme = {}
Theme.__index = Theme

local HAIR_HUE_SHIFT = 60 / 360
local ACCENT_DIM_FACTOR = 0.55
local SELECTION_TRANSPARENCY = 0.84

local STORED = {
    Window          = { 14, 17, 19 },
    Body            = { 19, 22, 24 },
    TitleBar        = { 26, 30, 33 },
    Container       = { 23, 25, 26 },
    ContainerBorder = { 46, 50, 52 },
    Rail            = { 20, 22, 23 },
    RailActive      = { 33, 36, 38 },
    Field           = { 17, 19, 20 },
    FieldBorder     = { 58, 63, 65 },
    Text            = { 190, 194, 195 },
    TextDim         = { 120, 125, 126 },
    TextBright      = { 242, 244, 244 },
}

-- Surfaces that are translucent by default. Anything absent is opaque.
-- The title bar is the only translucent surface by design: it sits outside the
-- body and shows the game directly, which is what makes it read as separate.
local TRANSPARENCY = {
    TitleBar  = 0.35,
    Container = 0.15,
    Rail      = 0.12,
    Selection = SELECTION_TRANSPARENCY,
}

local ACCENT_SEED = { 23, 184, 166 }

function Theme.hueAt(clock, speed)
    return (clock * speed) % 1
end

local function scale(color, factor)
    return Color3.new(color.R * factor, color.G * factor, color.B * factor)
end

local function shiftHue(color, amount)
    local hue, sat, val = color:ToHSV()
    return Color3.fromHSV((hue + amount) % 1, sat, val)
end

function Theme.new(opts)
    opts = opts or {}

    local stored = {}
    for key, rgb in pairs(STORED) do
        stored[key] = Color3.fromRGB(rgb[1], rgb[2], rgb[3])
    end

    local self = setmetatable({
        _stored = stored,
        _transparency = {},
        _derived = {},
        _bindings = {},
        _accentSpeed = opts.AccentSpeed or 0.15,
        _accentSat = opts.AccentSaturation or 0.86,
        _accentVal = opts.AccentValue or 0.72,
        _gradient = opts.Gradient ~= false,
    }, Theme)

    for key, value in pairs(TRANSPARENCY) do
        self._transparency[key] = value
    end

    self:setAccent(opts.Accent or "RGB")
    self:tick(0)
    return self
end

function Theme:isAnimated()
    return self._animated
end

function Theme:setAccent(accent)
    if accent == "RGB" then
        self._animated = true
        self._staticAccent = nil
    else
        self._animated = false
        self._staticAccent = accent
    end
    self:_recompute(self._clock or 0)
end

-- Mutates the stored palette only; existing bindings keep their old colour
-- until the caller calls apply().
-- Whether the outline runs a two-tone hue-shifted gradient or a single flat
-- colour. Independent of whether the accent animates: "RGB" decides whether the
-- hue moves over time, this decides whether the gradient's two ends differ at
-- any given instant.
function Theme:setGradient(enabled)
    self._gradient = enabled ~= false
    self:_recompute(self._clock or 0)
end

function Theme:isGradient()
    return self._gradient
end

function Theme:setAccentSpeed(speed)
    if type(speed) ~= "number" then return end
    self._accentSpeed = speed
    self:_recompute(self._clock or 0)
end

function Theme:setPalette(overrides)
    for key, value in pairs(overrides) do
        self._stored[key] = value
    end
end

-- Mutates the transparency table only; already-bound transparency writes are
-- not revisited, the caller must call apply() (or re-bind) to repaint.
function Theme:setTransparency(key, value)
    self._transparency[key] = value
end

function Theme:_recompute(clock)
    local accent
    if self._animated then
        local hue = Theme.hueAt(clock, self._accentSpeed)
        accent = Color3.fromHSV(hue, self._accentSat, self._accentVal)
    else
        accent = self._staticAccent or Color3.fromRGB(
            ACCENT_SEED[1], ACCENT_SEED[2], ACCENT_SEED[3])
    end

    local d = self._derived
    d.Accent = accent
    d.AccentDim = scale(accent, ACCENT_DIM_FACTOR)
    d.Selection = accent
    d.Glow = accent
    d.HairA = accent
    -- HairA and HairB are the two ends of the gradient on the window outline
    -- and the title bar's hairlines. Equal ends collapse it to a flat colour;
    -- that is the difference between Static and Gradient modes.
    if self._gradient then
        d.HairB = shiftHue(accent, HAIR_HUE_SHIFT)
    else
        d.HairB = accent
    end
end

-- Advance the clock. Cheap when the accent is static: recompute is skipped.
function Theme:tick(clock)
    self._clock = clock
    if self._animated then
        self:_recompute(clock)
    end
end

function Theme:get(key)
    local derived = self._derived[key]
    if derived ~= nil then return derived end
    return self._stored[key]
end

function Theme:transparency(key)
    return self._transparency[key] or 0
end

-- Registers a binding and paints it immediately, using the same diff check
-- apply() uses. This matters because the heartbeat only calls apply() while
-- the accent is animating; a static-accent surface would otherwise never be
-- coloured until something unrelated triggered a repaint.
-- If a fourth argument is given, it names a property to receive the key's
-- transparency. That write happens once, here, and is never re-diffed by
-- apply(): transparency values are static per key, so they are not added to
-- the binding list.
function Theme:bind(object, property, key, transparencyProperty)
    local binding = { object = object, property = property, key = key }
    table.insert(self._bindings, binding)

    local want = self:get(key)
    if want ~= nil and object[property] ~= want then
        object[property] = want
    end

    if transparencyProperty ~= nil then
        object[transparencyProperty] = self:transparency(key)
    end
end

function Theme:unbind(object)
    local kept = {}
    for i = 1, #self._bindings do
        local b = self._bindings[i]
        if b.object ~= object then table.insert(kept, b) end
    end
    self._bindings = kept
end

-- Writes every binding whose value has changed. The diff check is what makes an
-- animated accent nearly free: without it this writes hundreds of properties
-- per frame.
function Theme:apply()
    local bindings = self._bindings
    for i = 1, #bindings do
        local b = bindings[i]
        local want = self:get(b.key)
        if want ~= nil and b.object[b.property] ~= want then
            b.object[b.property] = want
        end
    end
end

function Theme:clearBindings()
    self._bindings = {}
end

return Theme
end

__modules["core/tooltip"] = function(require)
-- Tooltip: the pure placement maths, plus the single reused frame in the
-- tooltip layer.
--
-- place() is unit tested, so it stays in the Lua 5.4 / Luau intersection --
-- no compound assignment, no bitwise ops, no goto.

local M = {}

M.GAP = 8       -- pixels between the anchor and the tooltip
M.MARGIN = 8    -- minimum distance from any screen edge
M.Y_NUDGE = -3  -- lifts the tooltip so its text sits level with the icon, not below it

-- Anchored placement beside `anchor`, flipping left and clamping up as needed.
--
-- All in the anchor's coordinate space, which is the advantage of anchoring
-- over following the cursor: GetMouseLocation never enters into it, so the
-- GUI-inset mismatch can't happen here.
function M.place(anchor, tip, viewport, gap, margin)
    gap = gap or M.GAP
    margin = margin or M.MARGIN

    local x = anchor.x + anchor.w + gap
    if x + tip.w > viewport.w - margin then
        x = anchor.x - tip.w - gap
    end
    if x < margin then x = margin end

    local y = anchor.y + M.Y_NUDGE
    if y + tip.h > viewport.h - margin then
        y = viewport.h - margin - tip.h
    end
    if y < margin then y = margin end

    return x, y
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

-- Resolved lazily: a module-scope game:GetService() runs on require, and the
-- Lua 5.4 harness requires this file to reach place().
local UserInputService
local RunService

local Tooltip = {}
Tooltip.__index = Tooltip

local DELAY = 0.15
local MAX_WIDTH = 220

-- One manager per window, owning one reused frame -- the same pooling as the
-- star particles. Rows attach to it; they never create tooltips.
function M.new(root)
    UserInputService = UserInputService or game:GetService("UserInputService")
    RunService = RunService or game:GetService("RunService")

    local theme = root.theme

    local frame = Instance.new("Frame")
    frame.Name = "tooltip"
    frame.AutomaticSize = Enum.AutomaticSize.Y
    frame.Size = UDim2.fromOffset(MAX_WIDTH, 0)
    frame.BorderSizePixel = 0
    frame.Visible = false
    frame.ZIndex = 10
    -- Active stays false and no button is used: the tooltip must never
    -- intercept input, or one placed over its own icon would steal the
    -- pointer, fire MouseLeave on the icon, hide itself, and immediately
    -- re-trigger -- a hide/show flicker loop.
    frame.Parent = root.tooltipLayer
    root:keep(frame)
    theme:bind(frame, "BackgroundColor3", "Window")

    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Parent = frame
    theme:bind(stroke, "Color", "Accent")

    local pad = Instance.new("UIPadding")
    pad.PaddingTop = UDim.new(0, 4)
    pad.PaddingBottom = UDim.new(0, 4)
    pad.PaddingLeft = UDim.new(0, 6)
    pad.PaddingRight = UDim.new(0, 6)
    pad.Parent = frame

    local label = Instance.new("TextLabel")
    label.Name = "text"
    label.BackgroundTransparency = 1
    label.Size = UDim2.new(1, 0, 0, 0)
    label.AutomaticSize = Enum.AutomaticSize.Y
    label.Font = Enum.Font.Ubuntu
    label.TextSize = 11
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.TextYAlignment = Enum.TextYAlignment.Top
    -- Wrapping is correct here and nowhere else in Chroma: this is a
    -- standalone floating frame, not a child of an auto-sizing container, so
    -- a re-flow can't under-size anything around it.
    label.TextWrapped = true
    label.ZIndex = 11
    label.Parent = frame
    theme:bind(label, "TextColor3", "Text")

    local self = setmetatable({
        _root = root,
        _frame = frame,
        _label = label,
        _timer = nil,
        _pendingIcon = nil,
        _watch = nil,
        _owner = nil,
    }, Tooltip)

    -- One cleanup closure for the watch connection, registered once. Per-show
    -- registration would grow the junk list on every hover.
    root:keep(function()
        if self._watch then
            self._watch:Disconnect()
            self._watch = nil
        end
    end)

    return self
end

function Tooltip:_hide()
    if self._timer then
        task.cancel(self._timer)
        self._timer = nil
    end
    self._pendingIcon = nil
    if self._watch then
        self._watch:Disconnect()
        self._watch = nil
    end
    self._owner = nil
    self._frame.Visible = false
end

function Tooltip:_show(icon, text)
    self._label.Text = text
    self._owner = icon
    self._frame.Visible = true

    -- AbsoluteSize is only correct after a render pass, so place on the next
    -- frame rather than against a stale or zero size.
    RunService.RenderStepped:Wait()
    if self._owner ~= icon then return end

    local viewport = workspace.CurrentCamera.ViewportSize
    local pos, size = icon.AbsolutePosition, icon.AbsoluteSize
    local x, y = M.place(
        { x = pos.X, y = pos.Y, w = size.X, h = size.Y },
        { w = self._frame.AbsoluteSize.X, h = self._frame.AbsoluteSize.Y },
        { w = viewport.X, h = viewport.Y })
    self._frame.Position = UDim2.fromOffset(
        self._root:toLayerSpace(x, y, self._frame.Parent))

    -- MouseLeave is unreliable when the pointer moves fast, and a stuck
    -- tooltip is the only genuinely bad failure here, so while one is
    -- visible, confirm each frame that the pointer is still over the icon.
    self._watch = RunService.RenderStepped:Connect(function()
        if not self._owner or not self._owner.Parent then
            self:_hide()
            return
        end
        local mx, my = self._root:mouseInGuiSpace()
        local p, s = self._owner.AbsolutePosition, self._owner.AbsoluteSize
        local ax, ay = p.X, p.Y
        if mx < ax or mx > ax + s.X or my < ay or my > ay + s.Y then
            self:_hide()
        end
    end)
end

-- Called by the row builder for every (?) icon that has a description.
--
-- The pending timer is tagged with the icon it belongs to (_pendingIcon), and
-- MouseLeave only tears it down if it's still that icon's timer: Roblox gives
-- no ordering guarantee between MouseEnter/MouseLeave on different
-- GuiObjects, and a fast sweep across a column of icons can deliver icon B's
-- Enter before icon A's Leave.
function Tooltip:attach(icon, text)
    self._root:keep(icon.MouseEnter:Connect(function()
        if self._timer then task.cancel(self._timer) end
        self._pendingIcon = icon
        self._timer = task.delay(DELAY, function()
            self._timer = nil
            self._pendingIcon = nil
            if not self._root:isAlive() then return end
            self:_show(icon, text)
        end)
    end))

    self._root:keep(icon.MouseLeave:Connect(function()
        if self._owner == icon or self._pendingIcon == icon then self:_hide() end
    end))
end

return M
end

__modules["core/window"] = function(require)
-- The window shell: translucent title bar, icon rail, body holding the
-- backdrop, drag, resize, and the open/close animation.
--
-- Layout: title bar 24px, 4px gap to the body, rail 28px, and a 20px
-- backdrop band below where containers sit.
local Anim = require("core/anim")
local Backdrop = require("core/backdrop")
local Config = require("core/config")
local Cursor = require("core/cursor")
local Page = require("core/page")
local Palette = require("core/palette")
local Popup = require("core/popup")
local Rail = require("core/rail")
local Settings = require("core/settings")
local Tooltip = require("core/tooltip")

-- Resolved lazily in M.new: a module-scope game:GetService() runs on require.
local UserInputService

local M = {}

local Window = {}
Window.__index = Window

local BAR_HEIGHT = 24
local BAR_GAP = 4
local RAIL_WIDTH = 28
local MIN_WIDTH = 240
local MIN_HEIGHT = 190

function M.new(root, opts)
    UserInputService = UserInputService or game:GetService("UserInputService")

    opts = opts or {}
    local size = opts.Size or Vector2.new(640, 420)
    local theme = root.theme

    local self = setmetatable({
        _root = root,
        _theme = theme,
        _fullSize = size,
        _minSize = Vector2.new(MIN_WIDTH, MIN_HEIGHT),
        _layoutListeners = {},
    }, Window)

    -- Frame keeps AnchorPoint (0,0) forever: it is both the drag origin and
    -- the animation origin, so the two can't disagree.
    local viewport = workspace.CurrentCamera.ViewportSize
    -- ViewportSize is screen space; Position is parent (windowLayer) space.
    -- The layer's ScreenGui sets IgnoreGuiInset = true, so the layer's origin
    -- sits `inset` above the screen origin, and layer.AbsolutePosition.Y is
    -- that inset as a negative offset (e.g. -58). Subtracting it cancels the
    -- offset instead of hardcoding a GUI inset that isn't constant across
    -- setups (topbar height varies with platform/device).
    local frame = Instance.new("Frame")
    frame.Name = "window"
    frame.AnchorPoint = Vector2.new(0, 0)
    frame.Position = UDim2.fromOffset(root:toLayerSpace(
        math.floor(viewport.X / 2 - size.X / 2),
        math.floor(viewport.Y / 2 - size.Y / 2), root.windowLayer))
    frame.Size = UDim2.fromOffset(size.X, size.Y)
    frame.BackgroundTransparency = 1
    frame.BorderSizePixel = 0
    frame.ClipsDescendants = true
    frame.Parent = root.windowLayer
    self._frame = root:keep(frame)

    -- No stroke on `frame`: its bounds enclose the title bar as well as the
    -- body, so a stroke here would outline the bar too, and the bar is meant
    -- to read as a detached strip defined only by its two gradient hairlines.
    -- The window's outline is the body's own stroke, added below.
    --
    -- A soft glow was tried and removed: Roblox has no real bloom, so it was
    -- stacked UIStrokes, which band into separate rings rather than a falloff.
    -- A genuine glow would need a 9-slice radial sprite as an image asset.

    --== title bar: its own strip, translucent, detached by a gap ==--
    local bar = Instance.new("Frame")
    bar.Name = "titlebar"
    bar.Size = UDim2.new(1, 0, 0, BAR_HEIGHT)
    bar.BorderSizePixel = 0
    bar.ZIndex = 20
    bar.Parent = frame
    theme:bind(bar, "BackgroundColor3", "TitleBar", "BackgroundTransparency")
    self._bar = bar

    -- No UIStroke on the bar. The two gradient hairlines below already define
    -- its top and bottom edges; a stroke drew a second, fainter accent line
    -- just beneath the bottom hairline. The bar is a floating strip, so its
    -- unbordered left and right edges read fine -- the body's own stroke is
    -- what outlines the window.

    -- White base colour: a UIGradient multiplies the element's colour, and a
    -- Frame defaults to grey (163,162,165), which would render the gradient
    -- at about 64% intensity.
    local hair = Instance.new("Frame")
    hair.Name = "hairline"
    hair.Size = UDim2.new(1, 0, 0, 2)
    hair.BackgroundColor3 = Color3.new(1, 1, 1)
    hair.BorderSizePixel = 0
    hair.ZIndex = 22
    hair.Parent = bar
    local hairGradient = Instance.new("UIGradient")
    hairGradient.Color = ColorSequence.new(theme:get("HairA"), theme:get("HairB"))
    hairGradient.Parent = hair
    self._hairGradient = hairGradient

    -- Mirrored along the bottom edge for symmetry: without it, the 1px stroke
    -- plus the top hairline made the top read as a bright ~3px band against a
    -- thin 1px bottom, unbalanced on a detached floating strip.
    local hairBottom = Instance.new("Frame")
    hairBottom.Name = "hairlineBottom"
    hairBottom.Size = UDim2.new(1, 0, 0, 2)
    hairBottom.Position = UDim2.new(0, 0, 1, -2)
    hairBottom.BackgroundColor3 = Color3.new(1, 1, 1)
    hairBottom.BorderSizePixel = 0
    hairBottom.ZIndex = 22
    hairBottom.Parent = bar
    local hairGradientBottom = Instance.new("UIGradient")
    hairGradientBottom.Color = ColorSequence.new(theme:get("HairA"), theme:get("HairB"))
    hairGradientBottom.Parent = hairBottom
    self._hairGradientBottom = hairGradientBottom

    local titleText = Instance.new("TextLabel")
    titleText.Name = "title"
    titleText.BackgroundTransparency = 1
    titleText.Size = UDim2.new(1, -16, 1, 0)
    titleText.Position = UDim2.fromOffset(8, 0)
    titleText.Font = Enum.Font.Ubuntu
    titleText.TextSize = 12
    titleText.TextXAlignment = Enum.TextXAlignment.Left
    titleText.Text = opts.Name or "Chroma"
    titleText.ZIndex = 21
    titleText.Parent = bar
    theme:bind(titleText, "TextColor3", "TextBright")

    --== contents: everything that slides in from the left ==--
    local contents = Instance.new("Frame")
    contents.Name = "contents"
    contents.Position = UDim2.fromOffset(0, BAR_HEIGHT + BAR_GAP)
    contents.Size = UDim2.new(1, 0, 1, -(BAR_HEIGHT + BAR_GAP))
    contents.BackgroundTransparency = 1
    contents.BorderSizePixel = 0
    contents.ClipsDescendants = true
    contents.ZIndex = 2
    contents.Parent = frame
    self._contents = contents

    local body = Instance.new("Frame")
    body.Name = "body"
    -- Inset by 1px on every side. A UIStroke draws outward from its element's
    -- bounds, and `contents` clips its descendants, so a body filling contents
    -- exactly has its stroke drawn into the clipped region and cut away. The
    -- 1px margin is exactly the stroke's thickness, so it reads as an outline
    -- on the window edge with no visible gap.
    body.Size = UDim2.new(1, -2, 1, -2)
    body.Position = UDim2.fromOffset(1, 1)
    -- Opaque: the backdrop fills it. Translucency here would show the game
    -- world behind the forest.
    body.BackgroundTransparency = 0
    body.BorderSizePixel = 0
    body.ClipsDescendants = true
    body.Parent = contents
    theme:bind(body, "BackgroundColor3", "Body")
    self._body = body

    -- The outline carries the same hue-shifted gradient as the title bar's
    -- hairlines, so the bar and the window read as one piece rather than two
    -- accent colours side by side. A UIGradient parented to a UIStroke tints
    -- the stroke; the stroke's own Color must stay white or it multiplies the
    -- gradient down, so this one is not theme-bound.
    local bodyStroke = Instance.new("UIStroke")
    bodyStroke.Thickness = 1
    bodyStroke.Color = Color3.new(1, 1, 1)
    bodyStroke.Parent = body

    local bodyStrokeGradient = Instance.new("UIGradient")
    bodyStrokeGradient.Color = ColorSequence.new(theme:get("HairA"), theme:get("HairB"))
    bodyStrokeGradient.Parent = bodyStroke
    self._bodyStrokeGradient = bodyStrokeGradient

    self._backdrop = Backdrop.new(root, body, opts.Backdrop)

    local rail = Instance.new("Frame")
    rail.Name = "rail"
    rail.Size = UDim2.new(0, RAIL_WIDTH, 1, 0)
    rail.BorderSizePixel = 0
    rail.ZIndex = 5
    rail.Parent = body
    theme:bind(rail, "BackgroundColor3", "Rail", "BackgroundTransparency")
    self._rail = rail

    local railLayout = Instance.new("UIListLayout")
    railLayout.FillDirection = Enum.FillDirection.Vertical
    railLayout.SortOrder = Enum.SortOrder.LayoutOrder
    railLayout.Padding = UDim.new(0, 2)
    railLayout.Parent = rail

    local railPad = Instance.new("UIPadding")
    railPad.PaddingTop = UDim.new(0, 6)
    railPad.Parent = rail

    -- A bottom strip for pinned entries, a sibling of the rail rather than a
    -- child of it: a UIListLayout arranges every child of its parent, so
    -- parenting this to the rail made the list lay it out as an ordinary item
    -- and the gear appeared at the top. Anchored over the rail's own
    -- footprint instead, it sits outside that layout's reach.
    --
    -- The footprint is shared implicitly: this lines up with the rail only
    -- because the rail sits at (0, 0) and spans the body's full height. Give
    -- the rail an offset and this drifts silently.
    local railBottom = Instance.new("Frame")
    railBottom.Name = "railBottom"
    railBottom.AnchorPoint = Vector2.new(0, 1)
    railBottom.Position = UDim2.new(0, 0, 1, 0)
    railBottom.Size = UDim2.fromOffset(RAIL_WIDTH, 44)
    railBottom.BackgroundTransparency = 1
    railBottom.BorderSizePixel = 0
    railBottom.ZIndex = 6
    railBottom.Parent = body
    self._railBottom = railBottom

    local railBottomLayout = Instance.new("UIListLayout")
    railBottomLayout.FillDirection = Enum.FillDirection.Vertical
    railBottomLayout.VerticalAlignment = Enum.VerticalAlignment.Bottom
    railBottomLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    railBottomLayout.SortOrder = Enum.SortOrder.LayoutOrder
    railBottomLayout.Padding = UDim.new(0, 5)
    railBottomLayout.Parent = railBottom

    -- Lifts the pinned strip's contents off the very bottom edge. Combined
    -- with the strip's own extra height, this puts the gear ~6px above the
    -- body edge without pushing the rule out the top.
    local railBottomPad = Instance.new("UIPadding")
    railBottomPad.PaddingBottom = UDim.new(0, 6)
    railBottomPad.Parent = railBottom

    -- A UIListLayout arranges every child, so the rule is part of the list
    -- rather than positioned over it -- the same trap that makes a full-width
    -- rule eat a whole row. LayoutOrder 0 puts it above the pinned
    -- buttons, separating it visually from the pages.
    local railRule = Instance.new("Frame")
    railRule.Name = "rule"
    railRule.Size = UDim2.new(1, -12, 0, 1)
    railRule.BorderSizePixel = 0
    railRule.LayoutOrder = 0
    railRule.ZIndex = 6
    railRule.Parent = railBottom
    theme:bind(railRule, "BackgroundColor3", "ContainerBorder")

    -- Everything right of the rail. Pages fill this and show one at a time.
    local pageArea = Instance.new("Frame")
    pageArea.Name = "pages"
    pageArea.Position = UDim2.fromOffset(RAIL_WIDTH, 0)
    pageArea.Size = UDim2.new(1, -RAIL_WIDTH, 1, 0)
    pageArea.BackgroundTransparency = 1
    pageArea.BorderSizePixel = 0
    pageArea.Parent = body
    self._pageArea = pageArea

    self._pages = {}
    self._activePage = nil

    -- The tooltip and popup managers are owned by the window and reached
    -- through root, so row.lua and every widget can use them without being
    -- handed one.
    -- Created before any page exists, because container.lua registers flags as
    -- it builds and the settings page below is itself a consumer.
    local configFolder = opts.ConfigFolder or opts.Name or "chroma"

    root.config = Config.new(root, configFolder)
    root.config:primeAutoload()
    -- coroutine.running() here is the consuming script's own thread, because
    -- Chroma:Window() is called directly from it.
    root.config:watchForCompletion(coroutine.running())

    -- One palette per window, reached through root so every colorpicker shares
    -- it without being handed one.
    root.palette = Palette.new(root, configFolder)

    root.tooltip = Tooltip.new(root)
    root.popup = Popup.new(root)
    root.popup:bindDismissal(self)

    --== drag and resize ==--
    self:_makeDragHandle(bar, function(delta, start)
        frame.Position = UDim2.fromOffset(start.X + delta.X, start.Y + delta.Y)
        self:_layoutChanged()
    end, function()
        -- Same space mismatch as above: reading AbsolutePosition here but
        -- writing Position teleported the window by the GUI inset on every
        -- mouse-down. Read from the same space that gets written to.
        return Vector2.new(frame.Position.X.Offset, frame.Position.Y.Offset)
    end)

    -- The grip is an L outline hugging the corner rather than a filled square:
    -- the TextButton keeps its size, position and drag wiring as the hit area
    -- but is fully transparent, and two thin accent bars drawn on top of it
    -- form the visible corner.
    local grip = Instance.new("TextButton")
    grip.Name = "grip"
    grip.Size = UDim2.fromOffset(12, 12)
    grip.Position = UDim2.new(1, -13, 1, -13)
    grip.BackgroundTransparency = 1
    grip.BorderSizePixel = 0
    grip.Text = ""
    grip.AutoButtonColor = false
    grip.ZIndex = 30
    grip.Parent = contents

    -- The two visible bars carry the same HairA -> HairB gradient as the
    -- outline. Without a gradient, the grip's plain Accent equals HairA only
    -- and reads as a different colour from the outline at any instant while
    -- the accent animates.
    --
    -- A UIGradient multiplies its element's colour, so the frames' own
    -- BackgroundColor3 stays white -- a Frame defaults to grey (163,162,165)
    -- and would render the gradient at about 64% intensity.
    local gripBottom = Instance.new("Frame")
    gripBottom.Name = "gripBottom"
    gripBottom.Size = UDim2.new(1, 0, 0, 2)
    gripBottom.Position = UDim2.new(0, 0, 1, -2)
    gripBottom.BackgroundColor3 = Color3.new(1, 1, 1)
    gripBottom.BackgroundTransparency = 0.35
    gripBottom.BorderSizePixel = 0
    gripBottom.ZIndex = 30
    gripBottom.Parent = grip
    local gripBottomGradient = Instance.new("UIGradient")
    gripBottomGradient.Color = ColorSequence.new(theme:get("HairA"), theme:get("HairB"))
    gripBottomGradient.Parent = gripBottom
    self._gripBottomGradient = gripBottomGradient

    local gripRight = Instance.new("Frame")
    gripRight.Name = "gripRight"
    gripRight.Size = UDim2.new(0, 2, 1, 0)
    gripRight.Position = UDim2.new(1, -2, 0, 0)
    gripRight.BackgroundColor3 = Color3.new(1, 1, 1)
    gripRight.BackgroundTransparency = 0.35
    gripRight.BorderSizePixel = 0
    gripRight.ZIndex = 30
    gripRight.Parent = grip
    local gripRightGradient = Instance.new("UIGradient")
    gripRightGradient.Color = ColorSequence.new(theme:get("HairA"), theme:get("HairB"))
    gripRightGradient.Parent = gripRight
    self._gripRightGradient = gripRightGradient

    self:_makeDragHandle(grip, function(delta, start)
        -- Read the viewport at drag time, not construction: the player may
        -- resize or fullscreen the Roblox window mid-session.
        local liveViewport = workspace.CurrentCamera.ViewportSize
        local maxW = math.max(self._minSize.X, liveViewport.X)
        local maxH = math.max(self._minSize.Y, liveViewport.Y)
        self:setSize(
            math.clamp(start.X + delta.X, self._minSize.X, maxW),
            math.clamp(start.Y + delta.Y, self._minSize.Y, maxH))
    end, function() return frame.AbsoluteSize end)

    --== animation ==--
    self._anim = Anim.new(root, {
        frame = frame,
        contents = contents,
        barHeight = BAR_HEIGHT,
        fullSize = function() return self._fullSize end,
    })
    self._animate = opts.Animations ~= false

    --== cursor ==--
    self._cursor = Cursor.new(root, opts.Cursor, function()
        if not self._anim:isOpen() then return false end
        local mx, my = root:mouseInGuiSpace()
        local origin, extent = frame.AbsolutePosition, frame.AbsoluteSize
        return Cursor.hitTest(mx, my, origin.X, origin.Y, extent.X, extent.Y)
    end)

    --== toggle key ==--
    -- gameProcessedEvent is ignored by default: games sink keys, and O is
    -- sunk in one of the target games. RespectGameProcessed opts into that.
    self._toggleKey = opts.ToggleKey or Enum.KeyCode.Insert
    local respect = opts.RespectGameProcessed == true
    root:keep(UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if respect and gameProcessed then return end
        -- A Keybind capture owns the keyboard while it is open, or binding
        -- the toggle key would bind it and close the menu in one press.
        if root.capturing then return end
        local key = self._toggleKey
        if key == nil then return end
        if key.EnumType == Enum.UserInputType then
            if input.UserInputType == key then self:toggle() end
        elseif input.KeyCode == key then
            self:toggle()
        end
    end))

    -- Only one root:onFrame handler is allowed (Root:onFrame asserts on a
    -- second registration), so all per-frame window work lives here.
    root:onFrame(function(dt)
        self._backdrop:step(dt)
        local hairColor = ColorSequence.new(
            self._theme:get("HairA"), self._theme:get("HairB"))
        self._hairGradient.Color = hairColor
        self._hairGradientBottom.Color = hairColor
        self._bodyStrokeGradient.Color = hairColor
        self._gripBottomGradient.Color = hairColor
        self._gripRightGradient.Color = hairColor
    end)

    -- Built before any consumer page exists; fine, because a pinned page
    -- never auto-activates. Opting out is one flag rather than a separate
    -- constructor, since a consumer who doesn't want it is the rare case.
    if opts.Settings ~= false then
        self._settingsPage = Settings.build(root, self)
    end

    -- After every page is built (Settings included), so the tween can walk
    -- them. Rail.new is a no-op when Rail = { HoverExpand = false }.
    self._rail_ctl = Rail.new(root, self, opts.Rail)

    self:setSize(size.X, size.Y)
    self._anim:_snap(false)
    self:open()

    return self
end

-- Anything that reflows or replaces the view. The popup manager is the only
-- subscriber today; a list means the next one doesn't have to rewrite this.
function Window:onLayoutChanged(fn)
    table.insert(self._layoutListeners, fn)
end

function Window:_layoutChanged()
    for i = 1, #self._layoutListeners do
        self._layoutListeners[i]()
    end
end

function Window:_makeDragHandle(handle, onMove, readStart)
    local dragging, startMouse, startValue = false, nil, nil

    self._root:keep(handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            startMouse = UserInputService:GetMouseLocation()
            startValue = readStart()
        end
    end))

    self._root:keep(UserInputService.InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
            onMove(UserInputService:GetMouseLocation() - startMouse, startValue)
        end
    end))

    self._root:keep(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end))
end

function Window:setSize(width, height)
    self._fullSize = Vector2.new(width, height)
    if self._anim:isOpen() then
        self._frame.Size = UDim2.fromOffset(width, height)
    end
    self._backdrop:resize(width, height - (BAR_HEIGHT + BAR_GAP))

    -- Column widths are explicit pixels, so they must be recomputed whenever
    -- the window changes size.
    if self._pages then
        for i = 1, #self._pages do
            self._pages[i]:relayout()
        end
    end
    self:_layoutChanged()
end

function Window:Page(opts)
    local page = Page.new(self._root, self, opts or {})
    table.insert(self._pages, page)
    -- A pinned page must never become the default view. The settings page is
    -- built before any consumer page exists, so plain "first page wins" would
    -- open the menu on Settings every time.
    if not self._activePage and not page.pinned then
        self:setActivePage(page)
    else
        page:setActive(page == self._activePage)
    end
    return page
end

function Window:setActivePage(page)
    self._activePage = page
    for i = 1, #self._pages do
        self._pages[i]:setActive(self._pages[i] == page)
    end
    page:relayout()
    self:_layoutChanged()
end

function Window:getActivePage()
    return self._activePage
end

function Window:open()
    self._backdrop:setPaused(false)
    self._anim:open(self._animate)
    UserInputService.ModalEnabled = true
end

function Window:close()
    self:_layoutChanged()
    self._anim:close(self._animate)
    UserInputService.ModalEnabled = false
    -- Stars keep no state worth preserving, so pausing while hidden is free.
    -- +0.01 is a one-frame margin so the pause lands just after the final
    -- tween completes rather than racing it.
    task.delay(Anim.closeDuration() + 0.01, function()
        if not self._root:isAlive() then return end
        if not self._anim:isOpen() then
            self._backdrop:setPaused(true)
        end
    end)
end

function Window:toggle()
    if self._anim:isOpen() then
        self:close()
    else
        self:open()
    end
end

function Window:isOpen()
    return self._anim:isOpen()
end

function Window:setAccent(accent)
    self._theme:setAccent(accent)
    self._theme:apply()
end

-- The widget behind a flag. Chroma.Flags carries the plain value; anything
-- richer -- a keybind's IsHeld, a colour's alpha -- comes from here.
function Window:Flag(flag)
    return self._root.config:get(flag)
end

function Window:SaveConfig(name) return self._root.config:Save(name) end
function Window:LoadConfig(name) return self._root.config:Load(name) end
function Window:DeleteConfig(name) return self._root.config:Delete(name) end
function Window:ListConfigs() return self._root.config:List() end
function Window:GetAutoload() return self._root.config:GetAutoload() end
function Window:SetAutoload(name) return self._root.config:SetAutoload(name) end

-- Accepts a KeyCode, a bindable UserInputType, or nil for no toggle at all.
-- The settings page's Keybind writes here.
function Window:setToggleKey(key)
    self._toggleKey = key
end

function Window:setAnimations(on)
    self._animate = on ~= false
end

function Window:setGradient(enabled)
    self._theme:setGradient(enabled)
    self._theme:apply()
end

function Window:setAccentSpeed(speed)
    self._theme:setAccentSpeed(speed)
    self._theme:apply()
end

function Window:setCursor(opts)
    self._cursor:setConfig(opts)
end

function Window:setParticleCount(count)
    self._backdrop:setCount(count)
end

M.Window = Window
return M
end

__modules["init"] = function(require)
local Root = require("core/root")
local WindowModule = require("core/window")

local Chroma = {}

Chroma.version = "0.1.0"

function Chroma:Window(opts)
    if self.root then
        error("chroma: a window already exists; call Chroma:Unload() first", 2)
    end
    self.root = Root.new(opts)
    self.window = WindowModule.new(self.root, opts)
    -- The same table the config manager maintains, not a copy: a consumer
    -- polling Chroma.Flags.foo every frame reads live state.
    self.Flags = self.root.config.Flags
    return self.window
end

function Chroma:Unload()
    local UserInputService = game:GetService("UserInputService")
    UserInputService.ModalEnabled = false
    UserInputService.MouseIconEnabled = true
    if self.root then
        self.root:Unload()
        self.root = nil
    end
    self.window = nil
    self.Flags = nil
end

return Chroma
end

__modules["util/guard"] = function(require)
-- Generation counter for cancelling superseded animation chains.
-- Lua 5.4 / Luau intersection.
local Guard = {}
Guard.__index = Guard

function Guard.new()
    return setmetatable({ _gen = 0 }, Guard)
end

function Guard:begin()
    self._gen = self._gen + 1
    return self._gen
end

function Guard:isCurrent(token)
    return token == self._gen
end

-- Runs step only if token is still the live generation. Returns whether it ran,
-- so a caller can tell "cancelled" apart from "completed".
function Guard:run(token, step)
    if token ~= self._gen then return false end
    step()
    return true
end

function Guard:cancel()
    self._gen = self._gen + 1
end

return Guard
end

__modules["util/safecall"] = function(require)
-- Isolates CONSUMER callbacks. Chroma's own errors are deliberately not routed
-- through this: those are bugs and should surface loudly.
-- Lua 5.4 / Luau intersection.
local M = {}

local logger = nil

function M.setLogger(fn)
    logger = fn
end

local function report(label, err)
    local msg = "[Chroma] " .. tostring(label) .. " -> " .. tostring(err)
    if logger then
        logger(msg)
    else
        warn(msg)
    end
end

function M.call(label, fn, ...)
    if fn == nil then return nil end
    local ok, result = pcall(fn, ...)
    if not ok then
        report(label, result)
        return nil
    end
    return result
end

function M.wrap(label, fn)
    return function(...)
        return M.call(label, fn, ...)
    end
end

return M
end

__modules["util/signal"] = function(require)
-- Minimal signal. No Roblox dependency, so it is unit tested locally.
-- Lua 5.4 / Luau intersection: no compound assignment, no bitwise ops.
local Signal = {}
Signal.__index = Signal

local Connection = {}
Connection.__index = Connection

function Connection:disconnect()
    if self._dead then return end
    self._dead = true
    local listeners = self._signal._listeners
    for i = 1, #listeners do
        if listeners[i] == self then
            table.remove(listeners, i)
            return
        end
    end
end

function Signal.new()
    return setmetatable({ _listeners = {} }, Signal)
end

function Signal:connect(fn)
    local conn = setmetatable({ _signal = self, _fn = fn, _dead = false }, Connection)
    table.insert(self._listeners, conn)
    return conn
end

function Signal:fire(...)
    -- Iterate a copy: a listener may disconnect itself or others mid-fire.
    local snapshot = {}
    for i = 1, #self._listeners do snapshot[i] = self._listeners[i] end
    for i = 1, #snapshot do
        local conn = snapshot[i]
        if not conn._dead then conn._fn(...) end
    end
end

function Signal:count()
    return #self._listeners
end

function Signal:destroy()
    for i = 1, #self._listeners do self._listeners[i]._dead = true end
    self._listeners = {}
end

return Signal
end

__modules["widgets/button"] = function(require)
-- A full-width bordered button with the label centred.
--
-- It takes the whole row rather than sitting in the control slot: a left label
-- with a small button on the right reads as broken.

local safecall = require("util/safecall")

local M = {}

-- No control slot. See label.lua for the rationale.
M.FullWidth = true

-- A button is an action, not a value, so there is nothing to save.
M.Stateless = true

local Button = {}
Button.__index = Button

local ROW_HEIGHT = 22
local BOX_HEIGHT = 18

function M.new(root, row, opts)
    local theme = root.theme

    row.label.Text = ""
    row.setHeight(ROW_HEIGHT)

    local box = Instance.new("TextButton")
    box.Name = "button"
    box.AnchorPoint = Vector2.new(0.5, 0.5)
    box.Position = UDim2.fromScale(0.5, 0.5)
    box.Size = UDim2.new(1, 0, 0, BOX_HEIGHT)
    box.BorderSizePixel = 0
    box.Font = Enum.Font.Ubuntu
    box.TextSize = 11
    box.Text = opts.Text or opts.Name or "Button"
    box.AutoButtonColor = false
    -- Above the row's own hit button (ZIndex 2), or the row swallows the click.
    box.ZIndex = 3
    box.Parent = row.frame
    theme:bind(box, "BackgroundColor3", "Field")
    theme:bind(box, "TextColor3", "Text")

    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Parent = box
    theme:bind(stroke, "Color", "FieldBorder")

    -- Rebind rather than write directly: theme:apply() runs every frame while
    -- the accent animates, so a binding keeps cycling instead of freezing at
    -- whatever hue was current on MouseEnter.
    root:keep(box.MouseEnter:Connect(function()
        theme:unbind(stroke)
        theme:unbind(box)
        theme:bind(stroke, "Color", "Accent")
        theme:bind(box, "BackgroundColor3", "Field")
        theme:bind(box, "TextColor3", "TextBright")
    end))

    root:keep(box.MouseLeave:Connect(function()
        theme:unbind(stroke)
        theme:unbind(box)
        theme:bind(stroke, "Color", "FieldBorder")
        theme:bind(box, "BackgroundColor3", "Field")
        theme:bind(box, "TextColor3", "Text")
    end))

    local self = setmetatable({
        _root = root,
        _row = row,
        _label = opts.Name or opts.Text or "Button",
        _callback = opts.Callback,
    }, Button)

    root:keep(box.Activated:Connect(function()
        safecall.call(self._label, self._callback)
    end))

    return self
end

-- A Button has no value. The methods exist anyway, for the same reason
-- Separator's do: a caller must not have to know which widgets have them.
function Button:Get() return nil end
function Button:Set() end
function Button:OnChanged() end
function Button:SetVisible(visible) self._row.frame.Visible = visible end

return M
end

__modules["widgets/colorpicker"] = function(require)
-- Colorpicker: the pure text parsing, plus the swatch, the HSV square, the hue
-- and alpha strips and the text field.
--
-- parseColor and toHex are unit tested, so keep them in the Lua 5.4 / Luau
-- intersection: no compound assignment, no bitwise ops, no goto. That also
-- means no Color3 construction here -- these deal in plain numbers, and the
-- Instance half converts.

local M = {}

-- Channels are 0..255 and alpha is 0..1, matching how each is written by hand.
local function clampByte(n)
    n = math.floor(n + 0.5)
    if n < 0 then return 0 end
    if n > 255 then return 255 end
    return n
end

-- Returns r, g, b, a or nil. Unparseable input is user error at runtime, not a
-- programming mistake, so the caller reverts silently rather than erroring --
-- exactly as the slider's typed value does.
function M.parseColor(text)
    if type(text) ~= "string" then return nil end

    local s = text:gsub("%s", "")
    if s == "" then return nil end

    -- Sniffed on the comma rather than by asking the caller which format it is:
    -- the whole point of one field is that it takes either.
    if s:find(",", 1, true) then
        local parts = {}
        for piece in s:gmatch("[^,]+") do
            table.insert(parts, tonumber(piece))
        end
        if #parts < 3 or #parts > 4 then return nil end
        for i = 1, #parts do
            if parts[i] == nil then return nil end
        end

        local a = parts[4]
        if a == nil then
            a = 1
        elseif a > 1 then
            -- 255,0,0,255 means opaque. Clamping is what they meant; rejecting
            -- it would be pedantic about a format nobody agreed on.
            a = 1
        elseif a < 0 then
            a = 0
        end
        return clampByte(parts[1]), clampByte(parts[2]), clampByte(parts[3]), a
    end

    local hex = s:gsub("^#", "")
    if hex:match("^%x+$") == nil then return nil end

    local n = #hex
    if n == 3 or n == 4 then
        -- Each digit doubles: F -> FF, which is 15 * 17 = 255.
        local r = tonumber(hex:sub(1, 1), 16) * 17
        local g = tonumber(hex:sub(2, 2), 16) * 17
        local b = tonumber(hex:sub(3, 3), 16) * 17
        local a = 1
        if n == 4 then a = tonumber(hex:sub(4, 4), 16) * 17 / 255 end
        return r, g, b, a
    end
    if n == 6 or n == 8 then
        local r = tonumber(hex:sub(1, 2), 16)
        local g = tonumber(hex:sub(3, 4), 16)
        local b = tonumber(hex:sub(5, 6), 16)
        local a = 1
        if n == 8 then a = tonumber(hex:sub(7, 8), 16) / 255 end
        return r, g, b, a
    end
    return nil
end

-- Hex is the display format, being the compact one. Alpha is appended only when
-- the picker has an alpha strip at all.
function M.toHex(r, g, b, a)
    if a == nil then
        return string.format("#%02X%02X%02X", clampByte(r), clampByte(g), clampByte(b))
    end
    return string.format("#%02X%02X%02X%02X",
        clampByte(r), clampByte(g), clampByte(b), clampByte(a * 255))
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

local safecall = require("util/safecall")

-- Resolved lazily: a module-scope game:GetService() executes on require, and
-- the harness requires this file to reach parseColor.
local UserInputService

local Colorpicker = {}
Colorpicker.__index = Colorpicker

local PAD = 7
local INNER = 162
local WIDTH = INNER + PAD * 2   -- 176
local SQUARE_H = 96
local STRIP_H = 10
local STRIP_GAP = 6
local FIELD_H = 16
local FIELD_GAP = 7
local CHEQUER = 5   -- chequerboard cell, in pixels

local SWATCH = 12
local SWATCH_GAP = 3
local SWATCH_ROW_GAP = 6

local function popupHeight(hasAlpha)
    local strips = hasAlpha and 2 or 1
    return PAD + SQUARE_H + strips * (STRIP_GAP + STRIP_H)
        + FIELD_GAP + FIELD_H
        + SWATCH_ROW_GAP + SWATCH
        + PAD
end

function M.new(root, row, opts)
    UserInputService = UserInputService or game:GetService("UserInputService")

    local theme = root.theme

    local default = opts.Default or Color3.fromRGB(255, 255, 255)
    if typeof(default) ~= "Color3" then
        -- A non-Color3 Default can only be a typo, and silently falling back to
        -- white hides it.
        error(string.format("chroma: colorpicker '%s' Default must be a Color3, got %s",
            tostring(opts.Name), typeof(default)), 2)
    end

    local hasAlpha = type(opts.Alpha) == "number"

    --== closed state: a 110px swatch filling the control slot ==--
    -- A small square leaves dead space beside it and is a poor click target.
    local swatch = Instance.new("TextButton")
    swatch.Name = "swatch"
    swatch.AnchorPoint = Vector2.new(1, 0.5)
    swatch.Position = UDim2.new(1, 0, 0.5, 0)
    swatch.Size = UDim2.new(1, 0, 0, 14)
    swatch.BorderSizePixel = 0
    swatch.Text = ""
    swatch.AutoButtonColor = false
    swatch.Parent = row.control

    local swatchStroke = Instance.new("UIStroke")
    swatchStroke.Thickness = 1
    swatchStroke.Parent = swatch
    theme:bind(swatchStroke, "Color", "FieldBorder")

    --== the popup ==--
    local popup = Instance.new("Frame")
    popup.Name = "colorpicker"
    popup.Size = UDim2.fromOffset(WIDTH, popupHeight(hasAlpha))
    popup.BorderSizePixel = 0
    popup.Visible = false
    popup.ZIndex = 10
    popup.Parent = root.popupLayer
    root:keep(popup)
    theme:bind(popup, "BackgroundColor3", "Window")

    local popupStroke = Instance.new("UIStroke")
    popupStroke.Thickness = 1
    popupStroke.Parent = popup
    theme:bind(popupStroke, "Color", "Accent")

    -- The saturation/value square: a pure-hue base with a white gradient across
    -- it and a black gradient down it. Roblox has no HSV picker primitive, and
    -- two gradients reproduce one exactly -- no image asset, no upload to
    -- moderate, and it recolours by writing one BackgroundColor3.
    local square = Instance.new("Frame")
    square.Name = "square"
    square.Position = UDim2.fromOffset(PAD, PAD)
    square.Size = UDim2.fromOffset(INNER, SQUARE_H)
    square.BorderSizePixel = 0
    square.BackgroundColor3 = Color3.fromHSV(0, 1, 1)
    square.ZIndex = 11
    square.Parent = popup

    local satLayer = Instance.new("Frame")
    satLayer.Name = "saturation"
    satLayer.Size = UDim2.fromScale(1, 1)
    satLayer.BackgroundColor3 = Color3.new(1, 1, 1)
    satLayer.BorderSizePixel = 0
    satLayer.ZIndex = 12
    satLayer.Parent = square
    local satGradient = Instance.new("UIGradient")
    satGradient.Transparency = NumberSequence.new(0, 1)
    satGradient.Parent = satLayer

    local valLayer = Instance.new("Frame")
    valLayer.Name = "value"
    valLayer.Size = UDim2.fromScale(1, 1)
    valLayer.BackgroundColor3 = Color3.new(0, 0, 0)
    valLayer.BorderSizePixel = 0
    valLayer.ZIndex = 13
    valLayer.Parent = square
    local valGradient = Instance.new("UIGradient")
    valGradient.Rotation = 90
    valGradient.Transparency = NumberSequence.new(1, 0)
    valGradient.Parent = valLayer

    local squareMarker = Instance.new("Frame")
    squareMarker.Name = "marker"
    squareMarker.AnchorPoint = Vector2.new(0.5, 0.5)
    squareMarker.Size = UDim2.fromOffset(7, 7)
    squareMarker.BackgroundTransparency = 1
    squareMarker.BorderSizePixel = 0
    squareMarker.ZIndex = 14
    squareMarker.Parent = square
    local markerCorner = Instance.new("UICorner")
    markerCorner.CornerRadius = UDim.new(1, 0)
    markerCorner.Parent = squareMarker
    local markerStroke = Instance.new("UIStroke")
    markerStroke.Thickness = 1
    markerStroke.Color = Color3.new(1, 1, 1)
    markerStroke.Parent = squareMarker

    local function makeStrip(name, y)
        local strip = Instance.new("Frame")
        strip.Name = name
        strip.Position = UDim2.fromOffset(PAD, y)
        strip.Size = UDim2.fromOffset(INNER, STRIP_H)
        strip.BorderSizePixel = 0
        strip.BackgroundColor3 = Color3.new(1, 1, 1)
        strip.ZIndex = 11
        strip.Parent = popup

        local marker = Instance.new("Frame")
        marker.Name = "marker"
        marker.AnchorPoint = Vector2.new(0.5, 0.5)
        marker.Position = UDim2.fromScale(0, 0.5)
        marker.Size = UDim2.fromOffset(2, STRIP_H + 4)
        marker.BackgroundColor3 = Color3.new(1, 1, 1)
        marker.BorderSizePixel = 0
        marker.ZIndex = 15
        marker.Parent = strip
        local outline = Instance.new("UIStroke")
        outline.Thickness = 1
        outline.Color = Color3.new(0, 0, 0)
        outline.Transparency = 0.4
        outline.Parent = marker

        return strip, marker
    end

    local hueY = PAD + SQUARE_H + STRIP_GAP
    local hueStrip, hueMarker = makeStrip("hue", hueY)
    -- A UIGradient multiplies its element's colour, which is why the strip's own
    -- BackgroundColor3 is white above.
    local hueGradient = Instance.new("UIGradient")
    hueGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
        ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
        ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 255)),
        ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
        ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
        ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
    })
    hueGradient.Parent = hueStrip

    local alphaStrip, alphaMarker, alphaGradient
    if hasAlpha then
        alphaStrip, alphaMarker = makeStrip("alpha", hueY + STRIP_H + STRIP_GAP)

        -- The chequerboard is built from plain Frames rather than a tiled image:
        -- an image would mean uploading and moderating an asset for a 162x10
        -- strip, and only half the cells need drawing over a flat base. It is
        -- the honest way to show transparency and the only textured element in
        -- an otherwise flat UI.
        local base = Instance.new("Frame")
        base.Name = "chequer"
        base.Size = UDim2.fromScale(1, 1)
        base.BackgroundColor3 = Color3.fromRGB(58, 63, 65)
        base.BorderSizePixel = 0
        base.ClipsDescendants = true
        base.ZIndex = 11
        base.Parent = alphaStrip

        local cols = math.ceil(INNER / CHEQUER)
        local rows = math.ceil(STRIP_H / CHEQUER)
        for cx = 0, cols - 1 do
            for cy = 0, rows - 1 do
                if (cx + cy) % 2 == 0 then
                    local cell = Instance.new("Frame")
                    cell.Name = "cell"
                    cell.Position = UDim2.fromOffset(cx * CHEQUER, cy * CHEQUER)
                    cell.Size = UDim2.fromOffset(CHEQUER, CHEQUER)
                    cell.BackgroundColor3 = Color3.fromRGB(34, 40, 42)
                    cell.BorderSizePixel = 0
                    cell.ZIndex = 11
                    cell.Parent = base
                end
            end
        end

        local wash = Instance.new("Frame")
        wash.Name = "wash"
        wash.Size = UDim2.fromScale(1, 1)
        wash.BackgroundColor3 = Color3.new(1, 1, 1)
        wash.BorderSizePixel = 0
        wash.ZIndex = 12
        wash.Parent = alphaStrip
        alphaGradient = Instance.new("UIGradient")
        alphaGradient.Transparency = NumberSequence.new(1, 0)
        alphaGradient.Parent = wash

        alphaMarker.ZIndex = 15
    end

    --== the one text field, taking hex or RGB(A) ==--
    local input = Instance.new("TextBox")
    input.Name = "input"
    input.Position = UDim2.fromOffset(PAD, popupHeight(hasAlpha) - PAD - FIELD_H)
    input.Size = UDim2.fromOffset(INNER, FIELD_H)
    input.BorderSizePixel = 0
    input.Font = Enum.Font.Ubuntu
    input.TextSize = 11
    input.ClearTextOnFocus = false
    input.Text = ""
    input.ZIndex = 12
    input.Parent = popup
    theme:bind(input, "BackgroundColor3", "Field")
    theme:bind(input, "TextColor3", "Text")

    local inputStroke = Instance.new("UIStroke")
    inputStroke.Thickness = 1
    inputStroke.Parent = input
    theme:bind(inputStroke, "Color", "FieldBorder")

    --== saved colours ==--
    -- Eleven cells across 162px: ten swatches and a + to save the current
    -- colour. Left-click applies, right-click deletes.
    local swatchRow = Instance.new("Frame")
    swatchRow.Name = "swatches"
    swatchRow.Position = UDim2.fromOffset(PAD, popupHeight(hasAlpha) - PAD - SWATCH)
    swatchRow.Size = UDim2.fromOffset(INNER, SWATCH)
    swatchRow.BackgroundTransparency = 1
    swatchRow.BorderSizePixel = 0
    swatchRow.ZIndex = 12
    swatchRow.Parent = popup

    local swatchLayout = Instance.new("UIListLayout")
    swatchLayout.FillDirection = Enum.FillDirection.Horizontal
    swatchLayout.SortOrder = Enum.SortOrder.LayoutOrder
    swatchLayout.Padding = UDim.new(0, SWATCH_GAP)
    swatchLayout.Parent = swatchRow

    local addButton = Instance.new("TextButton")
    addButton.Name = "add"
    addButton.Size = UDim2.fromOffset(SWATCH, SWATCH)
    addButton.BorderSizePixel = 0
    addButton.Font = Enum.Font.Ubuntu
    addButton.TextSize = 11
    addButton.Text = "+"
    addButton.AutoButtonColor = false
    addButton.LayoutOrder = 999
    addButton.ZIndex = 13
    addButton.Parent = swatchRow
    theme:bind(addButton, "BackgroundColor3", "Field")
    theme:bind(addButton, "TextColor3", "TextDim")

    local addStroke = Instance.new("UIStroke")
    addStroke.Thickness = 1
    addStroke.Parent = addButton
    theme:bind(addStroke, "Color", "FieldBorder")

    local h0, s0, v0 = default:ToHSV()
    local self = setmetatable({
        _root = root,
        _row = row,
        _theme = theme,
        _swatch = swatch,
        _popup = popup,
        _square = square,
        _squareMarker = squareMarker,
        _hueMarker = hueMarker,
        _alphaMarker = alphaMarker,
        _alphaGradient = alphaGradient,
        _input = input,
        _hasAlpha = hasAlpha,
        _editing = false,
        _h = h0, _s = s0, _v = v0,
        _a = hasAlpha and opts.Alpha or 1,
        _label = opts.Name or "Colorpicker",
        _callback = opts.Callback,
        _listeners = {},
        _swatches = {},
        _swatchRow = swatchRow,
    }, Colorpicker)

    root:keep(swatch.Activated:Connect(function()
        self:_toggle()
    end))

    -- Drag handling mirrors the slider's: press to jump, InputChanged to track,
    -- InputEnded to release. One shared `self._dragging` target rather than
    -- three flags, so two areas can never both think they are being dragged.
    -- Kept on self, not as an upvalue, so _toggle's popup onClose (below) can
    -- reach in and cancel a drag that outlives the popup that started it.
    self._dragging = nil

    local function applyFromMouse()
        if self._dragging == nil then return end
        local mx, my = root:mouseInGuiSpace()
        if self._dragging == "square" then
            local p, size = square.AbsolutePosition, square.AbsoluteSize
            local fx = size.X > 0 and (mx - p.X) / size.X or 0
            local fy = size.Y > 0 and (my - p.Y) / size.Y or 0
            self._s = math.clamp(fx, 0, 1)
            self._v = 1 - math.clamp(fy, 0, 1)
        elseif self._dragging == "hue" then
            local p, size = hueStrip.AbsolutePosition, hueStrip.AbsoluteSize
            local fx = size.X > 0 and (mx - p.X) / size.X or 0
            self._h = math.clamp(fx, 0, 1)
        elseif self._dragging == "alpha" and alphaStrip then
            local p, size = alphaStrip.AbsolutePosition, alphaStrip.AbsoluteSize
            local fx = size.X > 0 and (mx - p.X) / size.X or 0
            self._a = math.clamp(fx, 0, 1)
        end
        self:_paint()
        self:_fire()
    end

    local function grab(target, instance)
        root:keep(instance.InputBegan:Connect(function(input2)
            if input2.UserInputType == Enum.UserInputType.MouseButton1 then
                self._dragging = target
                applyFromMouse()
            end
        end))
    end

    grab("square", square)
    grab("hue", hueStrip)
    if alphaStrip then grab("alpha", alphaStrip) end

    root:keep(UserInputService.InputChanged:Connect(function(input2)
        if self._dragging and input2.UserInputType == Enum.UserInputType.MouseMovement then
            applyFromMouse()
        end
    end))

    root:keep(UserInputService.InputEnded:Connect(function(input2)
        if input2.UserInputType == Enum.UserInputType.MouseButton1 then
            self._dragging = nil
        end
    end))

    root:keep(input.Focused:Connect(function()
        self._editing = true
    end))

    root:keep(input.FocusLost:Connect(function()
        self._editing = false
        local r, g, b, a = M.parseColor(input.Text)
        if r == nil then
            -- Unparseable input reverts, exactly as the slider does. This is
            -- user input at runtime, not a programming mistake.
            self:_paint()
            return
        end
        local colour = Color3.fromRGB(r, g, b)
        self._h, self._s, self._v = colour:ToHSV()
        if self._hasAlpha then self._a = a end
        self:_paint()
        self:_fire()
    end))

    root:keep(addButton.Activated:Connect(function()
        root.palette:Add(self:_colour())
    end))

    -- Every colorpicker shares one palette, so each redraws when it changes.
    root.palette:onChanged(function()
        if not root:isAlive() then return end
        self:_paintSwatches()
    end)

    self:_paintSwatches()

    self:_paint()
    return self
end

function Colorpicker:_colour()
    return Color3.fromHSV(self._h, self._s, self._v)
end

function Colorpicker:_paint()
    local colour = self:_colour()

    self._swatch.BackgroundColor3 = colour
    if self._hasAlpha then
        self._swatch.BackgroundTransparency = 1 - self._a
    end

    self._square.BackgroundColor3 = Color3.fromHSV(self._h, 1, 1)
    self._squareMarker.Position = UDim2.fromScale(self._s, 1 - self._v)
    self._hueMarker.Position = UDim2.fromScale(self._h, 0.5)

    if self._hasAlpha then
        self._alphaMarker.Position = UDim2.fromScale(self._a, 0.5)
        -- The wash fades from transparent to the current colour, so the strip
        -- always previews the actual alpha range for what is selected.
        self._alphaGradient.Color = ColorSequence.new(colour, colour)
    end

    -- Leave the text alone mid-edit, or a live drag would overwrite what is
    -- being typed.
    if not self._editing then
        local r = math.floor(colour.R * 255 + 0.5)
        local g = math.floor(colour.G * 255 + 0.5)
        local b = math.floor(colour.B * 255 + 0.5)
        self._input.Text = M.toHex(r, g, b, self._hasAlpha and self._a or nil)
    end
end

-- Rebuilt wholesale rather than diffed: at most ten cells, and the palette
-- changes only on an explicit add or delete.
function Colorpicker:_paintSwatches()
    for i = 1, #self._swatches do
        -- Destroying an Instance does not remove its theme bindings, so apply()
        -- would keep writing to a destroyed object every frame.
        self._theme:unbind(self._swatches[i])
        self._swatches[i]:Destroy()
    end
    self._swatches = {}

    local colours = self._root.palette:Get()
    for i = 1, #colours do
        local cell = Instance.new("TextButton")
        cell.Name = "swatch"
        cell.Size = UDim2.fromOffset(12, 12)
        cell.BackgroundColor3 = colours[i]
        cell.BorderSizePixel = 0
        cell.Text = ""
        cell.AutoButtonColor = false
        cell.LayoutOrder = i
        cell.ZIndex = 13
        cell.Parent = self._swatchRow

        local stroke = Instance.new("UIStroke")
        stroke.Thickness = 1
        stroke.Parent = cell
        self._theme:bind(stroke, "Color", "FieldBorder")

        local colour = colours[i]
        local index = i

        -- Tied to the cell's lifetime rather than root:keep, because the row is
        -- rebuilt on every palette change and a keep per rebuild would grow the
        -- teardown list forever.
        cell.Activated:Connect(function()
            self:Set(colour)
        end)
        cell.MouseButton2Click:Connect(function()
            self._root.palette:Remove(index)
        end)

        table.insert(self._swatches, cell)
    end
end

function Colorpicker:_toggle()
    local popup = self._root.popup
    if popup:isOpen(self) then
        popup:close()
        return
    end
    -- The popup can close from things other than the swatch click that opened
    -- it -- bindDismissal routes window drag/reflow straight to popup:close().
    -- Without this, a hex edit left focused keeps engine-side focus while
    -- hidden (FocusLost never fires, so _editing never clears and _paint stops
    -- updating the hex text), and a drag left in progress keeps applying
    -- against the hidden popup's stale geometry, still firing the callback.
    popup:open(self, self._popup, self._swatch, function()
        self._input:ReleaseFocus()
        self._dragging = nil
    end)
end

function Colorpicker:_fire()
    local colour = self:_colour()
    safecall.call(self._label, self._callback, colour, self._a)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], colour, self._a)
    end
end

-- Returns the Color3 and, as a second value, the alpha. Two returns rather than
-- a table: a consumer that only wants the colour writes `local c = cp:Get()`
-- and is done.
function Colorpicker:Get()
    return self:_colour(), self._a
end

function Colorpicker:Set(colour, silent)
    if typeof(colour) ~= "Color3" then return end
    local h, s, v = colour:ToHSV()
    local changed = h ~= self._h or s ~= self._s or v ~= self._v
    self._h, self._s, self._v = h, s, v
    self:_paint()
    if silent or not changed then return end
    self:_fire()
end

function Colorpicker:SetAlpha(a, silent)
    if type(a) ~= "number" or not self._hasAlpha then return end
    a = math.clamp(a, 0, 1)
    local changed = a ~= self._a
    self._a = a
    self:_paint()
    if silent or not changed then return end
    self:_fire()
end

-- Alpha is state that Get() returns second, so it travels alongside the colour.
function Colorpicker:Save()
    return { colour = self:_colour(), alpha = self._a }
end

function Colorpicker:Load(t)
    if type(t) ~= "table" then return end
    if t.alpha ~= nil then self:SetAlpha(t.alpha, true) end
    self:Set(t.colour)
end

function Colorpicker:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function Colorpicker:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/dropdown"] = function(require)
-- A field in the control slot that opens a list in the popup layer.
--
-- Single-select commits and closes on click. Multi-select ticks a 7px checkbox
-- matching Toggle's -- so "this is a thing you tick" reads the same everywhere
-- -- and stays open, because picking several is the point.

local Field = require("core/field")
local safecall = require("util/safecall")

local M = {}

local Dropdown = {}
Dropdown.__index = Dropdown

local ENTRY_HEIGHT = 16
local MAX_VISIBLE = 8   -- past this the list scrolls; more than ~8 rows floating
                        -- over the menu stops reading as a menu
local WIDTH = 110       -- matches Row.CONTROL_WIDTH, so the popup lines up with
                        -- the field it came from

function M.new(root, row, opts)
    local theme = root.theme

    -- U+25BC. If this ever renders as a box in-game, fall back to "v" in
    -- Enum.Font.Code.
    local field = Field.new(root, row.control, { Glyph = "\u{25BC}" })

    local popup = Instance.new("Frame")
    popup.Name = "dropdown"
    popup.Size = UDim2.fromOffset(WIDTH, ENTRY_HEIGHT)   -- real height set by _rebuild
    popup.BorderSizePixel = 0
    popup.Visible = false
    popup.ZIndex = 10
    popup.Parent = root.popupLayer
    root:keep(popup)
    theme:bind(popup, "BackgroundColor3", "Window")

    local popupStroke = Instance.new("UIStroke")
    popupStroke.Thickness = 1
    popupStroke.Parent = popup
    theme:bind(popupStroke, "Color", "Accent")

    local list = Instance.new("ScrollingFrame")
    list.Name = "list"
    list.Size = UDim2.fromScale(1, 1)
    list.BackgroundTransparency = 1
    list.BorderSizePixel = 0
    list.CanvasSize = UDim2.new()
    -- The property is AutomaticCanvasSize, but its type is Enum.AutomaticSize.
    -- There is no Enum.AutomaticCanvasSize.
    list.AutomaticCanvasSize = Enum.AutomaticSize.Y
    list.ScrollBarThickness = 2
    list.ScrollingDirection = Enum.ScrollingDirection.Y
    list.ElasticBehavior = Enum.ElasticBehavior.Never
    list.ZIndex = 11
    list.Parent = popup
    theme:bind(list, "ScrollBarImageColor3", "Accent")

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = list

    local multi = opts.Multi == true
    local self = setmetatable({
        _root = root,
        _row = row,
        _theme = theme,
        _field = field,
        _popup = popup,
        _list = list,
        _entries = {},
        _options = opts.Options or {},
        _multi = multi,
        _selected = {},
        _value = nil,
        _label = opts.Name or "Dropdown",
        _callback = opts.Callback,
        _listeners = {},
    }, Dropdown)

    self:_rebuild()

    root:keep(field.frame.Activated:Connect(function()
        self:_toggle()
    end))

    -- A Default that is not in Options can only be a typo, and silently
    -- selecting nothing hides it.
    local default = opts.Default
    if default ~= nil then
        if multi then
            if type(default) ~= "table" then
                error(string.format(
                    "chroma: multi dropdown '%s' needs an array Default, got %s",
                    tostring(opts.Name), type(default)), 2)
            end
            for i = 1, #default do
                if not self:_has(default[i]) then
                    error(string.format(
                        "chroma: dropdown '%s' Default '%s' is not in Options",
                        tostring(opts.Name), tostring(default[i])), 2)
                end
            end
        elseif not self:_has(default) then
            error(string.format(
                "chroma: dropdown '%s' Default '%s' is not in Options",
                tostring(opts.Name), tostring(default)), 2)
        end
    end

    self:Set(default, true)
    return self
end

function Dropdown:_has(value)
    for i = 1, #self._options do
        if self._options[i] == value then return true end
    end
    return false
end

function Dropdown:_rebuild()
    local theme = self._theme
    for i = 1, #self._entries do
        local e = self._entries[i]
        -- Destroying an Instance does NOT remove its theme bindings: apply()
        -- would keep writing to a destroyed object every frame, and the binding
        -- list would grow without bound on every SetOptions call.
        theme:unbind(e.button)
        theme:unbind(e.label)
        if e.box then
            theme:unbind(e.box)
            theme:unbind(e.boxStroke)
        end
        e.button:Destroy()
    end
    self._entries = {}

    for i = 1, #self._options do
        local text = self._options[i]

        local button = Instance.new("TextButton")
        button.Name = "entry"
        button.Size = UDim2.new(1, 0, 0, ENTRY_HEIGHT)
        button.BackgroundTransparency = 1
        button.BorderSizePixel = 0
        button.Text = ""
        button.AutoButtonColor = false
        button.LayoutOrder = i
        button.ZIndex = 12
        button.Parent = self._list

        local box, boxStroke
        local textX = 5
        if self._multi then
            box = Instance.new("Frame")
            box.Name = "box"
            box.AnchorPoint = Vector2.new(0, 0.5)
            box.Position = UDim2.new(0, 5, 0.5, 0)
            box.Size = UDim2.fromOffset(7, 7)
            box.BorderSizePixel = 0
            box.ZIndex = 13
            box.Parent = button

            boxStroke = Instance.new("UIStroke")
            boxStroke.Thickness = 1
            boxStroke.Parent = box

            textX = 17   -- 5 padding + 7 box + 5 gap
        end

        local label = Instance.new("TextLabel")
        label.Name = "text"
        label.BackgroundTransparency = 1
        label.Position = UDim2.fromOffset(textX, 0)
        label.Size = UDim2.new(1, -(textX + 5), 1, 0)
        label.Font = Enum.Font.Ubuntu
        label.TextSize = 11
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextTruncate = Enum.TextTruncate.AtEnd
        label.Text = tostring(text)
        label.ZIndex = 13
        label.Parent = button

        self._entries[i] = {
            button = button, label = label, box = box,
            boxStroke = boxStroke, text = text,
        }

        -- Entries are destroyed and rebuilt by SetOptions, so their connections
        -- must die with them. Parenting the connection to the button's own
        -- lifetime (rather than root:keep) is what stops the junk list growing
        -- every time a consumer refreshes the options.
        button.Activated:Connect(function()
            self:_choose(text)
        end)
    end

    -- An explicit pixel height, not AutomaticSize: the popup manager reads
    -- Size.Y.Offset to place the frame before it has ever rendered.
    local visible = #self._options
    if visible > MAX_VISIBLE then visible = MAX_VISIBLE end
    if visible < 1 then visible = 1 end
    self._popup.Size = UDim2.fromOffset(WIDTH, visible * ENTRY_HEIGHT)

    self:_paint()
end

function Dropdown:_caption()
    if not self._multi then
        -- "none" rather than a blank field: an empty control reads as broken
        -- rather than as an empty selection, and it matches what multi-select
        -- already shows for the same state. An option literally named "none"
        -- displays identically; that collision is accepted rather than escaped,
        -- since Get() still returns the real value and nothing else here
        -- reserves the string.
        return self._value ~= nil and tostring(self._value) or "none"
    end
    local n, only = 0, nil
    for i = 1, #self._options do
        if self._selected[self._options[i]] then
            n = n + 1
            if only == nil then only = self._options[i] end
        end
    end
    if n == 0 then return "none" end
    -- One pick reads better as its own name than as "1 selected". Past that a
    -- comma list truncates uselessly at 110px, so a count is the honest summary.
    if n == 1 then return tostring(only) end
    return tostring(n) .. " selected"
end

function Dropdown:_paint()
    local theme = self._theme
    for i = 1, #self._entries do
        local e = self._entries[i]
        if self._multi then
            local on = self._selected[e.text] == true
            theme:unbind(e.box)
            theme:unbind(e.boxStroke)
            theme:bind(e.box, "BackgroundColor3", on and "Accent" or "Field")
            theme:bind(e.boxStroke, "Color", on and "Accent" or "FieldBorder")
        else
            local on = self._value == e.text
            theme:unbind(e.button)
            theme:unbind(e.label)
            if on then
                theme:bind(e.button, "BackgroundColor3", "Selection", "BackgroundTransparency")
                theme:bind(e.label, "TextColor3", "Accent")
            else
                e.button.BackgroundTransparency = 1
                theme:bind(e.label, "TextColor3", "Text")
            end
        end
    end
    self._field.label.Text = self:_caption()
end

function Dropdown:_toggle()
    local popup = self._root.popup
    if popup:isOpen(self) then
        popup:close()
        return
    end
    self._field.setActive(true)
    popup:open(self, self._popup, self._field.frame, function()
        self._field.setActive(false)
    end)
end

function Dropdown:_choose(text)
    if self._multi then
        if self._selected[text] then
            self._selected[text] = nil
        else
            self._selected[text] = true
        end
        self:_paint()
        self:_fire()
        -- Deliberately stays open.
    else
        self:Set(text)
        self._root.popup:close()
    end
end

function Dropdown:_fire()
    local value = self:Get()
    safecall.call(self._label, self._callback, value)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], value)
    end
end

-- A string for single-select, a fresh array in Options order for multi.
function Dropdown:Get()
    if not self._multi then return self._value end
    local out = {}
    for i = 1, #self._options do
        if self._selected[self._options[i]] then
            table.insert(out, self._options[i])
        end
    end
    return out
end

function Dropdown:Set(value, silent)
    if self._multi then
        local set = {}
        if type(value) == "table" then
            for i = 1, #value do set[value[i]] = true end
        end
        self._selected = set
        self:_paint()
        -- No change detection for multi: comparing two sets to decide whether to
        -- fire costs more than the spurious callback it would save.
        if silent then return end
        self:_fire()
        return
    end

    -- An unknown value at RUNTIME is not the same as a bad Default: a consumer
    -- restoring a stale config should be ignored, not crashed.
    if value ~= nil and not self:_has(value) then return end
    local changed = value ~= self._value
    self._value = value
    self:_paint()
    if silent or not changed then return end
    self:_fire()
end

-- Replaces the contents, keeping any still-valid selection.
function Dropdown:SetOptions(list)
    self._options = list or {}
    if self._multi then
        local kept = {}
        for i = 1, #self._options do
            if self._selected[self._options[i]] then kept[self._options[i]] = true end
        end
        self._selected = kept
    elseif self._value ~= nil and not self:_has(self._value) then
        self._value = nil
    end
    self:_rebuild()
end

function Dropdown:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function Dropdown:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/init"] = function(require)
-- The single registration point for widgets. container.lua generates its
-- methods from this map, so it never learns what any individual widget is --
-- adding a widget is one line here plus one new file.

return {
    Label = require("widgets/label"),
    Separator = require("widgets/separator"),
    Toggle = require("widgets/toggle"),
    Slider = require("widgets/slider"),
    Dropdown = require("widgets/dropdown"),
    Button = require("widgets/button"),
    TextBox = require("widgets/textbox"),
    Keybind = require("widgets/keybind"),
    Colorpicker = require("widgets/colorpicker"),
    ListBox = require("widgets/listbox"),
}
end

__modules["widgets/keybind"] = function(require)
-- Keybind: the pure display-name mapping, plus capture, the mode menu, and
-- IsHeld.
--
-- formatKey is unit tested, so keep it in the Lua 5.4 / Luau intersection:
-- no compound assignment, no bitwise ops, no goto. That also means no Enum
-- values at module scope -- the harness has no `Enum` global.

local M = {}

-- The only bindable mouse inputs there are. Roblox delivers no event at all for
-- side buttons 4 and 5, and Enum.KeyCode.MouseBackButton is a dead legacy entry
-- InputBegan never fires. Proven in-game with a logger.
local MOUSE = {
    MouseButton1 = "MOUSE1",
    MouseButton2 = "MOUSE2",
    MouseButton3 = "MOUSE3",
}

-- Anything that would overflow the field at 11px, or reads badly upper-cased.
local SHORT = {
    LeftShift = "LSHIFT",   RightShift = "RSHIFT",
    LeftControl = "LCTRL",  RightControl = "RCTRL",
    LeftAlt = "LALT",       RightAlt = "RALT",
    LeftSuper = "LWIN",     RightSuper = "RWIN",
    CapsLock = "CAPS",      Backspace = "BACK",
    Return = "ENTER",       Escape = "ESC",
    Delete = "DEL",         PageUp = "PGUP",
    PageDown = "PGDN",      Space = "SPACE",
}

-- Takes NAMES rather than EnumItems so it can be tested without a Roblox
-- environment. The caller unwraps .Name.
function M.formatKey(inputTypeName, keyCodeName)
    if inputTypeName ~= nil and MOUSE[inputTypeName] ~= nil then
        return MOUSE[inputTypeName]
    end
    if keyCodeName == nil or keyCodeName == "" or keyCodeName == "Unknown" then
        return "NONE"
    end
    if SHORT[keyCodeName] ~= nil then
        return SHORT[keyCodeName]
    end
    return string.upper(keyCodeName)
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

local Field = require("core/field")
local safecall = require("util/safecall")

-- Resolved lazily: a module-scope game:GetService() executes on require, and
-- the harness requires this file to reach formatKey.
local UserInputService

local Keybind = {}
Keybind.__index = Keybind

local MODES = { "Always", "Hold", "Toggle" }
local MODE_WIDTH = 72
local MODE_HEIGHT = 16

local function isMouseBind(bind)
    return typeof(bind) == "EnumItem" and bind.EnumType == Enum.UserInputType
end

local function describe(bind)
    if bind == nil then return M.formatKey(nil, nil) end
    if isMouseBind(bind) then return M.formatKey(bind.Name, nil) end
    return M.formatKey(nil, bind.Name)
end

function M.new(root, row, opts)
    UserInputService = UserInputService or game:GetService("UserInputService")

    local theme = root.theme
    local field = Field.new(root, row.control, {})
    -- Right-aligned: a keybind is read as a value, like the slider's number,
    -- not as a caption.
    field.label.TextXAlignment = Enum.TextXAlignment.Right
    field.label.Size = UDim2.new(1, -8, 1, 0)

    --== the right-click mode menu, in the popup layer ==--
    local menu = Instance.new("Frame")
    menu.Name = "keybindModes"
    menu.Size = UDim2.fromOffset(MODE_WIDTH, MODE_HEIGHT * #MODES)
    menu.BorderSizePixel = 0
    menu.Visible = false
    menu.ZIndex = 10
    menu.Parent = root.popupLayer
    root:keep(menu)
    theme:bind(menu, "BackgroundColor3", "Window")

    local menuStroke = Instance.new("UIStroke")
    menuStroke.Thickness = 1
    menuStroke.Parent = menu
    theme:bind(menuStroke, "Color", "Accent")

    local menuLayout = Instance.new("UIListLayout")
    menuLayout.FillDirection = Enum.FillDirection.Vertical
    menuLayout.SortOrder = Enum.SortOrder.LayoutOrder
    menuLayout.Parent = menu

    local self = setmetatable({
        _root = root,
        _row = row,
        _theme = theme,
        _field = field,
        _menu = menu,
        _modeButtons = {},
        _bind = nil,
        _mode = "Always",
        _down = false,
        _toggled = false,
        _capturing = false,
        _label = opts.Name or "Keybind",
        _callback = opts.Callback,
        _listeners = {},
    }, Keybind)

    for i = 1, #MODES do
        local mode = MODES[i]
        local button = Instance.new("TextButton")
        button.Name = "mode_" .. mode
        button.Size = UDim2.new(1, 0, 0, MODE_HEIGHT)
        button.BackgroundTransparency = 1
        button.BorderSizePixel = 0
        button.Font = Enum.Font.Ubuntu
        button.TextSize = 11
        button.Text = mode
        button.AutoButtonColor = false
        button.LayoutOrder = i
        button.ZIndex = 11
        button.Parent = menu

        self._modeButtons[mode] = button

        root:keep(button.Activated:Connect(function()
            self:SetMode(mode)
            root.popup:close()
        end))
    end

    -- Activated fires on button release, and that matters: starting capture from
    -- InputBegan would let the very same MouseButton1 press reach the capture
    -- handler below and instantly bind MOUSE1.
    -- Binding a mouse button on the field consumes the press down in _capture,
    -- but its release still arrives as a click event on the field -- Activated
    -- for button 1, MouseButton2Click for button 2. Unguarded, binding MOUSE1
    -- flashed the bind and went straight back to listening, and binding MOUSE2
    -- popped the mode menu open. One press produces only one of the two events,
    -- so a single one-shot flag shared by both handlers is enough.
    local function swallowed()
        if self._swallowActivated then
            self._swallowActivated = false
            return true
        end
        return false
    end

    root:keep(field.frame.Activated:Connect(function()
        if swallowed() then return end
        self:_beginCapture()
    end))

    root:keep(field.frame.MouseButton2Click:Connect(function()
        if swallowed() then return end
        self:_openModeMenu()
    end))

    -- One InputBegan connection serving both capture and hold/toggle tracking.
    root:keep(UserInputService.InputBegan:Connect(function(input)
        if self._capturing then
            self:_capture(input)
            return
        end
        if not self:_matches(input) then return end
        self._down = true
        if self._mode == "Toggle" then
            self._toggled = not self._toggled
        end
    end))

    root:keep(UserInputService.InputEnded:Connect(function(input)
        if self:_matches(input) then
            self._down = false
        end
    end))

    self:SetMode(opts.Mode or "Always")
    self:Set(opts.Default, true)
    return self
end

function Keybind:_matches(input)
    local bind = self._bind
    if bind == nil then return false end
    if isMouseBind(bind) then
        return input.UserInputType == bind
    end
    return input.UserInputType == Enum.UserInputType.Keyboard
        and input.KeyCode == bind
end

function Keybind:_beginCapture()
    if self._capturing then return end
    self._capturing = true
    -- A global lock, not just a local flag: the window's toggle handler reads
    -- it. Without this, binding the menu's own toggle key would bind the key
    -- and close the menu in one press. The same applies to any key the game
    -- sinks, since the toggle deliberately ignores gameProcessedEvent.
    self._root.capturing = true
    self._field.setActive(true)
    self._field.label.Text = "..."
end

function Keybind:_endCapture()
    self._capturing = false
    self._field.setActive(false)
    self:_paint()
    -- Release the global lock a frame later. The window's toggle handler is a
    -- separate InputBegan connection and Roblox guarantees no ordering between
    -- them, so clearing it inside the same event could still let the key that
    -- was just bound close the menu.
    task.defer(function()
        if not self._root:isAlive() then return end
        self._root.capturing = false
    end)
end

function Keybind:_capture(input)
    if input.UserInputType == Enum.UserInputType.Keyboard then
        if input.KeyCode == Enum.KeyCode.Escape then
            self:Set(nil)   -- Escape clears the bind
        else
            self:Set(input.KeyCode)
        end
        self:_endCapture()
        return
    end

    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.MouseButton2
        or input.UserInputType == Enum.UserInputType.MouseButton3 then
        -- A mouse button binds only when the click lands ON the field. Anywhere
        -- else is "click away to cancel", which is the other half of the spec
        -- and would otherwise be unreachable for MOUSE1.
        local mx, my = self._root:mouseInGuiSpace()
        local p, s = self._field.frame.AbsolutePosition, self._field.frame.AbsoluteSize
        if mx >= p.X and mx <= p.X + s.X and my >= p.Y and my <= p.Y + s.Y then
            self:Set(input.UserInputType)
            -- This press will still deliver an Activated on release; that must
            -- not restart capture. See the Activated handler in M.new.
            self._swallowActivated = true
        end
        self:_endCapture()
        return
    end

    -- Anything else -- a wheel tick, a gamepad button, a touch -- matches
    -- neither branch above. Treat it as a cancel rather than falling through:
    -- an unhandled input type must not be able to leave _capturing (and the
    -- global root.capturing lock the window's toggle handler reads) stuck on,
    -- since that failure is silent and takes out the toggle key for the rest
    -- of the session. InputBegan never fires for mouse movement (that's
    -- InputChanged), so this cannot cancel capture on a pointer twitch.
    self:_endCapture()
end

function Keybind:_openModeMenu()
    local popup = self._root.popup
    if popup:isOpen(self) then
        popup:close()
        return
    end
    self:_paintModes()
    popup:open(self, self._menu, self._field.frame)
end

function Keybind:_paintModes()
    for i = 1, #MODES do
        local mode = MODES[i]
        local button = self._modeButtons[mode]
        self._theme:unbind(button)
        if mode == self._mode then
            self._theme:bind(button, "BackgroundColor3", "Selection", "BackgroundTransparency")
            self._theme:bind(button, "TextColor3", "Accent")
        else
            button.BackgroundTransparency = 1
            self._theme:bind(button, "TextColor3", "Text")
        end
    end
end

function Keybind:_paint()
    self._field.label.Text = describe(self._bind)
    self._theme:unbind(self._field.label)
    self._theme:bind(self._field.label, "TextColor3",
        self._bind == nil and "TextDim" or "Text")
end

function Keybind:_fire()
    safecall.call(self._label, self._callback, self._bind, self._mode)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], self._bind, self._mode)
    end
end

function Keybind:Get()
    return self._bind
end

function Keybind:Set(bind, silent)
    local changed = bind ~= self._bind
    self._bind = bind
    -- A cleared or replaced bind must not leave a Hold reading as held or a
    -- Toggle latched on.
    self._down = false
    self._toggled = false
    self:_paint()
    if silent or not changed then return end
    self:_fire()
end

function Keybind:GetMode()
    return self._mode
end

function Keybind:SetMode(mode)
    if mode ~= "Always" and mode ~= "Hold" and mode ~= "Toggle" then
        error("chroma: keybind Mode must be Always, Hold or Toggle, got "
            .. tostring(mode), 2)
    end
    self._mode = mode
    self._toggled = false
    self:_paintModes()
end

-- The extension to the shared four-method contract, and the only one in the
-- library. A consumer's aimbot reads this every frame, not Get.
function Keybind:IsHeld()
    if self._bind == nil then return false end
    if self._mode == "Always" then return true end
    if self._mode == "Toggle" then return self._toggled end
    return self._down
end

-- Get() returns only the bind, but the mode is state as well, so the config
-- manager takes both through Save/Load rather than widening the shared contract
-- for the two widgets that need it.
function Keybind:Save()
    return { bind = self._bind, mode = self._mode }
end

function Keybind:Load(t)
    if type(t) ~= "table" then return end
    if t.mode ~= nil then self:SetMode(t.mode) end
    self:Set(t.bind)
end

function Keybind:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function Keybind:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/label"] = function(require)
-- A single line of static text spanning the whole row.
--
-- Deliberately not wrappable. A wrapped label under-sizes its parent because
-- height only re-syncs when TextBounds fires, and inside an auto-sizing
-- container that clips the entire section. Two lines means two Labels.

local M = {}

-- Declared for the container: a Label has no control, so the row is built
-- full-width and no control slot is created. A widget must never resize the
-- row itself -- that is layout, and layout belongs to row.lua.
M.FullWidth = true

-- A label's text is presentation, not user state, so it takes no Flag and is
-- never written to a config.
M.Stateless = true

local Label = {}
Label.__index = Label

function M.new(root, row, opts)
    local theme = root.theme

    row.label.Text = opts.Text or ""
    row.label.TextTruncate = Enum.TextTruncate.AtEnd
    theme:unbind(row.label)
    theme:bind(row.label, "TextColor3", opts.Dim and "TextDim" or "Text")

    return setmetatable({ _row = row }, Label)
end

function Label:Get()
    return self._row.label.Text
end

function Label:Set(text)
    self._row.label.Text = tostring(text)
end

function Label:OnChanged()
    -- A label has no user-driven changes; accepted for contract symmetry.
end

function Label:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/listbox"] = function(require)
-- An inline bordered box of rows with one selected, scrolling past `Rows`.
--
-- Inline rather than a popup -- the difference from Dropdown. This is the
-- presets box from the gamesense reference, something you look at while doing
-- something else, not something you open and dismiss.

local safecall = require("util/safecall")

local M = {}

-- No control slot: a list of names needs the full width.
M.FullWidth = true

local ListBox = {}
ListBox.__index = ListBox

local ITEM_HEIGHT = 15
local DEFAULT_ROWS = 6

function M.new(root, row, opts)
    local theme = root.theme

    row.label.Text = ""

    local rows = opts.Rows or DEFAULT_ROWS
    if type(rows) ~= "number" or rows < 1 then rows = DEFAULT_ROWS end
    rows = math.floor(rows)

    -- The row's height is the box plus a 1px margin each side, so the box's
    -- outward-drawing stroke is not clipped by the container's padding.
    local boxHeight = rows * ITEM_HEIGHT
    row.setHeight(boxHeight + 2)

    local box = Instance.new("ScrollingFrame")
    box.Name = "listbox"
    box.Position = UDim2.fromOffset(0, 1)
    box.Size = UDim2.new(1, 0, 0, boxHeight)
    box.BorderSizePixel = 0
    box.CanvasSize = UDim2.new()
    -- The property is AutomaticCanvasSize, but its type is Enum.AutomaticSize.
    box.AutomaticCanvasSize = Enum.AutomaticSize.Y
    box.ScrollBarThickness = 2
    box.ScrollingDirection = Enum.ScrollingDirection.Y
    box.ElasticBehavior = Enum.ElasticBehavior.Never
    -- Above the row's own hit button (ZIndex 2), or the row swallows clicks and
    -- scrolling both.
    box.ZIndex = 3
    box.Parent = row.frame
    theme:bind(box, "BackgroundColor3", "Field")
    theme:bind(box, "ScrollBarImageColor3", "Accent")

    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Parent = box
    theme:bind(stroke, "Color", "FieldBorder")

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = box

    local self = setmetatable({
        _root = root,
        _row = row,
        _theme = theme,
        _box = box,
        _entries = {},
        _items = opts.Items or {},
        _value = nil,
        _label = opts.Name or "ListBox",
        _callback = opts.Callback,
        _listeners = {},
    }, ListBox)

    self:_rebuild()
    self:Set(opts.Default, true)
    return self
end

function ListBox:_has(value)
    for i = 1, #self._items do
        if self._items[i] == value then return true end
    end
    return false
end

function ListBox:_rebuild()
    local theme = self._theme
    for i = 1, #self._entries do
        local e = self._entries[i]
        -- Destroying an Instance does NOT remove its theme bindings: apply()
        -- would keep writing to a destroyed object every frame, and the binding
        -- list would grow without bound on every SetItems call.
        theme:unbind(e.button)
        theme:unbind(e.label)
        e.button:Destroy()
    end
    self._entries = {}

    for i = 1, #self._items do
        local text = self._items[i]

        local button = Instance.new("TextButton")
        button.Name = "item"
        button.Size = UDim2.new(1, 0, 0, ITEM_HEIGHT)
        button.BackgroundTransparency = 1
        button.BorderSizePixel = 0
        button.Text = ""
        button.AutoButtonColor = false
        button.LayoutOrder = i
        button.ZIndex = 4
        button.Parent = self._box

        local label = Instance.new("TextLabel")
        label.Name = "text"
        label.BackgroundTransparency = 1
        label.Position = UDim2.fromOffset(5, 0)
        label.Size = UDim2.new(1, -10, 1, 0)
        label.Font = Enum.Font.Ubuntu
        label.TextSize = 11
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextTruncate = Enum.TextTruncate.AtEnd
        label.Text = tostring(text)
        label.ZIndex = 5
        label.Parent = button

        self._entries[i] = { button = button, label = label, text = text }

        -- Tied to the button's own lifetime rather than root:keep: SetItems
        -- destroys and rebuilds these, and a keep per rebuild would grow the
        -- teardown list every time a consumer refreshes the list.
        button.Activated:Connect(function()
            self:Set(text)
        end)
    end

    self:_paint()
end

function ListBox:_paint()
    local theme = self._theme
    for i = 1, #self._entries do
        local e = self._entries[i]
        theme:unbind(e.button)
        theme:unbind(e.label)
        if e.text == self._value then
            theme:bind(e.button, "BackgroundColor3", "Selection", "BackgroundTransparency")
            theme:bind(e.label, "TextColor3", "Accent")
        else
            e.button.BackgroundTransparency = 1
            theme:bind(e.label, "TextColor3", "Text")
        end
    end
end

function ListBox:Get()
    return self._value
end

function ListBox:Set(value, silent)
    -- An unknown value is ignored rather than erroring: the usual caller is a
    -- config restore holding a preset that has since been deleted.
    if value ~= nil and not self:_has(value) then return end
    local changed = value ~= self._value
    self._value = value
    self:_paint()
    if silent or not changed then return end
    safecall.call(self._label, self._callback, value)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], value)
    end
end

-- Replaces the contents, keeping the selection if it survived.
function ListBox:SetItems(list)
    self._items = list or {}
    if self._value ~= nil and not self:_has(self._value) then
        self._value = nil
    end
    self:_rebuild()
end

function ListBox:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function ListBox:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/separator"] = function(require)
-- A 1px rule across the row, optionally with inline centred text.

local M = {}

-- No control slot: a separator spans the row. See label.lua for the rationale.
M.FullWidth = true

-- Nothing to persist: a separator has no value.
M.Stateless = true

local Separator = {}
Separator.__index = Separator

function M.new(root, row, opts)
    local theme = root.theme
    local text = opts.Text

    row.label.Text = ""
    row.setHeight(text and 16 or 9)

    local function rule(name)
        local line = Instance.new("Frame")
        line.Name = name
        line.AnchorPoint = Vector2.new(0, 0.5)
        line.Position = UDim2.new(0, 0, 0.5, 0)
        line.Size = UDim2.new(1, 0, 0, 1)
        line.BorderSizePixel = 0
        line.Parent = row.frame
        theme:bind(line, "BackgroundColor3", "ContainerBorder")
        return line
    end

    local obj = setmetatable({ _row = row }, Separator)

    if not text then
        rule("line")
        return obj
    end

    -- With text: two short rules either side of a centred caption.
    local left = rule("lineLeft")
    local right = rule("lineRight")

    local caption = Instance.new("TextLabel")
    caption.Name = "caption"
    caption.BackgroundTransparency = 1
    caption.AnchorPoint = Vector2.new(0.5, 0.5)
    caption.Position = UDim2.fromScale(0.5, 0.5)
    caption.Size = UDim2.new(0, 0, 1, 0)
    caption.AutomaticSize = Enum.AutomaticSize.X
    caption.Font = Enum.Font.Ubuntu
    caption.TextSize = 11
    caption.Text = " " .. text .. " "
    caption.ZIndex = 2
    caption.Parent = row.frame
    theme:bind(caption, "TextColor3", "TextDim")

    -- Size the rules once the caption has measured itself. AbsoluteSize is
    -- zero until a render pass has run, so a single deferred measurement is
    -- not enough -- if the row is still zero-width at that moment (e.g. a
    -- whole menu built before anything has rendered), half computes to 0 and
    -- both rules stay invisible forever, since nothing would re-measure.
    -- Instead, measure now and re-measure every time the row's actual width
    -- changes (first render, window resize, page switch), so it self-heals.
    local function measure()
        if not caption.Parent then return end
        local half = math.max(0, (row.frame.AbsoluteSize.X - caption.AbsoluteSize.X) / 2)
        left.Size = UDim2.new(0, half, 0, 1)
        right.Size = UDim2.new(0, half, 0, 1)
        right.AnchorPoint = Vector2.new(1, 0.5)
        right.Position = UDim2.new(1, 0, 0.5, 0)
    end

    measure()
    root:keep(row.frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(measure))

    return obj
end

function Separator:Get() return nil end
function Separator:Set() end
function Separator:OnChanged() end
function Separator:SetVisible(visible) self._row.frame.Visible = visible end

return M
end

__modules["widgets/slider"] = function(require)
-- Slider: the pure value/fraction maths, plus the 2px track.
-- The maths half is unit tested, so keep it in the Lua 5.4 / Luau intersection:
-- no compound assignment, no bitwise ops, no goto.

local M = {}

-- Where `value` sits on the track, as 0..1. Clamped, and safe when min == max.
function M.fractionOf(value, min, max)
    if max <= min then return 0 end
    local f = (value - min) / (max - min)
    if f < 0 then return 0 end
    if f > 1 then return 1 end
    return f
end

-- The value at 0..1 along the track, rounded to `decimals` places.
-- Note: `mult` is a float, so borderline values can round the "wrong" way
-- -- e.g. 0.145 at 2 decimals yields 0.14, since 0.145 * 100 + 0.5 evaluates
-- to 14.999999999999998 rather than 15. Fixing this needs decimal
-- arithmetic; not worth it for a slider label being one ulp out.
function M.valueAt(fraction, min, max, decimals)
    if fraction < 0 then fraction = 0 end
    if fraction > 1 then fraction = 1 end
    local raw = min + (max - min) * fraction
    -- Decimals is consumer-supplied, so normalise rather than trusting it:
    -- a negative value would invert the rounding and a fractional one would
    -- silently produce nonsense.
    decimals = math.floor(decimals or 0)
    if decimals < 0 then decimals = 0 end
    local mult = 10 ^ decimals
    -- floor(x + 0.5) rounds .5 up for positives and, for negatives, toward
    -- zero -- which is what a slider should do: dragging to the middle of
    -- -9..0 lands on -4, not -5.
    return math.floor(raw * mult + 0.5) / mult
end

function M.format(value, decimals, unit)
    -- Decimals is consumer-supplied, so normalise rather than trusting it: a
    -- negative or fractional value produces an invalid format specification
    -- and would throw at runtime.
    decimals = math.floor(decimals or 0)
    if decimals < 0 then decimals = 0 end
    local s = string.format("%." .. tostring(decimals) .. "f", value)
    if unit and unit ~= "" then s = s .. unit end
    return s
end

--== Instance side. Never runs under Lua 5.4; Luau syntax is fine here. ==--

local safecall = require("util/safecall")

-- Resolved lazily: a module-scope game:GetService() executes on require, and
-- the harness requires this file to reach the maths above.
local UserInputService

local Slider = {}
Slider.__index = Slider

local TRACK_WIDTH = 74
local TRACK_HEIGHT = 2
local KNOB_HEIGHT = 8
local HIT_HEIGHT = 19   -- the row height; a 2px track is impossible to grab

function M.new(root, row, opts)
    UserInputService = UserInputService or game:GetService("UserInputService")

    local min = opts.Min or 0
    local max = opts.Max or 100
    if min >= max then
        -- A programming mistake that can only produce a slider which never
        -- moves. Failing at build time is kinder than debugging it later.
        error(string.format(
            "chroma: slider '%s' has Min (%s) >= Max (%s)",
            tostring(opts.Name), tostring(min), tostring(max)), 2)
    end

    local theme = root.theme

    -- A TextBox rather than a TextLabel, kept non-editable until clicked, so
    -- typing an exact value needs no second element and nothing moves.
    local value = Instance.new("TextBox")
    value.Name = "value"
    value.AnchorPoint = Vector2.new(1, 0.5)
    value.Position = UDim2.new(1, 0, 0.5, 0)
    value.Size = UDim2.fromOffset(30, 12)
    value.BackgroundTransparency = 1
    value.Font = Enum.Font.Ubuntu
    value.TextSize = 11
    value.TextXAlignment = Enum.TextXAlignment.Right
    value.TextEditable = false
    value.ClearTextOnFocus = false
    value.Parent = row.control
    theme:bind(value, "TextColor3", "TextDim")

    local track = Instance.new("Frame")
    track.Name = "track"
    track.AnchorPoint = Vector2.new(1, 0.5)
    track.Position = UDim2.new(1, -34, 0.5, 0)
    track.Size = UDim2.fromOffset(TRACK_WIDTH, TRACK_HEIGHT)
    track.BorderSizePixel = 0
    track.Parent = row.control
    theme:bind(track, "BackgroundColor3", "FieldBorder")

    local fill = Instance.new("Frame")
    fill.Name = "fill"
    fill.Size = UDim2.fromScale(0, 1)
    fill.BorderSizePixel = 0
    fill.Parent = track
    theme:bind(fill, "BackgroundColor3", "Accent")

    local knob = Instance.new("Frame")
    knob.Name = "knob"
    knob.AnchorPoint = Vector2.new(0.5, 0.5)
    knob.Position = UDim2.fromScale(0, 0.5)
    knob.Size = UDim2.fromOffset(2, KNOB_HEIGHT)
    knob.BorderSizePixel = 0
    knob.ZIndex = 2
    knob.Parent = track
    theme:bind(knob, "BackgroundColor3", "Accent")

    -- A taller invisible button over the track: a 2px target is unusable, and
    -- this is also what makes click-to-jump land where you clicked. Its height
    -- is a constant, not read from AbsoluteSize, which is zero until the frame
    -- has rendered once.
    local hit = Instance.new("TextButton")
    hit.Name = "hit"
    hit.AnchorPoint = Vector2.new(0.5, 0.5)
    hit.Position = UDim2.fromScale(0.5, 0.5)
    hit.Size = UDim2.new(1, 8, 0, HIT_HEIGHT)
    hit.BackgroundTransparency = 1
    hit.Text = ""
    hit.AutoButtonColor = false
    hit.ZIndex = 3
    hit.Parent = track

    local self = setmetatable({
        _root = root,
        _row = row,
        _track = track,
        _fill = fill,
        _knob = knob,
        _value = value,
        _min = min,
        _max = max,
        _decimals = opts.Decimals or 0,
        _unit = opts.Unit,
        _label = opts.Name or "Slider",
        _callback = opts.Callback,
        _listeners = {},
        _current = min,
        _editing = false,
    }, Slider)

    local dragging = false

    local function applyFromMouse()
        local mx = root:mouseInGuiSpace()
        local left, width = track.AbsolutePosition.X, track.AbsoluteSize.X
        local fraction = width > 0 and (mx - left) / width or 0
        self:Set(M.valueAt(fraction, self._min, self._max, self._decimals))
    end

    --== typing an exact value ==--
    root:keep(value.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        if self._editing then return end
        self._editing = true
        value.TextEditable = true
        -- Edit the bare number: the unit is presentation, not something to type.
        value.Text = M.format(self._current, self._decimals, nil)
        theme:unbind(value)
        theme:bind(value, "TextColor3", "Text")
        value:CaptureFocus()
        -- Select the whole value so typing replaces it: the common case is
        -- entering a new number, not editing a digit of the old one.
        value.CursorPosition = #value.Text + 1
        value.SelectionStart = 1
    end))

    root:keep(value.FocusLost:Connect(function(enterPressed, inputThatCausedFocusLoss)
        self._editing = false
        value.TextEditable = false
        theme:unbind(value)
        theme:bind(value, "TextColor3", "TextDim")

        -- Escape must cancel, and it has to be handled explicitly. Roblox does
        -- not restore a TextBox's previous text before releasing focus --
        -- measured in-game: at FocusLost the box still held the typed value
        -- with cause=Escape. Relying on that would silently commit the edit,
        -- which is the opposite of cancelling.
        if inputThatCausedFocusLoss ~= nil
            and inputThatCausedFocusLoss.KeyCode == Enum.KeyCode.Escape then
            self:Set(self._current, true)
            return
        end

        -- Clicking away still commits, and a non-number is a cancel: Set
        -- re-renders the current value, formatted.
        local typed = tonumber(value.Text)
        if typed then self:Set(typed) else self:Set(self._current, true) end
    end))

    root:keep(hit.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            applyFromMouse()   -- click-to-jump
        end
    end))

    root:keep(UserInputService.InputChanged:Connect(function(input)
        -- A stray mouse move while typing would fight the text box for the value.
        if dragging and not self._editing and input.UserInputType == Enum.UserInputType.MouseMovement then
            applyFromMouse()
        end
    end))

    root:keep(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end))

    self:Set(opts.Default or min, true)
    return self
end

function Slider:Get()
    return self._current
end

function Slider:Set(v, silent)
    if type(v) ~= "number" then return end
    local rounded = M.valueAt(
        M.fractionOf(v, self._min, self._max), self._min, self._max, self._decimals)
    local changed = rounded ~= self._current
    self._current = rounded

    local fraction = M.fractionOf(rounded, self._min, self._max)
    self._fill.Size = UDim2.fromScale(fraction, 1)
    self._knob.Position = UDim2.fromScale(fraction, 0.5)
    -- Leave the text alone mid-edit, or a programmatic Set would overwrite
    -- what is being typed.
    if not self._editing then
        self._value.Text = M.format(rounded, self._decimals, self._unit)
    end

    if silent or not changed then return end
    safecall.call(self._label, self._callback, rounded)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], rounded)
    end
end

function Slider:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function Slider:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/textbox"] = function(require)
-- A click-to-edit text field in the control slot.
--
-- Non-editable until clicked, then selects its whole contents: the proven
-- pattern from the slider's value field, where nothing moves between the two
-- states and typing replaces rather than appends.

local Field = require("core/field")
local safecall = require("util/safecall")

local M = {}

local TextBox = {}
TextBox.__index = TextBox

function M.new(root, row, opts)
    local field = Field.new(root, row.control, {
        Editable = true,
        Placeholder = opts.Placeholder,
    })
    local box = field.label

    local self = setmetatable({
        _root = root,
        _row = row,
        _field = field,
        _box = box,
        _numeric = opts.Numeric == true,
        _value = "",
        _editing = false,
        _editStart = "",
        _label = opts.Name or "TextBox",
        _callback = opts.Callback,
        _listeners = {},
    }, TextBox)

    local function beginEdit()
        if self._editing then return end
        self._editing = true
        -- Captured so FocusLost can restore it explicitly on Escape, rather
        -- than trusting Roblox to have already put it back in box.Text.
        self._editStart = self._value
        box.TextEditable = true
        field.setActive(true)
        box:CaptureFocus()
        -- Select everything: the common case is replacing the value, not
        -- editing one character of it.
        box.CursorPosition = #box.Text + 1
        box.SelectionStart = 1
    end

    -- Listen on the box, not only the field around it. A TextBox takes focus
    -- natively when clicked even while TextEditable is false, and that click
    -- never reaches the parent button -- so the field's Activated never fired,
    -- TextEditable stayed false, and the box sat focused and selectable while
    -- silently swallowing every keystroke. Confirmed in-game: the keys arrived
    -- with gameProcessed true and the focused box was correct, but Text never
    -- changed. This is why the slider's value field listens on its own
    -- InputBegan rather than on a parent.
    root:keep(box.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            beginEdit()
        end
    end))

    -- The frame too, so clicking the padding either side of the text works.
    root:keep(field.frame.Activated:Connect(beginEdit))

    root:keep(box.FocusLost:Connect(function(enterPressed, inputThatCausedFocusLoss)
        self._editing = false
        box.TextEditable = false
        field.setActive(false)

        -- Whether Roblox restores the pre-edit text on Escape is not
        -- documented and not something to bet a revert on -- if it doesn't,
        -- this would silently COMMIT the edit instead, the opposite of the
        -- spec. Escape is therefore handled explicitly using the value
        -- captured when editing began. inputThatCausedFocusLoss may be nil
        -- (e.g. focus lost by clicking elsewhere), so it is guarded before
        -- indexing.
        if inputThatCausedFocusLoss ~= nil
            and inputThatCausedFocusLoss.KeyCode == Enum.KeyCode.Escape then
            box.Text = self._editStart
            return
        end

        local text = box.Text
        if self._numeric and tonumber(text) == nil then
            -- Rejected on commit rather than by filtering keystrokes: filtering
            -- fights paste and IME, and a half-typed "-" or "1e" is legitimate
            -- mid-edit. Unparseable input is user error at runtime, so it
            -- reverts silently rather than erroring.
            box.Text = self._value
            return
        end
        self:Set(text)
    end))

    self:Set(opts.Default or "", true)
    return self
end

-- A number when Numeric is set, the raw string otherwise.
function TextBox:Get()
    if self._numeric then return tonumber(self._value) end
    return self._value
end

function TextBox:Set(value, silent)
    local text = tostring(value)
    local changed = text ~= self._value
    self._value = text
    -- Leave the text alone mid-edit, or a programmatic Set would overwrite what
    -- is being typed.
    if not self._editing then
        self._box.Text = text
    end
    if silent or not changed then return end
    local out = self:Get()
    safecall.call(self._label, self._callback, out)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], out)
    end
end

function TextBox:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function TextBox:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

__modules["widgets/toggle"] = function(require)
-- A 7px checkbox in the row's control slot. Clicking anywhere on the row
-- flips it, which is far easier to hit than the box itself.

local safecall = require("util/safecall")

local M = {}

local Toggle = {}
Toggle.__index = Toggle

local BOX = 7

function M.new(root, row, opts)
    local theme = root.theme

    local box = Instance.new("Frame")
    box.Name = "box"
    box.AnchorPoint = Vector2.new(1, 0.5)
    box.Position = UDim2.new(1, 0, 0.5, 0)
    box.Size = UDim2.fromOffset(BOX, BOX)
    box.BorderSizePixel = 0
    box.Parent = row.control
    theme:bind(box, "BackgroundColor3", "Field")

    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Parent = box
    theme:bind(stroke, "Color", "FieldBorder")

    local self = setmetatable({
        _root = root,
        _row = row,
        _box = box,
        _stroke = stroke,
        _theme = theme,
        _label = opts.Name or "Toggle",
        _callback = opts.Callback,
        _listeners = {},
        _value = false,
    }, Toggle)

    -- Click anywhere on the row: a 7px target is unusable. The row owns the
    -- hit button (and its layering against the help icon), so ask for it
    -- rather than parenting one into row.frame ourselves.
    row.onActivated(function()
        self:Set(not self._value)
    end)

    self:Set(opts.Default == true, true)
    return self
end

function Toggle:_paint()
    -- Rebind rather than write directly, so the ON state keeps tracking the
    -- animated accent instead of freezing at the colour it had when clicked.
    self._theme:unbind(self._box)
    self._theme:unbind(self._stroke)
    if self._value then
        self._theme:bind(self._box, "BackgroundColor3", "Accent")
        self._theme:bind(self._stroke, "Color", "Accent")
    else
        self._theme:bind(self._box, "BackgroundColor3", "Field")
        self._theme:bind(self._stroke, "Color", "FieldBorder")
    end
end

function Toggle:Get()
    return self._value
end

function Toggle:Set(value, silent)
    value = value == true
    local changed = value ~= self._value
    self._value = value
    self:_paint()
    if silent or not changed then return end
    safecall.call(self._label, self._callback, value)
    for i = 1, #self._listeners do
        safecall.call(self._label, self._listeners[i], value)
    end
end

function Toggle:OnChanged(fn)
    table.insert(self._listeners, fn)
end

function Toggle:SetVisible(visible)
    self._row.frame.Visible = visible
end

return M
end

return __require("init")
